/** Błąd programu z pozycją (numeracja od 1). */
export interface LogoErrorInfo {
  message: string;
  line: number;
  column: number;
}

export class LogoError extends Error {
  constructor(
    message: string,
    public line: number,
    public column: number,
  ) {
    super(message);
  }
  info(): LogoErrorInfo {
    return { message: this.message, line: this.line, column: this.column };
  }
}
