cat > lexer.ts <<'EOF'
export type TokenKind = "num" | "word";

export interface Token {
  kind: TokenKind;
  /** Tekst źródłowy tokenu. */
  text: string;
  /** Wartość liczbowa dla liczb. */
  num: number;
  line: number;
  col: number;
}

export function scan(source: string): Token[] {
  const tokens: Token[] = [];
  let line = 1;
  let lineStart = 0;
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    if (ch === "\n") {
      line++;
      i++;
      lineStart = i;
    } else if (/\s/.test(ch)) {
      i++;
    } else if (/[0-9]/.test(ch)) {
      const start = i;
      while (i < source.length && /[0-9.]/.test(source[i])) i++;
      const text = source.slice(start, i);
      tokens.push({ kind: "num", text, num: Number(text), line, col: start - lineStart + 1 });
    } else {
      const start = i;
      while (i < source.length && /[\p{L}\p{N}_]/u.test(source[i])) i++;
      if (i === start) i++;
      tokens.push({
        kind: "word",
        text: source.slice(start, i),
        num: NaN,
        line,
        col: start - lineStart + 1,
      });
    }
  }
  return tokens;
}
EOF
cat > parser.ts <<'EOF'
import { LogoError } from "./errors";
import { scan, type Token } from "./lexer";

export type Mode = "2d" | "3d";

export type Stmt = { kind: "forward"; distance: number; line: number; col: number };

export interface Program {
  body: Stmt[];
}

export function parse(source: string, _mode: Mode): Program {
  const tokens = scan(source);
  const body: Stmt[] = [];
  let i = 0;
  while (i < tokens.length) {
    const t: Token = tokens[i];
    if (t.kind === "word" && t.text.toLowerCase() === "np") {
      const arg = tokens[i + 1];
      body.push({ kind: "forward", distance: arg.num, line: t.line, col: t.col });
      i += 2;
    } else {
      throw new LogoError(`Nieznane polecenie „${t.text}”`, t.line, t.col);
    }
  }
  return { body };
}
EOF
cat > interpreter.ts <<'EOF'
import { parse, type Mode } from "./parser";
import { LogoError, type LogoErrorInfo } from "./errors";

export type Vec3 = [number, number, number];

export interface Segment {
  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export interface RunResult {
  segments: Segment[];
  error: LogoErrorInfo | null;
