import type { Vec3 } from "./interpreter";

/** sin i cos kąta w stopniach; wielokrotności 90° są dokładne, by kwadrat był kwadratem. */
export function sinCosDeg(deg: number): [number, number] {
  const r = deg % 360;
  if (r % 90 === 0) {
    switch ((((r / 90) % 4) + 4) % 4) {
      case 0: return [0, 1];
      case 1: return [1, 0];
      case 2: return [0, -1];
      default: return [-1, 0];
    }
  }
  const rad = (r * Math.PI) / 180;
  return [Math.sin(rad), Math.cos(rad)];
}

const combine = (a: Vec3, ca: number, b: Vec3, cb: number): Vec3 => [
  a[0] * ca + b[0] * cb,
  a[1] * ca + b[1] * cb,
  a[2] * ca + b[2] * cb,
];

/** Pozycja i orientacja żółwia: kierunek (heading), prawa strona (right) i góra (up). */
export class Turtle {
  pos: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];

  /** Obrót w prawo wokół wektora „góra”. */
  yaw(deg: number): void {
    const [s, c] = sinCosDeg(deg);
    const h = combine(this.heading, c, this.right, s);
    const r = combine(this.right, c, this.heading, -s);
    this.heading = h;
    this.right = r;
  }
}
