/** Wyrażenia są kompilowane do postaci postfiksowej, więc ewaluacja nie zależy od głębokości drzewa. */
export type Instr =
  | { op: "num"; n: number }
  | { op: "add" | "sub" | "mul" | "div" };

export interface Expr {
  code: Instr[];
  /** Pozycja pierwszego tokenu wyrażenia (tu zgłaszane są błędy wartości). */
  line: number;
  col: number;
}

export function evaluate(expr: Expr): number {
  const stack: number[] = [];
  for (const ins of expr.code) {
    if (ins.op === "num") {
      stack.push(ins.n);
      continue;
    }
    const b = stack.pop()!;
    const a = stack.pop()!;
    switch (ins.op) {
      case "add": stack.push(a + b); break;
      case "sub": stack.push(a - b); break;
      case "mul": stack.push(a * b); break;
      case "div": stack.push(a / b); break;
    }
  }
  return stack[0];
}
