cat > lexer.ts <<'EOF'
export type TokenKind = "num" | "word" | "str" | "lbr" | "rbr" | "op" | "lpar" | "rpar";

export interface Token {
  kind: TokenKind;
  /** Tekst źródłowy tokenu. */
  text: string;
  /** Wartość liczbowa dla liczb. */
  num: number;
  line: number;
  col: number;
  /** Przesunięcie początku tokenu w tekście źródłowym. */
  start: number;
  /** Czy bezpośrednio przed / po tokenie stoi biały znak (lub początek / koniec tekstu). */
  wsBefore: boolean;
  wsAfter: boolean;
}

export function scan(source: string): Token[] {
  const tokens: Token[] = [];
  let line = 1;
  let lineStart = 0;
  let i = 0;
  const add = (kind: TokenKind, start: number, end: number, num = NaN) => {
    const isSpace = (k: number) => k < 0 || k >= source.length || /\s|;/.test(source[k]);
    tokens.push({
      kind,
      text: source.slice(start, end),
      num,
      line,
