import { parse, type Mode, type Stmt } from "./parser";
import { LogoError, type LogoErrorInfo } from "./errors";
import { evaluate, type Env } from "./expr";
import { Turtle } from "./turtle";

export type Vec3 = [number, number, number];

export interface Segment {
  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export interface RunResult {
  segments: Segment[];
  error: LogoErrorInfo | null;
}

export function run(source: string, mode: Mode): RunResult {
  const segments: Segment[] = [];
  try {
    const program = parse(source, mode);
    const turtle = new Turtle();
    const env: Env = { vars: new Map(), reps: [] };
    let penDown = true;
    let color = "#16866a";
    let width = 3;
    const moveTo = (to: Vec3) => {
      const from = turtle.pos;
      turtle.pos = to;
      const moved = from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2];
      if (penDown && moved) segments.push({ from, to, color, width });
    };
    const move = (d: number) => {
      const from = turtle.pos;
      const h = turtle.heading;
      moveTo([from[0] + h[0] * d, from[1] + h[1] * d, from[2] + h[2] * d]);
    };
    const exec = (body: Stmt[]): void => {
      const env = frames[frames.length - 1];
      for (const stmt of body) {
        if (stmt.kind === "let") {
          env.vars.set(stmt.name, evaluate(stmt.value, env));
          continue;
        }
        if (stmt.kind === "if") {
          const a = evaluate(stmt.left, env);
          const b = evaluate(stmt.right, env);
          const holds =
            stmt.cmp === "<" ? a < b
            : stmt.cmp === ">" ? a > b
            : stmt.cmp === "=" ? a === b
            : stmt.cmp === "<=" ? a <= b
            : stmt.cmp === ">=" ? a >= b
            : a !== b;
          if (holds) exec(stmt.then);
          else if (stmt.otherwise) exec(stmt.otherwise);
          continue;
        }
        if (stmt.kind === "repeat") {
          const count = evaluate(stmt.count, env);
          for (let n = 1; n <= count; n++) {
            env.reps.push(n);
            exec(stmt.body);
            env.reps.pop();
          }
          continue;
        }
        const value = stmt.value ? evaluate(stmt.value, env) : 0;
        switch (stmt.command) {
          case "forward": move(value); break;
          case "back": move(-value); break;
          case "right": turtle.yaw(value); break;
          case "left": turtle.yaw(-value); break;
          case "home":
            moveTo([0, 0, 0]);
            turtle.reset();
            break;
          case "pitchup": turtle.pitch(value); break;

