cd /work/src/lang && cat > parser.ts <<'EOF'
import { LogoError } from "./errors";
import { type Expr, type Instr } from "./expr";
import { scan, type Token } from "./lexer";
import { keywordOf, NO_ARGUMENT, SPATIAL, type Command, type Keyword } from "./vocab";

export type Mode = "2d" | "3d";

export type Stmt =
  | {
      kind: "command";
      command: Command;
      value: Expr | null;
      /** Kolor w formacie #rrggbb dla polecenia kolor. */
      color?: string;
      line: number;
      col: number;
    }
  | { kind: "let"; name: string; value: Expr; line: number; col: number }
  | {
      kind: "if";
      left: Expr;
      cmp: string;
      right: Expr;
      then: Stmt[];
      otherwise: Stmt[] | null;
      line: number;
      col: number;
    }
  | { kind: "repeat"; count: Expr; body: Stmt[]; line: number; col: number }
  | { kind: "call"; name: string; args: Expr[]; line: number; col: number };

export interface Procedure {
  name: string;
  params: string[];
  body: Stmt[];
}

export interface Program {
  procs: Map<string, Procedure>;
  body: Stmt[];
}

interface Header {
  name: string;
  params: string[];
  /** Indeks pierwszego tokenu po nagłówku. */
  next: number;
}

/** Czyta nagłówek procedury; `at` wskazuje token „oto”. */
function readHeader(tokens: Token[], at: number): Header {
  let i = at + 1;
  const name = tokens[i]?.name ?? "";
  i++;
  const params: string[] = [];
  while (tokens[i]?.kind === "colon" && tokens[i].line === tokens[at].line) {
    params.push(tokens[i].name);
    i++;
  }
  if (tokens[i]?.kind === "ma") {
    i++;
    if (tokens[i]) params.push(tokens[i].name);
    i++;
    while (tokens[i]?.kind === "comma") {
      i++;
      if (tokens[i]) params.push(tokens[i].name);
      i++;
    }
  }
  return { name, params, next: i };
}

/** Rodzaj tokenu do komunikatów o błędach. */
function describe(t: Token): string {
  switch (t.kind) {
    case "num": return `liczba „${t.text}”`;
    case "str": return `napis ${t.text}`;
    case "lbr": case "rbr": case "lpar": case "rpar": return `nawias „${t.text}”`;
    case "comma": return "przecinek";
    case "op": return `operator „${t.text}”`;
    case "cmp": return `operator porównania „${t.text}”`;
    case "colon": return `nazwa „${t.text}”`;
    default: return `„${t.text}”`;
  }
}

export function parse(source: string, mode: Mode): Program {
  const tokens = scan(source);
  let i = 0;
  const procs = new Map<string, Procedure>();
  // Sygnatury znamy z góry, więc procedury można wywoływać przed ich definicją.
  const arity = new Map<string, number>();
  tokens.forEach((t, k) => {
    if (t.kind === "word" && keywordOf(t.name)?.kind === "def") {
      const h = readHeader(tokens, k);
      if (!arity.has(h.name)) arity.set(h.name, h.params.length);
    }
  });

  const peek = (): Token | undefined => tokens[i];
  const kwOf = (t: Token | undefined): Keyword | undefined =>
    t?.kind === "word" ? keywordOf(t.name) : undefined;

  /** Błąd w tokenie `at`; gdy program się skończył, w tokenie `fallback`. */
  const fail = (message: string, at: Token | undefined, fallback: Token): never => {
    const t = at ?? fallback;
    throw new LogoError(message, t.line, t.col);
  };

  /** Operator jest dwuargumentowy tylko, gdy ma białe znaki po obu stronach albo po żadnej. */
  const isBinary = (...ops: string[]): boolean => {
    const t = peek();
    return t?.kind === "op" && ops.includes(t.text) && t.wsBefore === t.wsAfter;
  };

  /** `owner` to token, względem którego zgłaszamy brak argumentu, gdy program się kończy. */
  const parseExpr = (owner: Token): Expr => {
    const first = peek();
    const code: Instr[] = [];
    let last = owner;
    const primary = () => {
      let negate = false;
      while (peek()?.kind === "op" && (peek()!.text === "-" || peek()!.text === "+")) {
        if (peek()!.text === "-") negate = !negate;
        last = peek()!;
        i++;
      }
      const t = peek();
      if (t?.kind === "lpar") {
        i++;
        sum(t);
        if (peek()?.kind !== "rpar") fail("Brak zamykającego nawiasu „)”.", t, t);
        i++;
      } else if (t && kwOf(t)?.kind === "repcount") {
        code.push({ op: "rep" });
        i++;
      } else if (t && (t.kind === "num")) {
        code.push({ op: "num", n: t.num });
        i++;
      } else if (t && (t.kind === "colon" || (t.kind === "word" && !kwOf(t)))) {
        code.push({ op: "var", name: t.name });
        i++;
      } else {
        fail(
          t ? `Brakuje wartości: znaleziono ${describe(t)}.` : "Brakuje wartości na końcu programu.",
          t,
          last,
        );
      }
      if (negate) code.push({ op: "neg" });
    };
    const term = (from: Token) => {
      last = from;
      primary();
      while (isBinary("*", "/")) {
        const op = peek()!;
        i++;
        last = op;
        primary();
        code.push({ op: op.text === "*" ? "mul" : "div" });
      }
    };
    const sum = (from: Token) => {
      term(from);
      while (isBinary("+", "-")) {
        const op = peek()!;
        i++;
        term(op);
        code.push({ op: op.text === "+" ? "add" : "sub" });
      }
    };
    sum(owner);
    return { code, line: first!.line, col: first!.col };
  };

  /** Oczekuje tokenu danego rodzaju; `owner` służy do zgłoszenia końca programu. */
  const expectKind = (kind: Token["kind"], what: string, owner: Token): Token => {
    const t = peek();
    if (t?.kind !== kind) fail(`Oczekiwano ${what}${t ? `, a jest ${describe(t)}` : ""}.`, t, owner);
    i++;
    return t!;
  };

  const parseBracketBody = (owner: Token): Stmt[] => {
    const open = expectKind("lbr", "nawiasu „[”", owner);
    const body = parseBlock("rbr", open);
    i++; // ]
    return body;
  };

  const parseBlock = (until: "rbr" | "end" | null, opener: Token | null): Stmt[] => {
    const body: Stmt[] = [];
    for (;;) {
      const t = peek();
      if (!t) {
        if (until === "rbr") fail("Brak zamykającego nawiasu „]”.", opener!, opener!);
        return body;
      }
      const kw = kwOf(t);
      if (until === "rbr" && t.kind === "rbr") return body;
      if (until === "end" && kw?.kind === "end") return body;
      if (kw?.kind === "def") {
        const header = readHeader(tokens, i);
        i = header.next;
        const proc: Procedure = { name: header.name, params: header.params, body: [] };
        procs.set(proc.name, proc);
        proc.body = parseBlock("end", t);
        i++; // już
        continue;
      }
      if (t.kind === "word" && arity.has(t.name)) {
        i++;
        const args = Array.from({ length: arity.get(t.name)! }, () => parseExpr(t));
        body.push({ kind: "call", name: t.name, args, line: t.line, col: t.col });
        continue;
      }
      if (kw?.kind === "if" || kw?.kind === "ifelse") {
        i++;
        const left = parseExpr(t);
        const cmp = expectKind("cmp", "operatora porównania (<, >, =, <=, >=, <>)", t);
        const right = parseExpr(t);
        const then = parseBracketBody(t);
        const otherwise = kw.kind === "ifelse" ? parseBracketBody(t) : null;
        body.push({ kind: "if", left, cmp: cmp.text, right, then, otherwise, line: t.line, col: t.col });
        continue;
      }
      if (kw?.kind === "let") {
        i++;
        const nameTok = peek();
        if (!nameTok || nameTok.kind !== "word" || kwOf(nameTok)) {
          fail("Po „niech” powinna stać nazwa zmiennej.", nameTok, t);
        }
        i++;
        const value = parseExpr(t);
        body.push({ kind: "let", name: nameTok.name, value, line: t.line, col: t.col });
        continue;
      }
      if (kw?.kind === "repeat") {
        i++;
        const count = parseExpr(t);
        const inner = parseBracketBody(t);
        body.push({ kind: "repeat", count, body: inner, line: t.line, col: t.col });
        continue;
      }
      const command = kw?.kind === "command" ? kw.command : undefined;
      if (!command) {
        if (t.kind === "word" && !kw) throw new LogoError(`Nieznane polecenie „${t.text}”`, t.line, t.col);
        throw new LogoError(
          `Nieoczekiwany element: ${describe(t)}. W tym miejscu powinno stać polecenie.`,
          t.line,
          t.col,
        );
      }
      if (mode === "2d" && SPATIAL.has(command)) {
        throw new LogoError(
          `Polecenie „${t.text}” działa tylko w trybie 3D. Przełącz tryb na 3D, aby go użyć.`,
          t.line,
          t.col,
        );
      }
      i++;
      if (NO_ARGUMENT.has(command)) {
        body.push({ kind: "command", command, value: null, line: t.line, col: t.col });
      } else if (command === "color") {
        const arg = expectKind("str", "koloru w cudzysłowie, np. \"#16866a\"", t);
        body.push({
          kind: "command",
          command,
          value: null,
          color: arg.text.slice(1, -1).toLowerCase(),
          line: t.line,
          col: t.col,
        });
      } else {
        const value = parseExpr(t);
        body.push({ kind: "command", command, value, line: t.line, col: t.col });
      }
    }
  };

  return { procs, body: parseBlock(null, null) };
}
EOF
