import { describe, expect, test } from "bun:test";
import { run, startSession } from "../src/lang";

function started(src: string, mode: "2d" | "3d" = "2d") {
  const r = startSession(src, mode);
  if (!r.ok) throw new Error("oczekiwano sesji, jest błąd: " + r.error.message);
  return r.session;
}

describe("sesja krokowa", () => {
  test("każdy krok wykonuje jedno polecenie i zgłasza jego wiersz i kolumnę", () => {
    const s = started("np 10\n  pw 90\nnp 5");
    expect(s.step()).toEqual({ line: 1, column: 1 });
    expect(s.segments).toHaveLength(1);
    expect(s.step()).toEqual({ line: 2, column: 3 });
    expect(s.segments).toHaveLength(1);
    expect(s.turtle.heading).toEqual([1, 0, 0]);
    expect(s.step()).toEqual({ line: 3, column: 1 });
    expect(s.segments).toHaveLength(2);
    expect(s.done).toBe(false);
    expect(s.step()).toBeNull();
    expect(s.done).toBe(true);
    expect(s.error).toBeNull();
  });
  test("powtorz, jeśli i wywołanie to osobne kroki, a koniec obiegu nie jest krokiem", () => {
    const s = started("powtorz 2 [np 1]");
    const lines: Array<[number, number]> = [];
    for (let st = s.step(); st; st = s.step()) lines.push([st.line, st.column]);
    expect(lines).toEqual([[1, 1], [1, 12], [1, 12]]);
  });
  test("błąd czasu wykonania kończy sesję, zachowuje rysunek i jest dostępny w error", () => {
    const s = started("np 3\nnp 1 / 0\nnp 9");
    expect(s.step()).toEqual({ line: 1, column: 1 });
    expect(s.step()).toBeNull();
    expect(s.done).toBe(true);
    expect(s.error).toMatchObject({ line: 2, column: 4 });
    expect(s.segments).toHaveLength(1);
    expect(s.step()).toBeNull();
  });
  test("błąd parsowania nie tworzy sesji", () => {
    const r = startSession("np 3\nfoo", "2d");
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.error).toMatchObject({ line: 2, column: 1 });
  });
  test("czyść zwiększa epokę, by widok wiedział, że trzeba przerysować całość", () => {
    const s = started("np 3 czyść np 1");
    const e0 = s.epoch;
    s.step();
    expect(s.epoch).toBe(e0);
    s.step();
    expect(s.epoch).toBe(e0 + 1);
    expect(s.segments).toHaveLength(0);
  });
  test("zakończenie sesji krok po kroku daje to samo co run", () => {
    const src = "oto k ma: n\n powtorz n [np 10 pw 360 / n]\njuż\nk 5\nk 7";
    const s = started(src);
    while (s.step());
    expect({ segments: s.segments, error: s.error }).toEqual(run(src, "2d"));
  });
});
