cd /work/src/lang && cat > interpreter.ts <<'EOF'
import { LogoError, type LogoErrorInfo } from "./errors";
import { evaluate, type Env } from "./expr";
import {
  MAX_COORDINATE,
  MAX_FRAMES,
  MAX_OPERATIONS,
  MAX_SEGMENTS,
  repeatProblem,
  widthProblem,
} from "./limits";
import { parse, type Mode, type Program, type Stmt } from "./parser";
import { Turtle } from "./turtle";

export type Vec3 = [number, number, number];

export interface Segment {
  from: Vec3;
  to: Vec3;
  color: string;
  width: number;
}

export interface RunResult {
  segments: Segment[];
  error: LogoErrorInfo | null;
}

/** Pozycja właśnie wykonanego polecenia. */
export interface StepInfo {
  line: number;
  column: number;
}

export interface TurtleSnapshot {
  position: Vec3;
  heading: Vec3;
  right: Vec3;
  up: Vec3;
  penDown: boolean;
  color: string;
  width: number;
}

export interface Session {
  /** Odcinki narysowane (i niezapomniane przez czyść) do tej pory; tablica żywa. */
  readonly segments: Segment[];
  /** Zwiększa się przy czyść: widok musi wtedy przerysować wszystko. */
  readonly epoch: number;
  readonly turtle: TurtleSnapshot;
  readonly done: boolean;
  readonly error: LogoErrorInfo | null;
  /** Liczba wykonanych operacji (wg reguł limitu). */
  readonly ops: number;
  /** Wykonuje następne polecenie; zwraca null, gdy program się skończył lub wystąpił błąd. */
  step(): StepInfo | null;
}

export type StartResult = { ok: true; session: Session } | { ok: false; error: LogoErrorInfo };

/** Ustawienia tylko do testów granic limitów. */
export interface RunOptions {
  maxSegments?: number;
}

type Pos = { line: number; col: number };

class Machine implements Session {
  readonly segments: Segment[] = [];
  epoch = 0;
  done = false;
  error: LogoErrorInfo | null = null;
  ops = 0;

  private turtleState = new Turtle();
  private penDown = true;
  private color = "#16866a";
  private width = 3;
  private frames = 0;
  private readonly globals: Env = { vars: new Map(), globals: null, reps: [] };
  private readonly gen: Generator<StepInfo, void>;
  private readonly maxSegments: number;

  constructor(
    private readonly program: Program,
    options: RunOptions,
  ) {
    this.maxSegments = options.maxSegments ?? MAX_SEGMENTS;
    this.gen = this.main();
  }

  get turtle(): TurtleSnapshot {
    const t = this.turtleState;
    return {
      position: [...t.pos],
      heading: [...t.heading],
      right: [...t.right],
      up: [...t.up],
      penDown: this.penDown,
      color: this.color,
      width: this.width,
    };
  }

  step(): StepInfo | null {
    if (this.done) return null;
    try {
      const r = this.gen.next();
      if (!r.done) return r.value;
    } catch (e) {
      if (!(e instanceof LogoError)) throw e;
      this.error = e.info();
    }
    this.done = true;
    return null;
  }

  private charge(at: Pos): void {
    if (++this.ops > MAX_OPERATIONS) {
      throw new LogoError(`Przekroczono limit ${MAX_OPERATIONS} wykonanych operacji.`, at.line, at.col);
    }
  }

  private enterFrame(at: Pos): void {
    if (++this.frames > MAX_FRAMES) {
      throw new LogoError(
        `Przekroczono limit ${MAX_FRAMES} jednocześnie aktywnych wywołań procedur i powtórzeń.`,
