    const moved = from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2];
    if (this.penDown && moved) {
      if (this.segments.length >= this.maxSegments) {
        throw new LogoError(
          `Przekroczono limit ${this.maxSegments} odcinków w rysunku.`,
          at.line,
          at.col,
        );
      }
      this.segments.push({ from, to, color: this.color, width: this.width });
    }
    this.turtleState.pos = to;
  }

  private move(d: number, at: Pos): void {
    const from = this.turtleState.pos;
    const h = this.turtleState.heading;
    this.moveTo([from[0] + h[0] * d, from[1] + h[1] * d, from[2] + h[2] * d], at);
