  private *exec(body: Stmt[], env: Env): Generator<StepInfo, boolean> {
    for (const stmt of body) {
      this.charge(stmt);
      const info: StepInfo = { line: stmt.line, column: stmt.col };
      switch (stmt.kind) {
        case "call": {
          const proc = this.program.procs.get(stmt.name)!;
          const callEnv: Env = { vars: new Map(), globals: this.globals.vars, reps: [] };
          proc.params.forEach((p, k) => callEnv.vars.set(p, evaluate(stmt.args[k], env)));
