          env.vars.set(stmt.name, evaluate(stmt.value, env));
          yield info;
          break;
        case "if": {
          const a = evaluate(stmt.left, env);
          const b = evaluate(stmt.right, env);
          const holds =
            stmt.cmp === "<" ? a < b
            : stmt.cmp === ">" ? a > b
            : stmt.cmp === "=" ? a === b
            : stmt.cmp === "<=" ? a <= b
            : stmt.cmp === ">=" ? a >= b
            : a !== b;
          yield info;
          const chosen = holds ? stmt.then : stmt.otherwise;
          if (chosen) {
            if (yield* this.exec(chosen, env)) return true;
            this.charge(stmt);
          }
          break;
        }
        case "repeat": {
          const count = evaluate(stmt.count, env);
          const problem = repeatProblem(count);
          if (problem) throw new LogoError(problem, stmt.count.line, stmt.count.col);
          const outer = this.frames;
          this.enterFrame(stmt);
          yield info;
          for (let n = 1; n <= count; n++) {
            env.reps.push(n);
            const stopped = yield* this.exec(stmt.body, env);
            env.reps.pop();
            if (stopped) return true;
            this.charge(stmt);
          }
          this.frames = outer;
          break;
        }
        case "command": {
          const value = stmt.value ? evaluate(stmt.value, env) : 0;
          if (this.perform(stmt, value)) {
            yield info;
            return true;
          }
          yield info;
          break;
        }
      }
    }
    return false;
  }

  /** Wykonuje polecenie; zwraca true dla stop. */
  private perform(stmt: Extract<Stmt, { kind: "command" }>, value: number): boolean {
    const t = this.turtleState;
    switch (stmt.command) {
      case "forward": this.move(value, stmt); break;
      case "back": this.move(-value, stmt); break;
      case "right": t.yaw(value); break;
      case "left": t.yaw(-value); break;
      case "pitchup": t.pitch(value); break;
      case "pitchdown": t.pitch(-value); break;
      case "rollright": t.roll(value); break;
      case "rollleft": t.roll(-value); break;
      case "home":
