}

/** Parsuje program i przygotowuje sesję krokową; błąd parsowania nie tworzy sesji. */
export function startSession(source: string, mode: Mode, options: RunOptions = {}): StartResult {
  let program: Program;
  try {
    program = parse(source, mode);
  } catch (e) {
    if (e instanceof LogoError) return { ok: false, error: e.info() };
    throw e;
  }
  return { ok: true, session: new Machine(program, options) };
}

/** Wykonuje cały program bez animacji. */
export function run(source: string, mode: Mode, options: RunOptions = {}): RunResult {
  const started = startSession(source, mode, options);
  if (!started.ok) return { segments: [], error: started.error };
  const { session } = started;
  while (session.step());
  return { segments: session.segments, error: session.error };
}
