import { describe, expect, test } from "bun:test";
import { run } from "../src/lang";

// Deterministyczny generator (mulberry32), by test był powtarzalny.
function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const pieces = [
  "np", "ws", "pw", "lw", "pod", "opu", "kolor", "grubosc", "powtorz", "niech", "jeśli", "jeżeli",
  "stop", "dom", "czyść", "gora", "dol", "pp", "pl", "oto", "już", "ma:", "nrpowt", "x", "y", "f", "g",
  "0", "1", "5", "90", "12.5", ".5", "1e3", "-", "+", "*", "/", "(", ")", "[", "]", ",", "<", ">", "=",
  "<=", ">=", "<>", ":x", '"#16866a"', '"zly"', '"', "#", "\n", "\n", " ", ";", "ą", "$",
];

describe("odporność parsera i interpretera", () => {
  test("losowe programy nigdy nie zrywają działania: wynik to rysunek lub błąd z pozycją i polskim opisem", () => {
    const rand = rng(20240607);
    for (let n = 0; n < 4000; n++) {
      const len = 1 + Math.floor(rand() * 25);
      let src = "";
      for (let k = 0; k < len; k++) src += pieces[Math.floor(rand() * pieces.length)] + (rand() < 0.8 ? " " : "");
      for (const mode of ["2d", "3d"] as const) {
        let r;
        try {
          r = run(src, mode);
        } catch (e) {
          throw new Error(`run zgłosił wyjątek dla ${JSON.stringify(src)}: ${e}`);
        }
        if (r.error) {
          expect(r.error.line).toBeGreaterThanOrEqual(1);
          expect(r.error.column).toBeGreaterThanOrEqual(1);
          expect(r.error.message.length).toBeGreaterThan(3);
        } else {
          expect(Array.isArray(r.segments)).toBe(true);
        }
      }
    }
  });
  test("błąd parsowania zawsze daje pusty rysunek, a błąd wykonania tylko to, co narysowano przed nim", () => {
    const rand = rng(7);
    for (let n = 0; n < 1500; n++) {
      let src = "";
      for (let k = 0; k < 12; k++) src += pieces[Math.floor(rand() * pieces.length)] + " ";
      const r = run(src, "3d");
      for (const s of r.segments) {
        expect(s.from).toHaveLength(3);
        expect(s.to.every(Number.isFinite)).toBe(true);
        expect(s.color).toMatch(/^#[0-9a-f]{6}$/);
        expect(Number.isInteger(s.width) && s.width >= 1 && s.width <= 12).toBe(true);
      }
    }
  });
});
