cd /work/src/lang && cat > highlight.ts <<'EOF'
import { scan, type Token } from "./lexer";
import { keywordOf } from "./vocab";

export type SpanKind =
  | "command"
  | "procedure"
  | "name"
  | "number"
  | "string"
  | "comment"
  | "bracket"
  | "operator"
  | "invalid";

export interface Span {
  start: number;
  end: number;
  kind: SpanKind;
}

function kindOf(t: Token, procedures: Set<string>): SpanKind {
  switch (t.kind) {
    case "num": return "number";
    case "str": return "string";
    case "lbr": case "rbr": case "lpar": case "rpar": return "bracket";
    case "op": case "cmp": case "comma": return "operator";
    case "bad": return "invalid";
    case "ma": return "command";
    case "colon": return "name";
    case "word":
      if (keywordOf(t.name)) return "command";
      return procedures.has(t.name) ? "procedure" : "name";
  }
}

/** Zakresy do podświetlenia; używa tego samego leksera co interpreter, więc kolory zgadzają się ze znaczeniem. */
export function highlight(source: string): Span[] {
  const tokens = scan(source);
  const procedures = new Set<string>();
  tokens.forEach((t, k) => {
    const next = tokens[k + 1];
    if (t.kind === "word" && keywordOf(t.name)?.kind === "def" && next?.kind === "word" && next.line === t.line) {
      procedures.add(next.name);
    }
  });

  const spans: Span[] = [];
  const addComments = (from: number, to: number) => {
    for (let i = from; i < to; i++) {
      if (source[i] !== ";") continue;
      let end = source.indexOf("\n", i);
      if (end < 0 || end > to) end = Math.min(source.length, to);
      spans.push({ start: i, end, kind: "comment" });
      i = end;
    }
  };
  let pos = 0;
  for (const t of tokens) {
    addComments(pos, t.start);
    spans.push({ start: t.start, end: t.start + t.text.length, kind: kindOf(t, procedures) });
    pos = t.start + t.text.length;
  }
  addComments(pos, source.length);
  return spans;
}
EOF
