cat > app/controller.ts <<'EOF'
import {
  initialTurtle,
  startSession,
  type LogoErrorInfo,
  type Mode,
  type Segment,
  type Session,
  type TurtleSnapshot,
} from "../lang";

export type Status = "idle" | "running" | "paused" | "finished" | "failed";

export interface ControllerState {
  status: Status;
  mode: Mode;
  /** Program, który ma być uruchomiony (ostatnio ustawiony). */
  source: string;
  segments: readonly Segment[];
  /** Zwiększa się, gdy widok musi przerysować rysunek od zera. */
  epoch: number;
  turtle: TurtleSnapshot;
  /** Wiersz i kolumna ostatnio wykonanego polecenia (null, gdy nic nie jest wykonywane). */
  line: number | null;
  column: number | null;
  error: LogoErrorInfo | null;
  ops: number;
}

export interface Controller {
  readonly state: ControllerState;
  setProgram(source: string, mode: Mode): void;
  step(): void;
  subscribe(listener: (state: ControllerState) => void): () => void;
}

export function createController(): Controller {
  let source = "";
  let mode: Mode = "2d";
  let session: Session | null = null;
  let status: Status = "idle";
  let line: number | null = null;
  let column: number | null = null;
  let error: LogoErrorInfo | null = null;
  let epochBase = 0;
  const listeners = new Set<(s: ControllerState) => void>();

  const snapshot = (): ControllerState => ({
    status,
    mode,
    source,
    segments: session ? session.segments : [],
    epoch: epochBase + (session?.epoch ?? 0),
    turtle: session ? session.turtle : initialTurtle(),
    line,
    column,
    error,
    ops: session?.ops ?? 0,
  });

  const controller: Controller = {
    get state() {
      return snapshot();
    },
    setProgram(newSource, newMode) {
      source = newSource;
      mode = newMode;
    },
    step() {
      if (!session) {
        const started = startSession(source, mode);
        if (!started.ok) return;
        session = started.session;
      }
      const info = session.step();
      if (info) {
        line = info.line;
        column = info.column;
        status = "paused";
      } else {
        line = column = null;
        status = "finished";
      }
