cd /work/src/app && python3 - <<'EOF'
p='controller.ts'
s=open(p).read()
s=s.replace('''  run(): void;
  step(): void;''','''  run(): void;
  /** Wykonuje cały program od razu (bez animacji), niezależnie od szybkości. */
  runToEnd(): void;
  step(): void;''')
a=s.index('  const controller: Controller = {')
new_ctrl='''  const emit = () => {
    const s = snapshot();
    for (const l of [...listeners]) l(s);
  };

  const controller: Controller = {
    get state() {
      return snapshot();
    },
    setProgram(newSource, newMode) {
      const changed = newSource !== source || newMode !== mode;
      source = newSource;
      mode = newMode;
      if (!changed) return;
      // Edycja unieważnia trwające wykonanie i stary błąd; rysunek zostaje jako nieaktualny.
      status = "idle";
      line = column = null;
      error = null;
      budget = 0;
      emit();
    },
    setSpeed(opsPerSecond) {
      speed = opsPerSecond;
    },
    run() {
      if (status === "running") return;
      if (status === "paused" && session) {
        status = "running";
        emit();
        return;
      }
      if (begin()) status = "running";
      emit();
    },
    runToEnd() {
      if (!begin()) {
        emit();
        return;
      }
      advance(Infinity);
      emit();
    },
    step() {
      if (status === "finished" || status === "failed") return;
      if (status === "idle" && !begin()) {
        emit();
        return;
      }
      advance(1);
      if (status === "running") status = "paused";
      emit();
    },
    reset() {
      if (status === "idle" && !session && !error) return;
      epochBase += (session?.epoch ?? 0) + 1;
      session = null;
      budget = 0;
      status = "idle";
      line = column = null;
      error = null;
      emit();
    },
    pause() {
      if (status !== "running") return;
      status = "paused";
      emit();
    },
    resume() {
      if (status !== "paused" || !session) return;
      status = "running";
      emit();
    },
    tick(dtMs) {
      if (status !== "running" || !session) return;
      if (speed === Infinity) {
        advance(Infinity);
        emit();
        return;
      }
      budget += (dtMs * speed) / 1000;
      const whole = Math.floor(budget);
      if (whole < 1) return;
      budget -= whole;
      advance(whole);
      emit();
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
  return controller;
}
'''
s=s[:a]+new_ctrl
open(p,'w').write(s)
