    resume() {
      if (status !== "paused" || !session) return;
      status = "running";
      emit();
    },
    tick(dtMs) {
      if (status !== "running" || !session) return;
      if (speed === Infinity) {
        advance(Infinity);
        emit();
        return;
      }
      budget += (dtMs * speed) / 1000;
      const whole = Math.floor(budget);
      if (whole < 1) return;
      budget -= whole;
      advance(whole);
      emit();
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
  return controller;
