/** Minimalny magazyn klucz–wartość (zgodny z localStorage). */
export interface KeyValueStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export function createMemoryStore(initial: Record<string, string> = {}): KeyValueStore {
  const map = new Map(Object.entries(initial));
  return {
    getItem: (k) => map.get(k) ?? null,
    setItem: (k, v) => void map.set(k, String(v)),
    removeItem: (k) => void map.delete(k),
  };
}

/**
 * Magazyn przeglądarki. Gdy localStorage jest zablokowany (tryb prywatny, polityka przeglądarki),
 * aplikacja nadal działa na pamięci tymczasowej.
 */
export function createBrowserStore(): KeyValueStore {
  try {
    const ls = globalThis.localStorage;
    const probe = "logomocja:v1:probe";
    ls.setItem(probe, "1");
    ls.removeItem(probe);
    return ls;
  } catch {
    return createMemoryStore();
  }
}

/** Odczyt bez wyjątków. */
export function safeGet(store: KeyValueStore, key: string): string | null {
  try {
    return store.getItem(key);
  } catch {
    return null;
  }
}

/** Zapis bez wyjątków; zwraca false, gdy się nie udał. */
export function safeSet(store: KeyValueStore, key: string, value: string): boolean {
  try {
    store.setItem(key, value);
    return true;
  } catch {
    return false;
  }
}

export function safeRemove(store: KeyValueStore, key: string): void {
  try {
    store.removeItem(key);
  } catch {
    /* ignorujemy */
  }
}
