import type { Mode } from "../lang";
import { exampleById } from "./examples";
import { safeGet, safeSet, type KeyValueStore } from "./storage";

const KEY_MODE = "logomocja:v1:mode";
const keyDraft = (mode: Mode) => `logomocja:v1:draft:${mode}`;

const DEFAULT_EXAMPLE: Record<Mode, string> = { "2d": "kwadrat", "3d": "schody" };

export interface Workspace {
  readonly mode: Mode;
  /** Tekst programu w aktualnym trybie. */
  readonly source: string;
  setSource(text: string): void;
  setMode(mode: Mode): void;
}

export function createWorkspace(store: KeyValueStore): Workspace {
  const storedMode = safeGet(store, KEY_MODE);
  let mode: Mode = storedMode === "3d" ? "3d" : "2d";
  const drafts: Record<Mode, string> = {
    "2d": safeGet(store, keyDraft("2d")) ?? exampleById(DEFAULT_EXAMPLE["2d"])!.source,
    "3d": safeGet(store, keyDraft("3d")) ?? exampleById(DEFAULT_EXAMPLE["3d"])!.source,
  };

  return {
    get mode() {
      return mode;
    },
    get source() {
      return drafts[mode];
    },
    setSource(text) {
      drafts[mode] = text;
      safeSet(store, keyDraft(mode), text);
    },
    setMode(next) {
      mode = next;
      safeSet(store, KEY_MODE, next);
    },
  };
}
