export type Route =
  | { page: "workspace" }
  | { page: "examples" }
  | { page: "challenges"; id?: string }
  | { page: "docs"; id?: string };

/**
 * Trasy w hashu (#/…): odświeżenie działa bez reguł przepisywania na serwerze
 * i pod dowolną ścieżką bazową.
 */
export function parseRoute(hash: string): Route {
  const path = hash.replace(/^#/, "").split("?")[0];
  const [, page, id] = path.split("/");
  const rawId = id ? safeDecode(id) : undefined;
  switch (page) {
    case "przyklady": return { page: "examples" };
    case "wyzwania": return rawId ? { page: "challenges", id: rawId } : { page: "challenges" };
    case "dokumentacja": return rawId ? { page: "docs", id: rawId } : { page: "docs" };
    default: return { page: "workspace" };
  }
}

export function formatRoute(route: Route): string {
  switch (route.page) {
    case "workspace": return "#/pracownia";
    case "examples": return "#/przyklady";
    case "challenges": return route.id ? `#/wyzwania/${encodeURIComponent(route.id)}` : "#/wyzwania";
    case "docs": return route.id ? `#/dokumentacja/${encodeURIComponent(route.id)}` : "#/dokumentacja";
  }
}

function safeDecode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}
