import type { Mode } from "../lang";

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromBase64Url(payload: string): string | null {
  if (!/^[A-Za-z0-9_-]*$/.test(payload)) return null;
  try {
    const binary = atob(payload.replace(/-/g, "+").replace(/_/g, "/"));
    const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

/** Fragment adresu (#/pracownia?tryb=…&kod=…), który koduje program i tryb. */
export function shareHash(source: string, mode: Mode): string {
  return `#/pracownia?tryb=${mode}&kod=${toBase64Url(source)}`;
}

/** Odczytuje program i tryb z fragmentu adresu; null, gdy to nie jest poprawny link. */
export function decodeShare(hash: string): { source: string; mode: Mode } | null {
  const m = /^#\/pracownia\?(.*)$/.exec(hash);
  if (!m) return null;
  const params = new URLSearchParams(m[1]);
  const mode = params.get("tryb");
  const code = params.get("kod");
  if ((mode !== "2d" && mode !== "3d") || code === null) return null;
  const source = fromBase64Url(code);
  return source === null ? null : { source, mode };
}
