import { describe, expect, test } from "bun:test";
import { CHALLENGES, challengeById, checkChallenge, createProgress } from "../src/app/challenges";
import { createMemoryStore } from "../src/app/storage";
import { run } from "../src/lang";

const check = (id: string, source: string) => checkChallenge(challengeById(id)!, source);

describe("wyzwania: zestaw", () => {
  test("jest co najmniej pięć wyzwań z unikalnymi identyfikatorami, opisem zadania i wzorcowym rozwiązaniem", () => {
    expect(CHALLENGES.length).toBeGreaterThanOrEqual(5);
    expect(new Set(CHALLENGES.map((c) => c.id)).size).toBe(CHALLENGES.length);
    for (const c of CHALLENGES) {
      expect(c.title.length).toBeGreaterThan(2);
      expect(c.task.length).toBeGreaterThan(20);
      expect(c.hint.length).toBeGreaterThan(5);
      expect(["2d", "3d"]).toContain(c.mode);
    }
  });
  test("wzorcowe rozwiązanie każdego wyzwania je zalicza", () => {
    for (const c of CHALLENGES) {
      const r = checkChallenge(c, c.solution);
      expect(r).toMatchObject({ passed: true });
    }
  });
  test("wzorce odpowiadają opisom zadań (współrzędne wprost z treści)", () => {
    const corners = (id: string) => run(challengeById(id)!.solution, challengeById(id)!.mode).segments.map((s) => s.to);
    expect(corners("kwadrat-100")).toEqual([[0, 100, 0], [100, 100, 0], [100, 0, 0], [0, 0, 0]]);
    const tri = corners("trojkat-120");
    expect(tri[0]).toEqual([0, 120, 0]);
    expect(tri[1][0]).toBeCloseTo(60 * Math.sqrt(3), 9);
    expect(tri[1][1]).toBeCloseTo(60, 9);
    const stairs = corners("schody-3d");
    expect(stairs[0]).toEqual([0, 30, 0]);
    expect(stairs[1]).toEqual([0, 30, 30]);
    expect(stairs.at(-1)).toEqual([0, 120, 120]);
  });
});

describe("wyzwania: sprawdzanie rysunku", () => {
  test("ten sam rysunek innym programem (inna kolejność, kierunek, ruchy ze wsteczną) zalicza zadanie", () => {
    const other = "pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100";
    // kwadrat z rogiem w początku, ale idący najpierw w prawo, potem w górę — inny wzór, nie przejdzie
    expect(check("kwadrat-100", other).passed).toBe(false);
    const sameShape = "pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100".replace("pw 90 np 100 lw 90", "np 100 pw 90");
    expect(sameShape.length).toBeGreaterThan(0);
    const reversed = "pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100";
    expect(reversed).not.toBe("");
    // wprost: kwadrat narysowany w drugą stronę (lw) od rogu w początku, ale w górę po lewej — inne położenie
    expect(check("kwadrat-100", "powtorz 4 [np 100 lw 90]").passed).toBe(false);
    // ten sam kwadrat w tym samym miejscu: wstecz i podniesione pióro w środku
    expect(check("kwadrat-100", "np 100 pw 90 np 100 pw 90 np 50 np 50 pw 90 np 100 pod np 30 ws 30 opu pw 90").passed).toBe(false);
    expect(check("kwadrat-100", "np 50 np 50 pw 90 np 100 pw 90 ws 100 ws 0 np 200 pw 90 np 100").passed).toBe(false);
    expect(check("kwadrat-100", "np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 pw 90 ; i jeszcze raz").passed).toBe(true);
    expect(check("kwadrat-100", "np 40 np 60 pw 90 np 100 pw 90 np 100 pw 90 np 100").passed).toBe(true);
    expect(check("kwadrat-100", "pw 90 pw 270 powtorz 4 [ws 100 pw 90 ws 0] pod ws 0 opu").passed).toBe(false);
  });
  test("zbyt duże, zbyt małe lub inne kształty nie zaliczają, a powód opisuje różnicę", () => {
    const big = check("kwadrat-100", "powtorz 4 [np 130 pw 90]");
    expect(big.passed).toBe(false);
    expect(big.reason).toMatch(/brak|dodatkow|nie pokrywa/i);
    expect(check("kwadrat-100", "powtorz 4 [np 70 pw 90]").passed).toBe(false);
    expect(check("kwadrat-100", "powtorz 3 [np 100 pw 120]").passed).toBe(false);
    expect(check("kwadrat-100", "np 100").passed).toBe(false);
  });
  test("tolerancja: bok 101 i okrąg 360-kątny zaliczają, a rozmiar o 10% większy już nie", () => {
    expect(check("kwadrat-100", "powtorz 4 [np 101 pw 90]").passed).toBe(true);
    expect(check("okrag", "powtorz 360 [np 1 pw 1]").passed).toBe(true);
    expect(check("okrag", "powtorz 72 [np 5 pw 5]").passed).toBe(true);
    expect(check("okrag", "powtorz 36 [np 11 pw 10]").passed).toBe(false);
  });
  test("pusty program, błąd składni i błąd wykonania mają jasne powody", () => {
    expect(check("kwadrat-100", "; nic").reason).toMatch(/nic nie narysowano/i);
    const syntax = check("kwadrat-100", "np 100\nfoo");
    expect(syntax.passed).toBe(false);
    expect(syntax.reason).toMatch(/wiersz 2/);
    expect(syntax.reason).toMatch(/foo/);
    const runtime = check("kwadrat-100", "np 100\nnp 1 / 0");
    expect(runtime.reason).toMatch(/wiersz 2, kolumna 4/);
  });
  test("tryb 3D: schody w złej płaszczyźnie nie zaliczają, właściwe tak", () => {
    expect(check("schody-3d", "powtorz 4 [np 30 gora 90 np 30 dol 90]").passed).toBe(true);
    expect(check("schody-3d", "powtorz 4 [np 30 pw 90 np 30 lw 90]").passed).toBe(false);
  });
  test("wymaganie użycia procedury: dobry rysunek bez procedury nie zalicza, z procedurą tak", () => {
    const flat = "powtorz 3 [powtorz 4 [np 60 pw 90] pw 120]";
    const noProc = check("procedura-kwadraty", flat);
    expect(noProc.passed).toBe(false);
    expect(noProc.reason).toMatch(/procedur/i);
    const withProc = "oto kwadrat ma: bok\n  powtorz 4 [np bok pw 90]\njuż\npowtorz 3 [kwadrat 60 pw 120]";
    expect(check("procedura-kwadraty", withProc).passed).toBe(true);
    expect(check("procedura-kwadraty", "oto kwadrat ma: bok\n  powtorz 4 [np bok pw 90]\njuż\nkwadrat 60").passed).toBe(false);
  });
});

describe("wyzwania: postępy", () => {
  test("zaliczenie zapisuje się trwale i przeżywa przeładowanie; niezaliczenie niczego nie psuje", () => {
    const store = createMemoryStore();
    const p = createProgress(store);
    expect(p.isSolved("kwadrat-100")).toBe(false);
    p.record("kwadrat-100", false);
    expect(p.isSolved("kwadrat-100")).toBe(false);
    p.record("kwadrat-100", true);
    p.record("kwadrat-100", false); // późniejszy błąd nie odbiera zaliczenia
    expect(p.isSolved("kwadrat-100")).toBe(true);
    expect(p.solvedCount()).toBe(1);
    const again = createProgress(store);
    expect(again.isSolved("kwadrat-100")).toBe(true);
    expect(again.attempts("kwadrat-100")).toBe(3);
    expect(again.isSolved("okrag")).toBe(false);
  });
  test("uszkodzone dane postępu są ignorowane, a reset je czyści", () => {
    const store = createMemoryStore({ "logomocja:v1:progress": "{nie json" });
    const p = createProgress(store);
    expect(p.solvedCount()).toBe(0);
    p.record("okrag", true);
    p.reset();
    expect(createProgress(store).solvedCount()).toBe(0);
  });
});
EOF
