import type { Segment, Vec3 } from "../lang";

export interface DrawingMatch {
  ok: boolean;
  /** Jaka część wzoru jest pokryta rysunkiem (0–1). */
  coverage: number;
  /** Jaka część rysunku leży na wzorze (0–1). */
  precision: number;
  /** Przykładowy punkt wzoru, którego brakuje w rysunku. */
  missing: Vec3 | null;
  /** Przykładowy punkt rysunku, którego nie ma we wzorze. */
  extra: Vec3 | null;
}

const THRESHOLD = 0.97;

function extentOf(segments: readonly Segment[]): number {
  let min = [Infinity, Infinity, Infinity];
  let max = [-Infinity, -Infinity, -Infinity];
  for (const s of segments) {
    for (const p of [s.from, s.to]) {
      for (let k = 0; k < 3; k++) {
        min[k] = Math.min(min[k], p[k]);
        max[k] = Math.max(max[k], p[k]);
      }
    }
  }
  return segments.length ? Math.max(max[0] - min[0], max[1] - min[1], max[2] - min[2]) : 0;
}

function samples(segments: readonly Segment[], step: number): Vec3[] {
  const out: Vec3[] = [];
  for (const s of segments) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.min(400, Math.max(1, Math.ceil(len / step)));
    for (let k = 0; k <= n; k++) {
      const t = k / n;
      out.push([
        s.from[0] + (s.to[0] - s.from[0]) * t,
        s.from[1] + (s.to[1] - s.from[1]) * t,
        s.from[2] + (s.to[2] - s.from[2]) * t,
      ]);
    }
  }
  return out;
}

class CellSet {
  private cells = new Set<string>();
  constructor(private cell: number) {}
  private key(i: number, j: number, k: number) {
    return `${i},${j},${k}`;
  }
  add(p: Vec3) {
    this.cells.add(this.key(Math.floor(p[0] / this.cell), Math.floor(p[1] / this.cell), Math.floor(p[2] / this.cell)));
  }
  /** Czy w sąsiedztwie punktu (±1 komórka) leży jakiś punkt z zbioru. */
  near(p: Vec3): boolean {
    const i = Math.floor(p[0] / this.cell);
    const j = Math.floor(p[1] / this.cell);
    const k = Math.floor(p[2] / this.cell);
    for (let a = -1; a <= 1; a++)
      for (let b = -1; b <= 1; b++)
        for (let c = -1; c <= 1; c++) if (this.cells.has(this.key(i + a, j + b, k + c))) return true;
    return false;
  }
}

/**
 * Porównuje rysunek ze wzorem niezależnie od kolejności, kierunku i podziału odcinków:
 * oba rysunki są próbkowane, a punkt zalicza się, gdy w pobliżu jest punkt drugiego rysunku.
 * Tolerancja rośnie z rozmiarem wzoru (ok. 2%), minimum 1.5 jednostki.
 */
export function compareDrawings(expected: readonly Segment[], actual: readonly Segment[]): DrawingMatch {
  const cell = Math.max(1.5, 0.02 * extentOf(expected));
  const step = cell / 2;
  const exp = samples(expected, step);
  const act = samples(actual, step);
  const expSet = new CellSet(cell);
  const actSet = new CellSet(cell);
  exp.forEach((p) => expSet.add(p));
  act.forEach((p) => actSet.add(p));
  let missing: Vec3 | null = null;
  let covered = 0;
  for (const p of exp) {
    if (actSet.near(p)) covered++;
    else missing ??= p;
  }
  let extra: Vec3 | null = null;
  let precise = 0;
  for (const p of act) {
    if (expSet.near(p)) precise++;
    else extra ??= p;
  }
  const coverage = exp.length ? covered / exp.length : 1;
  const precision = act.length ? precise / act.length : 1;
  return { ok: coverage >= THRESHOLD && precision >= THRESHOLD, coverage, precision, missing, extra };
}
