  },
];

export function challengeById(id: string): Challenge | undefined {
  return CHALLENGES.find((c) => c.id === id);
}

export interface CheckResult {
  passed: boolean;
  reason: string;
}

const fmt = (p: readonly number[]) => `(${p.map((v) => Math.round(v)).join(", ")})`;

const targetCache = new Map<string, Segment[]>();
function targetOf(c: Challenge): Segment[] {
  let t = targetCache.get(c.id);
  if (!t) {
    t = run(c.solution, c.mode).segments;
    targetCache.set(c.id, t);
  }
  return t;
}

/** Wzór (rysunek wzorcowego rozwiązania), np. do podglądu. */
export function challengeTarget(c: Challenge): readonly Segment[] {
  return targetOf(c);
}

/** Uruchamia program użytkownika i porównuje jego rysunek ze wzorem. */
export function checkChallenge(c: Challenge, source: string): CheckResult {
  const result = run(source, c.mode);
  if (result.error) {
    const e = result.error;
    return {
      passed: false,
      reason: `Program zgłasza błąd (wiersz ${e.line}, kolumna ${e.column}): ${e.message}`,
    };
  }
  if (result.segments.length === 0) {
    return { passed: false, reason: "Nic nie narysowano. Uruchom program, który rysuje kreski." };
  }
  const match = compareDrawings(targetOf(c), result.segments);
  const pct = (x: number) => `${Math.round(x * 100)}%`;
  if (!match.ok) {
    if (match.coverage < 0.97 && match.missing) {
      return {
        passed: false,
        reason: `Rysunek nie pokrywa wzoru (${pct(match.coverage)}): brakuje fragmentów, np. w pobliżu punktu ${fmt(match.missing)}.`,
      };
    }
    return {
      passed: false,
      reason: `Rysunek zawiera dodatkowe linie, których nie ma we wzorze (${pct(1 - match.precision)} rysunku), np. w pobliżu punktu ${match.extra ? fmt(match.extra) : "?"}.`,
    };
  }
  if (c.requires === "procedure") {
    const facts = inspectProgram(source, c.mode);
    if (!facts || facts.procedures === 0 || facts.calls < 2 && facts.repeats === 0) {
      return {
        passed: false,
        reason: "Rysunek się zgadza, ale zadanie wymaga zdefiniowania procedury (oto … już) i użycia jej w programie.",
      };
    }
  }
  return { passed: true, reason: "Rysunek zgadza się ze wzorem. Brawo!" };
}

const KEY_PROGRESS = "logomocja:v1:progress";

interface ProgressData {
  [id: string]: { solved: boolean; attempts: number; solvedAt?: string };
}

export interface Progress {
  isSolved(id: string): boolean;
  attempts(id: string): number;
  solvedCount(): number;
  /** Zapisuje wynik próby; zaliczenie nie jest odbierane przez późniejsze porażki. */
  record(id: string, passed: boolean): void;
  reset(): void;
}

export function createProgress(store: KeyValueStore): Progress {
  const load = (): ProgressData => {
    const raw = safeGet(store, KEY_PROGRESS);
    if (!raw) return {};
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  };
  let data = load();
  return {
    isSolved: (id) => data[id]?.solved === true,
    attempts: (id) => data[id]?.attempts ?? 0,
    solvedCount: () => Object.values(data).filter((e) => e?.solved === true).length,
    record(id, passed) {
      const entry = data[id] ?? { solved: false, attempts: 0 };
      entry.attempts += 1;
      if (passed && !entry.solved) {
        entry.solved = true;
        entry.solvedAt = new Date().toISOString();
      }
      data[id] = entry;
      safeSet(store, KEY_PROGRESS, JSON.stringify(data));
    },
    reset() {
      data = {};
      safeRemove(store, KEY_PROGRESS);
    },
  };
}
