/** Skróty wyświetlane w interfejsie (Ctrl odpowiada ⌘ na macOS). */
export const SHORTCUTS: readonly { action: Action; label: string; keys: readonly string[] }[] = [
  { action: "run", label: "Uruchom program", keys: ["Ctrl+Enter"] },
  { action: "step", label: "Wykonaj jeden krok", keys: ["F10", "Ctrl+."] },
  { action: "pause-resume", label: "Pauza / wznów", keys: ["F9", "Ctrl+Shift+Enter"] },
  { action: "reset", label: "Zeruj (przerwij i wyczyść rysunek)", keys: ["F8", "Ctrl+Shift+."] },
];

/** Zamienia zdarzenie klawiatury na akcję; null dla zwykłego pisania. */
export function matchShortcut(e: KeyEventLike): Action | null {
  if (e.altKey) return null;
  const mod = e.ctrlKey || e.metaKey;
  if (!mod && !e.shiftKey) {
    if (e.key === "F10") return "step";
    if (e.key === "F9") return "pause-resume";
    if (e.key === "F8") return "reset";
    return null;
  }
  if (mod && !e.shiftKey) {
    if (e.key === "Enter") return "run";
    if (e.key === ".") return "step";
    return null;
  }
  if (mod && e.shiftKey) {
    if (e.key === "Enter") return "pause-resume";
    if (e.key === "." || e.key === ">") return "reset";
  }
  return null;
}
