import { describe, expect, test } from "bun:test";
import { EXAMPLES } from "../src/app/examples";
import { createMemoryStore } from "../src/app/storage";
import { createStudio, type ViewPort } from "../src/app/studio";
import { run } from "../src/lang";

function makeStudio() {
  const calls: Array<{ status: string; segments: number }> = [];
  let resolveFrame: (() => void) | null = null;
  const view: ViewPort = {
    fitAndPresent(state) {
      calls.push({ status: state.status, segments: state.segments.length });
      return new Promise<void>((resolve) => {
        resolveFrame = resolve;
        queueMicrotask(resolve);
      });
    },
  };
  const store = createMemoryStore();
  const studio = createStudio({ store, view });
  return { studio, store, calls, view, resolveFrame: () => resolveFrame };
}

describe("window.logomocja: run", () => {
  test("version jest niepustym tekstem", () => {
    expect(typeof makeStudio().studio.api.version).toBe("string");
    expect(makeStudio().studio.api.version.length).toBeGreaterThan(0);
  });
  test("run zwraca wynik interpretera i nie dotyka interfejsu ani szkicu", () => {
    const { studio, store, calls } = makeStudio();
    const before = studio.workspace.source;
    const r = studio.api.run("np 10 pw 90 np 5", "2d");
    expect(r).toEqual(run("np 10 pw 90 np 5", "2d"));
    expect(studio.workspace.source).toBe(before);
    expect(studio.controller.state.segments).toEqual([]);
    expect(calls).toEqual([]);
    expect(store.getItem("logomocja:v1:draft:2d")).toBeNull();
  });
  test("run zgłasza błędy po polsku z pozycją", () => {
    const r = makeStudio().studio.api.run("np 10\n  foo", "3d");
    expect(r.segments).toEqual([]);
    expect(r.error).toMatchObject({ line: 2, column: 3 });
  });
});

describe("window.logomocja: open", () => {
  test.each(EXAMPLES.map((e) => [e.id, e.mode] as const))("open(%s) wczytuje do edytora i zwraca to samo co run", async (id, mode) => {
    const { studio } = makeStudio();
    const ex = EXAMPLES.find((e) => e.id === id)!;
    const opened = await studio.api.open(ex.source, mode);
    expect(opened).toEqual(run(ex.source, mode));
    expect(studio.workspace.source).toBe(ex.source);
    expect(studio.workspace.mode).toBe(mode);
    expect(studio.controller.state.status).toBe("finished");
    expect(studio.controller.state.segments).toHaveLength(opened.segments.length);
  });
  test("open czeka na narysowanie: widok dostaje gotowy, zakończony rysunek, a obietnica rozwiązuje się po nim", async () => {
    const { studio, calls } = makeStudio();
    const result = await studio.api.open("powtorz 4 [np 10 pw 90]", "2d");
    expect(calls).toEqual([{ status: "finished", segments: 4 }]);
    expect(result.segments).toHaveLength(4);
  });
  test("kolejne open nie dokładają do poprzedniego rysunku, a zwrócone segmenty nie znikają po reset", async () => {
    const { studio } = makeStudio();
    const a = await studio.api.open("powtorz 4 [np 10 pw 90]", "2d");
    const b = await studio.api.open("np 5", "2d");
    expect(b.segments).toHaveLength(1);
    expect(a.segments).toHaveLength(4);
    studio.controller.reset();
    expect(studio.controller.state.segments).toEqual([]);
    expect(b.segments).toHaveLength(1);
    expect(studio.workspace.source).toBe("np 5");
  });
  test("open z błędem składni nic nie rysuje, a z błędem wykonania zachowuje narysowane", async () => {
    const { studio } = makeStudio();
    const syntax = await studio.api.open("np 5\nfoo", "2d");
    expect(syntax.segments).toEqual([]);
    expect(syntax.error).toMatchObject({ line: 2, column: 1 });
    expect(studio.controller.state.status).toBe("failed");
    const runtime = await studio.api.open("np 5\nnp 1 / 0", "2d");
    expect(runtime.segments).toHaveLength(1);
    expect(runtime.error).toMatchObject({ line: 2, column: 4 });
    expect(studio.controller.state.error).toMatchObject({ line: 2, column: 4 });
  });
  test("open w trybie 3D przełącza tryb pracowni, a draft innego trybu zostaje nietknięty", async () => {
    const { studio } = makeStudio();
    studio.workspace.setSource("np 42 ; moje 2D");
    await studio.api.open("gora 90 np 7", "3d");
    expect(studio.workspace.mode).toBe("3d");
    studio.workspace.setMode("2d");
    expect(studio.workspace.source).toBe("np 42 ; moje 2D");
  });
  test("open wklejony nad cennym szkicem zachowuje go w kopii zapasowej", async () => {
    const { studio } = makeStudio();
    studio.workspace.setSource("np 42 ; cenne");
    await studio.api.open("np 1", "2d");
    expect(studio.workspace.hasBackup("2d")).toBe(true);
    studio.workspace.restoreBackup("2d");
    expect(studio.workspace.source).toBe("np 42 ; cenne");
  });
  test("powtarzane run/open na tym samym studiu są niezależne (brak stanu przeciekającego między przebiegami)", async () => {
    const { studio } = makeStudio();
    const src = "niech n 0\npowtorz 3 [niech n n + 1 np n]";
    const first = await studio.api.open(src, "2d");
    const second = await studio.api.open(src, "2d");
    expect(second).toEqual(first);
    expect(studio.api.run(src, "2d")).toEqual(first);
  });
});
