import { run, type Mode, type RunResult, type Segment } from "../lang";
import { VERSION } from "../version";
import { createProgress, type Progress } from "./challenges";
import { createController, type Controller, type ControllerState } from "./controller";
import type { KeyValueStore } from "./storage";
import { createWorkspace, type Workspace } from "./workspace";

/** Port widoku: dopasowuje kamerę do rysunku i rysuje go na ekranie. */
export interface ViewPort {
  /** Wywoływane, gdy rysunek jest gotowy; obietnica spełnia się, gdy klatka jest na ekranie. */
  fitAndPresent(state: ControllerState): Promise<void>;
}

/** Interfejs testowy dostępny jako window.logomocja. */
export interface StudioApi {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

export interface Studio {
  workspace: Workspace;
  controller: Controller;
  progress: Progress;
  api: StudioApi;
}

const copySegments = (segments: readonly Segment[]): Segment[] =>
  segments.map((s) => ({ from: [...s.from], to: [...s.to], color: s.color, width: s.width }));

export function createStudio(options: { store: KeyValueStore; view?: ViewPort }): Studio {
  const workspace = createWorkspace(options.store);
  const controller = createController();
  const progress = createProgress(options.store);
  controller.setProgram(workspace.source, workspace.mode);

  const api: StudioApi = {
    version: VERSION,
    run: (source, mode) => run(source, mode),
    async open(source, mode) {
      workspace.replaceSource(source, mode);
      controller.setProgram(source, mode);
      controller.runToEnd();
      const state = controller.state;
      await options.view?.fitAndPresent(state);
      return { segments: copySegments(state.segments), error: state.error };
    },
  };

  return { workspace, controller, progress, api };
}
