import { describe, expect, test } from "bun:test";
import { boundsOf } from "../src/view/bounds";
import { fitCamera2D, gridStep, panBy, toScreen, toWorld, zoomAt } from "../src/view/camera2d";
import type { Segment } from "../src/lang";

const seg = (from: [number, number, number], to: [number, number, number]): Segment => ({ from, to, color: "#000000", width: 1 });

describe("granice rysunku", () => {
  test("obejmują oba końce każdego odcinka i (domyślnie) początek układu", () => {
    const b = boundsOf([seg([10, 20, 5], [30, 50, -5])])!;
    expect(b.min).toEqual([0, 0, -5]);
    expect(b.max).toEqual([30, 50, 5]);
    const noOrigin = boundsOf([seg([10, 20, 5], [30, 50, -5])], false)!;
    expect(noOrigin.min).toEqual([10, 20, -5]);
  });
  test("pusty rysunek: bez początku brak granic, z początkiem punkt (0,0,0)", () => {
    expect(boundsOf([], false)).toBeNull();
    expect(boundsOf([])).toEqual({ min: [0, 0, 0], max: [0, 0, 0] });
  });
});

describe("kamera 2D", () => {
  const W = 800;
  const H = 600;
  test("oś Y rośnie w górę ekranu, a środek kamery leży w środku widoku", () => {
    const cam = { cx: 10, cy: 20, scale: 2 };
    expect(toScreen(cam, W, H, 10, 20)).toEqual([400, 300]);
    expect(toScreen(cam, W, H, 20, 20)).toEqual([420, 300]);
    expect(toScreen(cam, W, H, 10, 30)).toEqual([400, 280]);
  });
  test("toWorld jest odwrotnością toScreen", () => {
    const cam = { cx: -35, cy: 12.5, scale: 3.7 };
    const [sx, sy] = toScreen(cam, W, H, 123.4, -56.7);
    const [x, y] = toWorld(cam, W, H, sx, sy);
    expect(x).toBeCloseTo(123.4, 9);
    expect(y).toBeCloseTo(-56.7, 9);
  });
  test("dopasowanie mieści rysunek z marginesem i wyśrodkowuje go", () => {
    const b = { min: [0, 0, 0] as [number, number, number], max: [100, 50, 0] as [number, number, number] };
    const cam = fitCamera2D(b, W, H);
    expect(cam.cx).toBe(50);
    expect(cam.cy).toBe(25);
    const [x0, y0] = toScreen(cam, W, H, 0, 0);
    const [x1, y1] = toScreen(cam, W, H, 100, 50);
    expect(x0).toBeGreaterThan(0);
    expect(x1).toBeLessThan(W);
    expect(y1).toBeGreaterThan(0);
    expect(y0).toBeLessThan(H);
    // ogranicza szerokość: (800 − 2·margines)/100
    expect(cam.scale).toBeCloseTo((W * (1 - 2 * 0.08)) / 100, 9);
  });
  test("dopasowanie pustych granic daje widok domyślny, a punktowych granic nie dzieli przez zero", () => {
    expect(fitCamera2D(null, W, H)).toEqual({ cx: 0, cy: 0, scale: 1 });
    const cam = fitCamera2D({ min: [5, 5, 0], max: [5, 5, 0] }, W, H);
    expect(Number.isFinite(cam.scale)).toBe(true);
    expect(cam.scale).toBeGreaterThan(0);
  });
  test("przybliżanie wokół kursora zachowuje punkt świata pod kursorem", () => {
    const cam = { cx: 0, cy: 0, scale: 2 };
    const before = toWorld(cam, W, H, 600, 100);
    const zoomed = zoomAt(cam, W, H, 600, 100, 1.5);
    expect(zoomed.scale).toBeCloseTo(3, 9);
    const after = toWorld(zoomed, W, H, 600, 100);
    expect(after[0]).toBeCloseTo(before[0], 9);
    expect(after[1]).toBeCloseTo(before[1], 9);
  });
  test("skala jest ograniczona od dołu i od góry", () => {
    const cam = { cx: 0, cy: 0, scale: 1 };
    expect(zoomAt(cam, W, H, 0, 0, 1e-9).scale).toBeGreaterThan(0);
    expect(zoomAt(cam, W, H, 0, 0, 1e9).scale).toBeLessThan(1e6);
  });
  test("przesunięcie o piksele przesuwa rysunek razem z kursorem", () => {
    const cam = { cx: 0, cy: 0, scale: 2 };
    const moved = panBy(cam, 40, -20);
    // punkt świata, który był pod (400,300), ma teraz być pod (440,280)
    const [wx, wy] = toWorld(cam, W, H, 400, 300);
    const [sx, sy] = toScreen(moved, W, H, wx, wy);
    expect(sx).toBeCloseTo(440, 9);
    expect(sy).toBeCloseTo(280, 9);
  });
  test("krok siatki to 1, 2 lub 5 razy potęga dziesięciu i daje czytelny odstęp w pikselach", () => {
    for (const scale of [0.01, 0.1, 0.37, 1, 2.5, 7, 40, 300]) {
      const step = gridStep(scale);
      const mantissa = step / 10 ** Math.floor(Math.log10(step));
      expect([1, 2, 5]).toContain(Math.round(mantissa * 1e9) / 1e9);
      expect(step * scale).toBeGreaterThanOrEqual(40);
      expect(step * scale).toBeLessThan(40 * 2.5 + 1e-9);
    }
  });
});
EOF
