import type { Bounds } from "./bounds";

/** Kamera 2D: środek w jednostkach świata i skala w pikselach na jednostkę. */
export interface Camera2D {
  cx: number;
  cy: number;
  scale: number;
}

const MIN_SCALE = 1e-3;
const MAX_SCALE = 1e5;
const clampScale = (s: number) => Math.min(MAX_SCALE, Math.max(MIN_SCALE, s));

export function toScreen(cam: Camera2D, w: number, h: number, x: number, y: number): [number, number] {
  return [w / 2 + (x - cam.cx) * cam.scale, h / 2 - (y - cam.cy) * cam.scale];
}

export function toWorld(cam: Camera2D, w: number, h: number, sx: number, sy: number): [number, number] {
  return [cam.cx + (sx - w / 2) / cam.scale, cam.cy - (sy - h / 2) / cam.scale];
}

/** Kamera mieszcząca granice z marginesem (ułamek rozmiaru widoku z każdej strony). */
export function fitCamera2D(bounds: Bounds | null, w: number, h: number, margin = 0.08): Camera2D {
  if (!bounds) return { cx: 0, cy: 0, scale: 1 };
  const bw = bounds.max[0] - bounds.min[0];
  const bh = bounds.max[1] - bounds.min[1];
  const usableW = Math.max(1, w * (1 - 2 * margin));
  const usableH = Math.max(1, h * (1 - 2 * margin));
  const scale = Math.min(bw > 0 ? usableW / bw : Infinity, bh > 0 ? usableH / bh : Infinity);
  return {
    cx: (bounds.min[0] + bounds.max[0]) / 2,
    cy: (bounds.min[1] + bounds.max[1]) / 2,
    scale: Number.isFinite(scale) ? clampScale(scale) : 1,
  };
}

/** Zmienia skalę o `factor`, zostawiając punkt świata pod kursorem w miejscu. */
export function zoomAt(cam: Camera2D, w: number, h: number, sx: number, sy: number, factor: number): Camera2D {
  const [wx, wy] = toWorld(cam, w, h, sx, sy);
  const scale = clampScale(cam.scale * factor);
  return { scale, cx: wx - (sx - w / 2) / scale, cy: wy + (sy - h / 2) / scale };
}

/** Przesuwa rysunek o (dx, dy) pikseli ekranu. */
export function panBy(cam: Camera2D, dx: number, dy: number): Camera2D {
  return { ...cam, cx: cam.cx - dx / cam.scale, cy: cam.cy + dy / cam.scale };
}

/** Najmniejszy „ładny” krok siatki (1, 2 lub 5 × 10^k), który daje co najmniej 40 px odstępu. */
export function gridStep(scale: number): number {
  const raw = 40 / scale;
  const exp = Math.floor(Math.log10(raw));
  for (const m of [1, 2, 5, 10]) {
    const step = m * 10 ** exp;
    if (step >= raw * (1 - 1e-12)) return step;
  }
  return 10 ** (exp + 1);
}
