import { describe, expect, test } from "bun:test";
import { defaultCamera3D, fitCamera3D, orbit, pan3D, project, projectSegment, topView, zoom3D } from "../src/view/camera3d";
import type { Vec3 } from "../src/lang";

const W = 800;
const H = 600;

describe("kamera 3D", () => {
  test("cel kamery rzutuje się na środek widoku w odległości równej distance", () => {
    const cam = { ...defaultCamera3D(), target: [10, 20, 30] as Vec3, distance: 250 };
    const p = project(cam, W, H, [10, 20, 30])!;
    expect(p.x).toBeCloseTo(W / 2, 9);
    expect(p.y).toBeCloseTo(H / 2, 9);
    expect(p.depth).toBeCloseTo(250, 9);
  });
  test("oś Z rośnie w górę ekranu przy każdym obrocie i nachyleniu poniżej 90°", () => {
    for (const yaw of [0, 0.7, 2, 4, -3]) {
      for (const pitch of [-1, 0, 0.5, 1.2]) {
        const cam = { ...defaultCamera3D(), yaw, pitch };
        const lo = project(cam, W, H, [0, 0, 0])!;
        const hi = project(cam, W, H, [0, 0, 10])!;
        expect(hi.y).toBeLessThan(lo.y);
      }
    }
  });
  test("widok z góry ma tę samą orientację co widok 2D: +X w prawo, +Y w górę ekranu", () => {
    const cam = topView(defaultCamera3D());
    const o = project(cam, W, H, [0, 0, 0])!;
    const px = project(cam, W, H, [50, 0, 0])!;
    const py = project(cam, W, H, [0, 50, 0])!;
    expect(px.x).toBeGreaterThan(o.x + 1);
    expect(px.y).toBeCloseTo(o.y, 6);
    expect(py.y).toBeLessThan(o.y - 1);
    expect(py.x).toBeCloseTo(o.x, 6);
  });
  test("perspektywa: bliższy odcinek tej samej długości wygląda na dłuższy", () => {
    const cam = { ...defaultCamera3D(), yaw: 0, pitch: 0, target: [0, 0, 0] as Vec3, distance: 300 };
    // kamera stoi w (0,-300,0) i patrzy w +Y; odcinki wzdłuż X
    const near = [project(cam, W, H, [-10, -100, 0])!, project(cam, W, H, [10, -100, 0])!];
    const far = [project(cam, W, H, [-10, 100, 0])!, project(cam, W, H, [10, 100, 0])!];
    expect(near[1].x - near[0].x).toBeGreaterThan(far[1].x - far[0].x);
  });
  test("punkt za kamerą nie jest rzutowany, a odcinek przecinający płaszczyznę bliską jest przycinany", () => {
    const cam = { ...defaultCamera3D(), yaw: 0, pitch: 0, target: [0, 0, 0] as Vec3, distance: 100 };
    expect(project(cam, W, H, [0, -500, 0])).toBeNull();
    expect(projectSegment(cam, W, H, [0, -500, 0], [5, -400, 0])).toBeNull();
    const clipped = projectSegment(cam, W, H, [0, 0, 0], [0, -500, 0])!;
    expect(clipped[0].depth).toBeCloseTo(100, 9);
    expect(clipped[1].depth).toBeGreaterThan(0);
    expect(clipped[1].depth).toBeLessThan(100);
    expect(Number.isFinite(clipped[1].x) && Number.isFinite(clipped[1].y)).toBe(true);
  });
  test("obrót o pełny okrąg wraca do tego samego rzutu, a nachylenie jest ograniczone do ±90°", () => {
    const cam = defaultCamera3D();
    const around = orbit(cam, (2 * Math.PI) / 0.008, 0);
    const a = project(cam, W, H, [30, 40, 50])!;
    const b = project(around, W, H, [30, 40, 50])!;
    expect(b.x).toBeCloseTo(a.x, 6);
    expect(b.y).toBeCloseTo(a.y, 6);
    expect(orbit(cam, 0, 1e6).pitch).toBeLessThanOrEqual(Math.PI / 2);
    expect(orbit(cam, 0, -1e6).pitch).toBeGreaterThanOrEqual(-Math.PI / 2);
  });
  test("przeciągnięcie w prawo obraca scenę zgodnie z ruchem wskazówek zegara widzianym z góry", () => {
    const cam = { ...defaultCamera3D(), yaw: 0, pitch: 0.5 };
    const turned = orbit(cam, 100, 0);
    // punkt na +X (po prawej): po obrocie powinien znaleźć się bliżej kamery (większa głębokość maleje)
    const before = project(cam, W, H, [100, 0, 0])!;
    const after = project(turned, W, H, [100, 0, 0])!;
    expect(after.depth).toBeLessThan(before.depth);
  });
  test("przesunięcie o piksele przesuwa stary cel dokładnie o tyle pikseli", () => {
    const cam = { ...defaultCamera3D(), target: [5, 6, 7] as Vec3, distance: 321 };
    const moved = pan3D(cam, W, H, 40, -25);
    const p = project(moved, W, H, [5, 6, 7])!;
    expect(p.x).toBeCloseTo(W / 2 + 40, 6);
    expect(p.y).toBeCloseTo(H / 2 - 25, 6);
  });
  test("przybliżanie zmienia odległość i jest ograniczone", () => {
    const cam = { ...defaultCamera3D(), distance: 200 };
    expect(zoom3D(cam, 0.5).distance).toBeCloseTo(100, 9);
    expect(zoom3D(cam, 1e-12).distance).toBeGreaterThan(0);
    expect(zoom3D(cam, 1e12).distance).toBeLessThan(1e9);
  });
  test("dopasowanie mieści w widoku wszystkie narożniki granic, także dla smukłych i dużych rysunków", () => {
    const cases: Array<{ min: Vec3; max: Vec3 }> = [
      { min: [0, 0, 0], max: [100, 100, 100] },
      { min: [-3000, -10, 0], max: [3000, 10, 20] },
      { min: [0, 0, 0], max: [0.5, 0.5, 0.5] },
      { min: [-90000, -90000, -90000], max: [90000, 90000, 90000] },
    ];
    for (const b of cases) {
      for (const [w, h] of [[800, 600], [360, 640]] as const) {
        const cam = fitCamera3D(b, w, h);
        for (const x of [b.min[0], b.max[0]])
          for (const y of [b.min[1], b.max[1]])
            for (const z of [b.min[2], b.max[2]]) {
              const p = project(cam, w, h, [x, y, z])!;
              expect(p).not.toBeNull();
              expect(p.x).toBeGreaterThan(0);
              expect(p.x).toBeLessThan(w);
              expect(p.y).toBeGreaterThan(0);
              expect(p.y).toBeLessThan(h);
            }
      }
    }
  });
  test("dopasowanie pustych granic daje widok domyślny", () => {
    expect(fitCamera3D(null, W, H)).toEqual(defaultCamera3D());
  });
});
