import type { Vec3 } from "../lang";
import type { Bounds } from "./bounds";

/**
 * Kamera orbitalna ze Z do góry. `yaw` to azymut (0 = patrzymy w stronę +Y, +X po prawej),
 * `pitch` to wysokość nad poziomem (π/2 = widok z góry).
 */
export interface Camera3D {
  target: Vec3;
  distance: number;
  yaw: number;
  pitch: number;
  /** Pionowe pole widzenia w radianach. */
  fov: number;
}

export interface Projected {
  x: number;
  y: number;
  /** Odległość wzdłuż kierunku patrzenia (większa = dalej). */
  depth: number;
}

/** Radiany ruchu kamery na piksel przeciągnięcia. */
export const ORBIT_SPEED = 0.008;
const MIN_DISTANCE = 1e-3;
const MAX_DISTANCE = 1e7;

export function defaultCamera3D(): Camera3D {
  return { target: [0, 0, 0], distance: 400, yaw: (40 * Math.PI) / 180, pitch: (28 * Math.PI) / 180, fov: (45 * Math.PI) / 180 };
}

/** Widok z góry, zgodny z orientacją widoku 2D (+X w prawo, +Y w górę ekranu). */
export function topView(cam: Camera3D): Camera3D {
  return { ...cam, yaw: 0, pitch: Math.PI / 2 };
}

const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];

export function basisOf(cam: Camera3D): { eye: Vec3; right: Vec3; up: Vec3; forward: Vec3 } {
  const cp = Math.cos(cam.pitch);
  const dir: Vec3 = [Math.sin(cam.yaw) * cp, -Math.cos(cam.yaw) * cp, Math.sin(cam.pitch)];
  const eye: Vec3 = [
    cam.target[0] + dir[0] * cam.distance,
    cam.target[1] + dir[1] * cam.distance,
    cam.target[2] + dir[2] * cam.distance,
  ];
  const forward: Vec3 = [-dir[0], -dir[1], -dir[2]];
  const right: Vec3 = [Math.cos(cam.yaw), Math.sin(cam.yaw), 0];
  return { eye, right, up: cross(right, forward), forward };
}

const nearPlane = (cam: Camera3D) => Math.max(1e-4, cam.distance * 0.01);
const focalLength = (cam: Camera3D, h: number) => h / 2 / Math.tan(cam.fov / 2);

/** Rzutuje punkt na ekran; null, gdy leży przed płaszczyzną bliską (za kamerą). */
export function project(cam: Camera3D, w: number, h: number, p: Vec3): Projected | null {
  const b = basisOf(cam);
  const d: Vec3 = [p[0] - b.eye[0], p[1] - b.eye[1], p[2] - b.eye[2]];
  const depth = dot(d, b.forward);
  if (depth < nearPlane(cam)) return null;
  const f = focalLength(cam, h);
  return { x: w / 2 + (dot(d, b.right) / depth) * f, y: h / 2 - (dot(d, b.up) / depth) * f, depth };
}

/** Rzutuje odcinek z przycięciem do płaszczyzny bliskiej; null, gdy cały jest za kamerą. */
export function projectSegment(
  cam: Camera3D,
  w: number,
  h: number,
  a: Vec3,
  b: Vec3,
): [Projected, Projected] | null {
  const bs = basisOf(cam);
  const near = nearPlane(cam);
  const depthOf = (p: Vec3) => dot([p[0] - bs.eye[0], p[1] - bs.eye[1], p[2] - bs.eye[2]], bs.forward);
  const da = depthOf(a);
  const db = depthOf(b);
  if (da < near && db < near) return null;
  let pa = a;
  let pb = b;
  if (da < near || db < near) {
    const t = (near - da) / (db - da);
    const cut: Vec3 = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
    if (da < near) pa = cut;
    else pb = cut;
  }
  const qa = project(cam, w, h, pa) ?? project(cam, w, h, nudge(pa, bs.forward, near * 1.0001));
  const qb = project(cam, w, h, pb) ?? project(cam, w, h, nudge(pb, bs.forward, near * 1.0001));
  return qa && qb ? [qa, qb] : null;
}

/** Przesuwa punkt przycięcia minimalnie do przodu, by uniknąć błędu zaokrąglenia na płaszczyźnie bliskiej. */
function nudge(p: Vec3, forward: Vec3, amount: number): Vec3 {
  return [p[0] + forward[0] * amount * 1e-6, p[1] + forward[1] * amount * 1e-6, p[2] + forward[2] * amount * 1e-6];
}

/** Obrót kamery wokół celu o przeciągnięcie (dx, dy) pikseli. */
export function orbit(cam: Camera3D, dx: number, dy: number): Camera3D {
  const yaw = cam.yaw + dx * ORBIT_SPEED;
  const pitch = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, cam.pitch + dy * ORBIT_SPEED));
  return { ...cam, yaw, pitch };
}

/** Przesunięcie widoku w płaszczyźnie ekranu o (dx, dy) pikseli. */
export function pan3D(cam: Camera3D, w: number, h: number, dx: number, dy: number): Camera3D {
  const { right, up } = basisOf(cam);
  const k = (2 * cam.distance * Math.tan(cam.fov / 2)) / h;
  return {
    ...cam,
    target: [
      cam.target[0] - right[0] * dx * k + up[0] * dy * k,
      cam.target[1] - right[1] * dx * k + up[1] * dy * k,
      cam.target[2] - right[2] * dx * k + up[2] * dy * k,
    ],
  };
}

export function zoom3D(cam: Camera3D, factor: number): Camera3D {
  return { ...cam, distance: Math.min(MAX_DISTANCE, Math.max(MIN_DISTANCE, cam.distance * factor)) };
}

/** Ustawia cel i odległość tak, by granice zmieściły się w widoku (zachowuje kierunek patrzenia). */
export function fitCamera3D(bounds: Bounds | null, w: number, h: number, base: Camera3D = defaultCamera3D()): Camera3D {
  if (!bounds) return defaultCamera3D();
  const target: Vec3 = [
    (bounds.min[0] + bounds.max[0]) / 2,
    (bounds.min[1] + bounds.max[1]) / 2,
    (bounds.min[2] + bounds.max[2]) / 2,
  ];
  const radius = Math.hypot(
    bounds.max[0] - bounds.min[0],
    bounds.max[1] - bounds.min[1],
    bounds.max[2] - bounds.min[2],
  ) / 2;
  if (radius === 0) return { ...base, target, distance: 100 };
  const halfV = base.fov / 2;
  const halfH = Math.atan(Math.tan(halfV) * (w / h));
  const half = Math.min(halfV, halfH);
  const distance = Math.min(MAX_DISTANCE, Math.max(MIN_DISTANCE, (radius / Math.sin(half)) * 1.1));
  return { ...base, target, distance };
}
