import { cp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { basename } from "node:path";

/** Ścieżka bazowa z BASE_PATH: zawsze z / na początku i na końcu (domyślnie „/”). */
export function normalizeBase(raw: string | undefined): string {
  let base = (raw ?? "/").trim();
  if (base === "") base = "/";
  if (!base.startsWith("/")) base = "/" + base;
  if (!base.endsWith("/")) base += "/";
  return base.replace(/\/{2,}/g, "/");
}

export async function build(base: string, outdir = "dist"): Promise<void> {
  await rm(outdir, { recursive: true, force: true });
  await mkdir(`${outdir}/assets`, { recursive: true });

  const result = await Bun.build({
    entrypoints: ["src/main.ts"],
    outdir: `${outdir}/assets`,
    naming: "[name]-[hash].[ext]",
    target: "browser",
    format: "esm",
    minify: true,
    sourcemap: "none",
  });
  if (!result.success) {
    for (const log of result.logs) console.error(log);
    throw new Error("Budowanie nie powiodło się.");
  }
  const js = result.outputs.find((o) => o.path.endsWith(".js"));
  const css = result.outputs.find((o) => o.path.endsWith(".css"));
  if (!js || !css) throw new Error("Brak pliku JS lub CSS w wyniku budowania.");

  let html = await readFile("index.html", "utf8");
  html = html
    .replaceAll("%BASE%", base)
    .replaceAll("%JS%", `${base}assets/${basename(js.path)}`)
    .replaceAll("%CSS%", `${base}assets/${basename(css.path)}`);
  await writeFile(`${outdir}/index.html`, html);
  await cp("public", outdir, { recursive: true });
  console.log(`Zbudowano do ${outdir}/ (BASE_PATH=${base})`);
}

if (import.meta.main) {
  await build(normalizeBase(process.env.BASE_PATH));
}
