import { describe, expect, test } from "bun:test";
import { DOC_COMMANDS, DOC_SECTIONS, docExamples } from "../src/app/docs-content";
import { ALL_KEYWORDS } from "../src/lang/vocab";
import { run } from "../src/lang";

describe("dokumentacja", () => {
  test("każdy przykład w dokumentacji działa tak, jak opisano (bez błędu albo z udokumentowanym błędem)", () => {
    const examples = docExamples();
    expect(examples.length).toBeGreaterThan(40);
    for (const ex of examples) {
      const r = run(ex.code, ex.mode);
      if (ex.error) {
        expect(r.error, `przykład „${ex.title}” miał zgłosić błąd`).not.toBeNull();
        expect(r.error!.message).toMatch(ex.error);
      } else {
        expect(r.error, `przykład „${ex.title}”: ${r.error?.message}`).toBeNull();
      }
    }
  });
  test("każde słowo języka (polskie i angielskie, z ogonkami i bez) jest opisane w dokumentacji", () => {
    const documented = new Set(DOC_COMMANDS.flatMap((c) => [...c.polish, ...c.english]).map((w) => w.toLowerCase()));
    for (const word of ALL_KEYWORDS) {
      expect(documented.has(word), `brak w dokumentacji: ${word}`).toBe(true);
    }
  });
  test("każde polecenie ma opis, składnię i własny działający przykład", () => {
    for (const c of DOC_COMMANDS) {
      expect(c.summary.length).toBeGreaterThan(10);
      expect(c.syntax.length).toBeGreaterThan(1);
      expect(run(c.example, c.mode).error).toBeNull();
    }
  });
  test("polecenia przestrzenne mają przykłady w 3D, a pozostałe działają w obu trybach", () => {
    for (const c of DOC_COMMANDS) {
      if (c.spatial) expect(c.mode).toBe("3d");
      else {
        expect(run(c.example, "2d").error).toBeNull();
        expect(run(c.example, "3d").error).toBeNull();
      }
    }
  });
  test("sekcje mają unikalne identyfikatory i obejmują wszystkie tematy z opisu produktu", () => {
    const ids = DOC_SECTIONS.map((s) => s.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of ["start", "ruch", "pioro", "powtorz", "wyrazenia", "zmienne", "warunki", "procedury", "przestrzen", "bledy", "limity", "skroty"]) {
      expect(ids).toContain(id);
    }
  });
  test("limity w dokumentacji zgadzają się z opisem języka", () => {
    const text = JSON.stringify(DOC_SECTIONS);
    for (const n of ["50 000", "10 000", "32", "100 000", "±100 000"]) expect(text).toContain(n);
  });
});
EOF
