/** Wszystkie przykłady z dokumentacji (z opisów poleceń i z bloków kodu). */
export function docExamples(): DocExample[] {
  const out: DocExample[] = DOC_COMMANDS.map((c) => ({ title: `Polecenie ${c.polish[0]}`, code: c.example, mode: c.mode }));
  for (const section of DOC_SECTIONS) {
    for (const block of section.blocks) if (block.type === "code") out.push(block.example);
  }
  return out;
}

