import type { Mode } from "../lang";
import { SHORTCUTS } from "./shortcuts";

export interface DocExample {
  title: string;
  code: string;
  mode: Mode;
  /** Jeśli ustawione, przykład celowo kończy się błędem pasującym do wzorca. */
  error?: RegExp;
}

export interface DocCommand {
  id: string;
  polish: string[];
  english: string[];
  /** Składnia, np. „np wyrażenie”. */
  syntax: string;
  summary: string;
  details?: string;
  example: string;
  mode: Mode;
  spatial?: boolean;
}

export type DocBlock =
  | { type: "p"; text: string }
  | { type: "list"; items: string[] }
  | { type: "note"; text: string }
  | { type: "table"; head: string[]; rows: string[][] }
  | { type: "code"; example: DocExample }
  | { type: "commands"; ids: string[] };

export interface DocSection {
  id: string;
  title: string;
  blocks: DocBlock[];
}

const ex = (title: string, code: string, mode: Mode = "2d", error?: RegExp): DocExample => ({
  title,
  code,
  mode,
  ...(error ? { error } : {}),
});

export const DOC_COMMANDS: readonly DocCommand[] = [
