          "Pobierz .logo zapisuje program jako zwykły plik tekstowy, a Otwórz plik .logo wczytuje taki plik (z poleceniami 3D przełącza na tryb 3D).",
          "Eksportuj PNG zapisuje bieżący rysunek jako obraz.",
          "Szkice obu trybów, motyw, szybkość animacji i postępy w wyzwaniach zapisują się w tej przeglądarce (localStorage); nic nie jest wysyłane do sieci.",
        ],
      },
    ],
  },
];

/** Wszystkie przykłady z dokumentacji (z opisów poleceń i z bloków kodu). */
export function docExamples(): DocExample[] {
  const out: DocExample[] = DOC_COMMANDS.map((c) => ({ title: `Polecenie ${c.polish[0]}`, code: c.example, mode: c.mode }));
  for (const section of DOC_SECTIONS) {
    for (const block of section.blocks) if (block.type === "code") out.push(block.example);
  }
  return out;
}

