import type { Segment } from "../lang";
import { gridStep, toScreen, type Camera2D } from "./camera2d";
import type { Palette } from "./palette";
import type { Scene } from "./scene";

const FONT = '12px ui-sans-serif, system-ui, "Segoe UI", Roboto, sans-serif';

/** Czy odcinek na pewno leży poza ekranem (oba końce po tej samej stronie). */
function offscreen(ax: number, ay: number, bx: number, by: number, w: number, h: number, pad: number): boolean {
  return (
    (ax < -pad && bx < -pad) || (ax > w + pad && bx > w + pad) || (ay < -pad && by < -pad) || (ay > h + pad && by > h + pad)
  );
}

function strokeSegments(
  ctx: CanvasRenderingContext2D,
  segments: readonly Segment[],
  project: (s: Segment) => [number, number, number, number],
  w: number,
  h: number,
  widthOf: (s: Segment) => number,
): void {
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  let style = "";
  let open = false;
  for (const s of segments) {
    const [ax, ay, bx, by] = project(s);
    if (offscreen(ax, ay, bx, by, w, h, 14)) continue;
    const lw = widthOf(s);
    const key = `${s.color}|${lw}`;
    if (key !== style) {
      if (open) ctx.stroke();
      ctx.beginPath();
      ctx.strokeStyle = s.color;
      ctx.lineWidth = lw;
      style = key;
      open = true;
    }
    ctx.moveTo(ax, ay);
    ctx.lineTo(bx, by);
  }
  if (open) ctx.stroke();
}

export function drawGrid2D(ctx: CanvasRenderingContext2D, cam: Camera2D, w: number, h: number, pal: Palette): void {
  const step = gridStep(cam.scale);
  const toW = (sx: number, sy: number): [number, number] => [cam.cx + (sx - w / 2) / cam.scale, cam.cy - (sy - h / 2) / cam.scale];
  const [x0, y1] = toW(0, 0);
  const [x1, y0] = toW(w, h);
  ctx.lineWidth = 1;
  ctx.font = FONT;
  ctx.fillStyle = pal.text;
  ctx.textBaseline = "top";
  for (let i = Math.ceil(x0 / step); i <= Math.floor(x1 / step); i++) {
    const [sx] = toScreen(cam, w, h, i * step, 0);
    ctx.strokeStyle = i % 5 === 0 ? pal.gridStrong : pal.grid;
    ctx.beginPath();
    ctx.moveTo(Math.round(sx) + 0.5, 0);
    ctx.lineTo(Math.round(sx) + 0.5, h);
    ctx.stroke();
  }
  for (let j = Math.ceil(y0 / step); j <= Math.floor(y1 / step); j++) {
    const [, sy] = toScreen(cam, w, h, 0, j * step);
    ctx.strokeStyle = j % 5 === 0 ? pal.gridStrong : pal.grid;
    ctx.beginPath();
    ctx.moveTo(0, Math.round(sy) + 0.5);
    ctx.lineTo(w, Math.round(sy) + 0.5);
    ctx.stroke();
  }
  // Osie przez początek układu i podpisy na co piątej kresce.
  const [ox, oy] = toScreen(cam, w, h, 0, 0);
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = pal.axisX;
  ctx.beginPath();
  ctx.moveTo(0, Math.round(oy) + 0.5);
  ctx.lineTo(w, Math.round(oy) + 0.5);
  ctx.stroke();
  ctx.strokeStyle = pal.axisY;
  ctx.beginPath();
  ctx.moveTo(Math.round(ox) + 0.5, 0);
  ctx.lineTo(Math.round(ox) + 0.5, h);
  ctx.stroke();
  const labelY = Math.min(h - 16, Math.max(2, oy + 4));
  const labelX = Math.min(w - 40, Math.max(4, ox + 5));
  ctx.textAlign = "center";
  for (let i = Math.ceil(x0 / (step * 5)); i <= Math.floor(x1 / (step * 5)); i++) {
    if (i === 0) continue;
    const [sx] = toScreen(cam, w, h, i * step * 5, 0);
    ctx.fillText(String(Math.round(i * step * 5 * 1e6) / 1e6), sx, labelY);
  }
  ctx.textAlign = "left";
  for (let j = Math.ceil(y0 / (step * 5)); j <= Math.floor(y1 / (step * 5)); j++) {
    if (j === 0) continue;
    const [, sy] = toScreen(cam, w, h, 0, j * step * 5);
    ctx.fillText(String(Math.round(j * step * 5 * 1e6) / 1e6), labelX, sy - 6);
  }
  // Wyraźny znacznik początku układu.
  ctx.fillStyle = pal.origin;
  ctx.beginPath();
  ctx.arc(ox, oy, 3.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = pal.text;
  ctx.textAlign = "left";
  ctx.fillText("0", ox + 7, oy + 5);
  ctx.fillStyle = pal.axisX;
  ctx.fillText("X", w - 14, Math.min(h - 18, Math.max(2, oy - 18)));
  ctx.fillStyle = pal.axisY;
  ctx.fillText("Y", Math.min(w - 14, Math.max(2, ox + 8)), 4);
}

function drawTurtle2D(ctx: CanvasRenderingContext2D, cam: Camera2D, w: number, h: number, scene: Scene, pal: Palette): void {
  const t = scene.turtle;
  const [sx, sy] = toScreen(cam, w, h, t.position[0], t.position[1]);
  // Kierunek na ekranie: oś Y jest odwrócona.
  const dx = t.heading[0];
  const dy = -t.heading[1];
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  const px = -uy;
  const py = ux;
  const size = 11;
  ctx.save();
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(sx + ux * size * 1.5, sy + uy * size * 1.5);
  ctx.lineTo(sx - ux * size + px * size * 0.9, sy - uy * size + py * size * 0.9);
  ctx.lineTo(sx - ux * size * 0.4, sy - uy * size * 0.4);
  ctx.lineTo(sx - ux * size - px * size * 0.9, sy - uy * size - py * size * 0.9);
  ctx.closePath();
  ctx.fillStyle = t.penDown ? t.color : "transparent";
  ctx.globalAlpha = 0.9;
  if (t.penDown) ctx.fill();
  ctx.globalAlpha = 1;
  ctx.lineWidth = 2;
  ctx.strokeStyle = pal.turtleOutline;
  ctx.setLineDash(t.penDown ? [] : [3, 3]);
  ctx.stroke();
  ctx.restore();
}

export function drawScene2D(ctx: CanvasRenderingContext2D, cam: Camera2D, w: number, h: number, scene: Scene, pal: Palette): void {
  ctx.fillStyle = pal.bg;
  ctx.fillRect(0, 0, w, h);
