import type { Segment, Vec3 } from "../lang";
import { basisOf, project, projectSegment, type Camera3D } from "./camera3d";
import type { Palette } from "./palette";
import type { Scene } from "./scene";

const FONT = '12px ui-sans-serif, system-ui, "Segoe UI", Roboto, sans-serif';

/** Najmniejsza „ładna” liczba (1, 2 lub 5 × 10^k) nie mniejsza niż x. */
export function niceCeil(x: number): number {
  if (!(x > 0)) return 1;
  const exp = Math.floor(Math.log10(x));
  for (const m of [1, 2, 5, 10]) if (m * 10 ** exp >= x * (1 - 1e-12)) return m * 10 ** exp;
  return 10 ** (exp + 1);
}

function line3(
  ctx: CanvasRenderingContext2D,
  cam: Camera3D,
  w: number,
  h: number,
  a: Vec3,
  b: Vec3,
): [number, number, number, number] | null {
  const seg = projectSegment(cam, w, h, a, b);
  return seg ? [seg[0].x, seg[0].y, seg[1].x, seg[1].y] : null;
}

function drawGridAndAxes(ctx: CanvasRenderingContext2D, cam: Camera3D, w: number, h: number, pal: Palette, extent: number): void {
  const step = niceCeil(extent / 8);
  const cells = Math.min(24, Math.max(4, Math.ceil(extent / step)));
  const half = cells * step;
  ctx.lineWidth = 1;
  for (let i = -cells; i <= cells; i++) {
    ctx.strokeStyle = i % 5 === 0 ? pal.gridStrong : pal.grid;
    const a = line3(ctx, cam, w, h, [i * step, -half, 0], [i * step, half, 0]);
    if (a) {
      ctx.beginPath();
      ctx.moveTo(a[0], a[1]);
      ctx.lineTo(a[2], a[3]);
      ctx.stroke();
    }
    const b = line3(ctx, cam, w, h, [-half, i * step, 0], [half, i * step, 0]);
    if (b) {
      ctx.beginPath();
      ctx.moveTo(b[0], b[1]);
      ctx.lineTo(b[2], b[3]);
      ctx.stroke();
    }
  }
  const len = Math.max(half, extent) * 1.05;
  const axes: Array<[string, Vec3, string]> = [
    ["X", [len, 0, 0], pal.axisX],
    ["Y", [0, len, 0], pal.axisY],
    ["Z", [0, 0, len], pal.axisZ],
  ];
  ctx.font = FONT;
  ctx.textBaseline = "middle";
  ctx.textAlign = "center";
  for (const [name, tip, color] of axes) {
    const neg: Vec3 = [-tip[0], -tip[1], -tip[2]];
    ctx.save();
    ctx.strokeStyle = color;
    ctx.globalAlpha = 0.35;
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 1.5;
    const n = line3(ctx, cam, w, h, [0, 0, 0], neg);
    if (n) {
      ctx.beginPath();
      ctx.moveTo(n[0], n[1]);
      ctx.lineTo(n[2], n[3]);
      ctx.stroke();
    }
    ctx.restore();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    const p = line3(ctx, cam, w, h, [0, 0, 0], tip);
    if (p) {
      ctx.beginPath();
      ctx.moveTo(p[0], p[1]);
      ctx.lineTo(p[2], p[3]);
      ctx.stroke();
    }
    const label = project(cam, w, h, [tip[0] * 1.04, tip[1] * 1.04, tip[2] * 1.04]);
    if (label) {
      ctx.fillStyle = color;
      ctx.fillText(name, label.x, label.y);
    }
  }
  const o = project(cam, w, h, [0, 0, 0]);
  if (o) {
    ctx.fillStyle = pal.origin;
    ctx.beginPath();
    ctx.arc(o.x, o.y, 3.5, 0, Math.PI * 2);
    ctx.fill();
  }
}

function strokeSegments3D(
  ctx: CanvasRenderingContext2D,
  cam: Camera3D,
  w: number,
  h: number,
  segments: readonly Segment[],
  override?: { color: string; width: number },
): void {
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  let style = "";
  let open = false;
  for (const s of segments) {
    const seg = projectSegment(cam, w, h, s.from, s.to);
    if (!seg) continue;
    const [a, b] = seg;
    if ((a.x < -20 && b.x < -20) || (a.x > w + 20 && b.x > w + 20) || (a.y < -20 && b.y < -20) || (a.y > h + 20 && b.y > h + 20)) continue;
    const base = override?.width ?? s.width;
    const depth = (a.depth + b.depth) / 2;
    // Perspektywa: bliższe kreski są grubsze, dalsze cieńsze (kwantyzacja do 0.5 px dla grupowania).
    const scaled = Math.min(base * 2.2, Math.max(base * 0.5, (base * cam.distance) / depth));
    const lw = Math.round(scaled * 2) / 2;
    const color = override?.color ?? s.color;
    const key = `${color}|${lw}`;
    if (key !== style) {
      if (open) ctx.stroke();
      ctx.beginPath();
      ctx.strokeStyle = color;
      ctx.lineWidth = lw;
      style = key;
      open = true;
    }
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
  }
  if (open) ctx.stroke();
}

function shade(hex: string, factor: number): string {
  const n = parseInt(hex.slice(1), 16);
  const f = Math.max(0, Math.min(1.15, factor));
  const c = (v: number) => Math.max(0, Math.min(255, Math.round(v * f)));
  return `rgb(${c((n >> 16) & 255)}, ${c((n >> 8) & 255)}, ${c(n & 255)})`;
}

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const norm = (a: Vec3): Vec3 => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};

function drawTurtle3D(ctx: CanvasRenderingContext2D, cam: Camera3D, w: number, h: number, scene: Scene, pal: Palette): void {
  const t = scene.turtle;
  const here = project(cam, w, h, t.position);
  if (!here) return;
  const focal = h / 2 / Math.tan(cam.fov / 2);
  const L = (15 * here.depth) / focal; // ok. 15 px na ekranie niezależnie od odległości
  const at = (h0: number, r0: number, u0: number): Vec3 => [
    t.position[0] + t.heading[0] * h0 * L + t.right[0] * r0 * L + t.up[0] * u0 * L,
    t.position[1] + t.heading[1] * h0 * L + t.right[1] * r0 * L + t.up[1] * u0 * L,
    t.position[2] + t.heading[2] * h0 * L + t.right[2] * r0 * L + t.up[2] * u0 * L,
  ];
  const tip = at(1.5, 0, 0);
  const left = at(-0.7, -0.9, 0);
  const right = at(-0.7, 0.9, 0);
  const top = at(-0.25, 0, 0.8);
  const faces: Vec3[][] = [
    [tip, left, right],
    [tip, right, top],
    [tip, top, left],
    [left, right, top],
  ];
  const b = basisOf(cam);
  const light = norm([-b.right[0] * 0.4 + b.up[0] * 0.7 - b.forward[0] * 0.6, -b.right[1] * 0.4 + b.up[1] * 0.7 - b.forward[1] * 0.6, -b.right[2] * 0.4 + b.up[2] * 0.7 - b.forward[2] * 0.6]);
  const center = t.position;
  const drawn = faces
    .map((f) => {
      let n = norm(cross(sub(f[1], f[0]), sub(f[2], f[0])));
      const mid: Vec3 = [(f[0][0] + f[1][0] + f[2][0]) / 3, (f[0][1] + f[1][1] + f[2][1]) / 3, (f[0][2] + f[1][2] + f[2][2]) / 3];
      if (dot(n, sub(mid, center)) < 0) n = [-n[0], -n[1], -n[2]]; // normalna na zewnątrz
      const pts = f.map((p) => project(cam, w, h, p));
      const depth = pts.every(Boolean) ? pts.reduce((s, p) => s + p!.depth, 0) / 3 : Infinity;
      return { pts, depth, shade: 0.55 + 0.5 * Math.max(0, dot(n, light)) };
    })
    .filter((f) => f.pts.every(Boolean))
    .sort((a, c) => c.depth - a.depth);
  ctx.save();
  ctx.lineJoin = "round";
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = pal.turtleOutline;
  ctx.setLineDash(t.penDown ? [] : [3, 3]);
  for (const f of drawn) {
    ctx.beginPath();
    f.pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p!.x, p!.y) : ctx.lineTo(p!.x, p!.y)));
    ctx.closePath();
    ctx.fillStyle = shade(t.color, f.shade);
    ctx.fill();
    ctx.stroke();
  }
  ctx.restore();
}

export function drawScene3D(
  ctx: CanvasRenderingContext2D,
  cam: Camera3D,
  w: number,
  h: number,
  scene: Scene,
  pal: Palette,
  extent: number,
): void {
  ctx.fillStyle = pal.bg;
  ctx.fillRect(0, 0, w, h);
  drawGridAndAxes(ctx, cam, w, h, pal, extent);
  if (scene.ghost && scene.ghost.length) {
    ctx.save();
    ctx.globalAlpha = 0.75;
    ctx.setLineDash([6, 5]);
    strokeSegments3D(ctx, cam, w, h, scene.ghost, { color: pal.ghost, width: 2 });
    ctx.restore();
  }
  strokeSegments3D(ctx, cam, w, h, scene.segments);
  if (scene.showTurtle) drawTurtle3D(ctx, cam, w, h, scene, pal);
}
