import type { Mode, Segment } from "../lang";
import { h, icon } from "../ui/dom";
import { boundsOf } from "./bounds";
import { fitCamera2D, panBy, zoomAt, type Camera2D } from "./camera2d";
import { defaultCamera3D, fitCamera3D, orbit, pan3D, topView, zoom3D, type Camera3D } from "./camera3d";
import { paletteFor, type CanvasBackground } from "./palette";
import { drawScene2D } from "./render2d";
import { drawScene3D } from "./render3d";
import type { Scene } from "./scene";

export interface ViewportOptions {
  getTheme(): "light" | "dark";
  getBackground(): CanvasBackground;
  setBackground(value: CanvasBackground): void;
}

const EMPTY_2D: Camera2D = { cx: 0, cy: 0, scale: 1.6 };

/** Płótno z rysunkiem żółwia: widok 2D lub 3D, obsługa myszy, dotyku i klawiatury. */
export class Viewport {
  readonly el: HTMLElement;
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D | null;
  private readonly controls: HTMLElement;
  private readonly topButton: HTMLButtonElement;
  private mode: Mode = "2d";
  private scene: Scene = { segments: [], turtle: defaultTurtle(), showTurtle: true };
  private cam2d: Camera2D = { ...EMPTY_2D };
  private cam3d: Camera3D = defaultCamera3D();
  private width = 0;
  private height = 0;
  private dpr = 1;
  private raf = 0;
  /** Dopasowuje widok automatycznie, dopóki użytkownik sam go nie zmieni. */
  private autoFit = true;
  private fitPending = false;
  private lastFitKey = "";
  private pointers = new Map<number, { x: number; y: number }>();
  private pinch: { dist: number; mx: number; my: number } | null = null;
  private resizeObserver: ResizeObserver | null = null;

  constructor(private readonly options: ViewportOptions) {
    this.canvas = h("canvas", {
      class: "viewport-canvas",
      tabindex: "0",
      role: "img",
      "aria-label": "Rysunek żółwia",
      "aria-describedby": "viewport-help",
    });
    this.ctx = typeof this.canvas.getContext === "function" ? this.canvas.getContext("2d") : null;
    this.topButton = this.button("top", "Z góry", "Widok z góry (zgodny z widokiem 2D)", () => this.setTopView());
    const bgButton = this.button("contrast", "Tło", "Przełącz tło rysunku: automatyczne, jasne, ciemne", () => this.cycleBackground());
    this.controls = h(
      "div",
      { class: "viewport-controls", role: "group", "aria-label": "Sterowanie widokiem" },
      this.button("plus", "Przybliż", "Przybliż (klawisz +)", () => this.zoom(1.25)),
      this.button("minus", "Oddal", "Oddal (klawisz −)", () => this.zoom(1 / 1.25)),
      this.button("fit", "Dopasuj", "Dopasuj widok do rysunku (klawisz 0)", () => this.fit()),
      this.button("home", "Reset", "Przywróć domyślny widok", () => this.resetCamera()),
      this.topButton,
      bgButton,
    );
    const help = h(
      "p",
      { id: "viewport-help", class: "sr-only" },
      "Przeciągnij, aby przesuwać (w 3D: obracać, a z Shiftem przesuwać). Kółko myszy lub szczypanie zmienia przybliżenie. Klawisze strzałek przesuwają lub obracają, plus i minus przybliżają, zero dopasowuje widok.",
    );
    this.el = h("div", { class: "viewport" }, this.canvas, this.controls, help);
    this.bindInput();
    this.syncMode();
    if (typeof ResizeObserver !== "undefined") {
      this.resizeObserver = new ResizeObserver(() => this.measure());
      this.resizeObserver.observe(this.el);
    }
  }

  private button(iconName: string, label: string, title: string, onClick: () => void): HTMLButtonElement {
    return h("button", { type: "button", class: "btn small ghost", title, "aria-label": title, onClick }, icon(iconName, 16), h("span", { class: "btn-label" }, label));
  }

  // ---- API ----

  setMode(mode: Mode): void {
    if (mode === this.mode) return;
    this.mode = mode;
    this.syncMode();
    this.autoFit = true;
    this.refit();
    this.requestRender();
  }

  /** Aktualizuje rysunek; przy włączonym automatycznym dopasowaniu śledzi granice. */
  setScene(scene: Scene): void {
    this.scene = scene;
    this.canvas.setAttribute(
      "aria-label",
      `Rysunek żółwia, tryb ${this.mode === "2d" ? "2D" : "3D"}: ${scene.segments.length} ${scene.segments.length === 1 ? "odcinek" : "odcinków"}`,
    );
    if (this.autoFit) this.refit();
    this.requestRender();
  }

  /** Dopasowuje widok do całego rysunku i włącza automatyczne śledzenie. */
  fit(): void {
    this.autoFit = true;
    this.lastFitKey = "";
    this.refit();
    this.requestRender();
  }

  resetCamera(): void {
    this.cam3d = defaultCamera3D();
    this.cam2d = { ...EMPTY_2D };
    this.fit();
  }

  setTopView(): void {
    if (this.mode !== "3d") return;
    this.cam3d = topView(this.cam3d);
    this.autoFit = true;
    this.lastFitKey = "";
    this.refit();
    this.requestRender();
  }

  zoom(factor: number): void {
    this.autoFit = false;
    if (this.mode === "2d") this.cam2d = zoomAt(this.cam2d, this.width, this.height, this.width / 2, this.height / 2, factor);
    else this.cam3d = zoom3D(this.cam3d, 1 / factor);
    this.requestRender();
  }

  requestRender(): void {
    if (this.raf) return;
    this.raf = requestAnimationFrame(() => {
      this.raf = 0;
      this.renderNow();
    });
  }

  /** Rysuje od razu i zwraca obietnicę spełnioną, gdy klatka trafiła na ekran. */
  present(): Promise<void> {
    this.measure();
    this.renderNow();
    return new Promise((resolve) => {
      const done = () => resolve();
      const timer = setTimeout(done, 300);
      requestAnimationFrame(() =>
        requestAnimationFrame(() => {
          clearTimeout(timer);
          done();
        }),
      );
    });
  }

  /** Obraz PNG bieżącego widoku (bez żółwia). */
  exportPng(): Promise<Blob | null> {
    this.renderNow(true);
    return new Promise((resolve) => {
      if (!this.canvas.toBlob) return resolve(null);
      this.canvas.toBlob((blob) => {
        this.renderNow();
        resolve(blob);
      }, "image/png");
    });
  }

  focus(): void {
    this.canvas.focus();
  }

  destroy(): void {
    this.resizeObserver?.disconnect();
    if (this.raf) cancelAnimationFrame(this.raf);
  }

  // ---- wewnętrzne ----

  private syncMode(): void {
    this.el.dataset.mode = this.mode;
    this.topButton.hidden = this.mode !== "3d";
  }

  private cycleBackground(): void {
    const order: CanvasBackground[] = ["auto", "light", "dark"];
    const next = order[(order.indexOf(this.options.getBackground()) + 1) % order.length];
    this.options.setBackground(next);
    this.requestRender();
  }

  private measure(): void {
    const rect = this.el.getBoundingClientRect();
    const w = Math.max(0, Math.floor(rect.width));
    const hh = Math.max(0, Math.floor(rect.height));
    const dpr = Math.min(3, window.devicePixelRatio || 1);
    if (w === this.width && hh === this.height && dpr === this.dpr) return;
    this.width = w;
    this.height = hh;
    this.dpr = dpr;
    this.canvas.width = Math.max(1, Math.round(w * dpr));
    this.canvas.height = Math.max(1, Math.round(hh * dpr));
    this.canvas.style.width = `${w}px`;
    this.canvas.style.height = `${hh}px`;
    if (this.autoFit && w > 0 && hh > 0) {
      this.lastFitKey = "";
      this.refit();
    }
    this.requestRender();
  }

  private sceneBounds() {
    const b = boundsOf(this.scene.segments);
    const t = this.scene.turtle.position;
    if (b) {
      for (let k = 0; k < 3; k++) {
        b.min[k] = Math.min(b.min[k], t[k]);
        b.max[k] = Math.max(b.max[k], t[k]);
      }
    }
    return b;
  }

  /** Dopasowuje kamerę do rysunku, jeśli granice się zmieniły od ostatniego dopasowania. */
  private refit(): void {
    if (this.width === 0 || this.height === 0) {
      this.fitPending = true;
      return;
    }
    this.fitPending = false;
    const b = this.sceneBounds();
    const empty = this.scene.segments.length === 0;
    const key = `${this.mode}|${this.width}x${this.height}|${empty ? "empty" : JSON.stringify(b)}`;
    if (key === this.lastFitKey) return;
    this.lastFitKey = key;
    if (this.mode === "2d") this.cam2d = empty ? { ...EMPTY_2D } : fitCamera2D(b, this.width, this.height);
    else this.cam3d = empty ? { ...defaultCamera3D(), yaw: this.cam3d.yaw, pitch: this.cam3d.pitch } : fitCamera3D(b, this.width, this.height, this.cam3d);
  }

  private renderNow(forExport = false): void {
    if (!this.ctx) return;
    if (this.fitPending) this.refit();
    const ctx = this.ctx;
    const pal = paletteFor(this.options.getTheme(), this.options.getBackground());
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    const scene = forExport ? { ...this.scene, showTurtle: false, ghost: undefined } : this.scene;
    if (this.mode === "2d") {
      drawScene2D(ctx, this.cam2d, this.width, this.height, scene, pal);
    } else {
      const b = this.sceneBounds();
      const extent = b ? Math.max(100, ...b.min.map(Math.abs), ...b.max.map(Math.abs)) : 100;
      drawScene3D(ctx, this.cam3d, this.width, this.height, scene, pal, extent);
    }
  }

  // ---- wejście: mysz, dotyk, klawiatura ----

  private bindInput(): void {
    const c = this.canvas;
    c.addEventListener("contextmenu", (e) => e.preventDefault());
    c.addEventListener("pointerdown", (e) => {
      c.focus({ preventScroll: true });
      c.setPointerCapture?.(e.pointerId);
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      this.pinch = this.pointers.size === 2 ? this.pinchState() : null;
      this.el.classList.add("dragging");
    });
    c.addEventListener("pointermove", (e) => {
      const prev = this.pointers.get(e.pointerId);
      if (!prev) return;
      const cur = { x: e.clientX, y: e.clientY };
      this.pointers.set(e.pointerId, cur);
      if (this.pointers.size === 1) {
