/** Czyste funkcje edycji tekstu w edytorze (testowalne bez DOM). */
export interface Edit {
  from: number;
  to: number;
  insert: string;
  selStart: number;
  selEnd: number;
}

export function applyEdit(text: string, e: Edit): { text: string; selStart: number; selEnd: number } {
  return { text: text.slice(0, e.from) + e.insert + text.slice(e.to), selStart: e.selStart, selEnd: e.selEnd };
}

const INDENT = "  ";

/** Tab / Shift+Tab: wcięcie lub zdjęcie wcięcia z zaznaczonych wierszy. */
export function indentEdit(text: string, start: number, end: number, outdent: boolean): Edit | null {
  if (!outdent && start === end) {
    return { from: start, to: start, insert: INDENT, selStart: start + INDENT.length, selEnd: start + INDENT.length };
  }
  const firstLineStart = text.lastIndexOf("\n", start - 1) + 1;
  // Zaznaczenie kończące się tuż po nowym wierszu nie obejmuje już następnego wiersza.
  const lastPos = end > start && text[end - 1] === "\n" ? end - 1 : end;
  const nl = text.indexOf("\n", lastPos);
  const lastLineEnd = nl === -1 ? text.length : nl;
  const lines = text.slice(firstLineStart, lastLineEnd).split("\n");
  const changed = lines.map((l) => (outdent ? l.replace(/^ {1,2}/, "") : l.length ? INDENT + l : l));
  if (changed.every((l, i) => l === lines[i])) return null;
  const insert = changed.join("\n");
  const total = insert.length - (lastLineEnd - firstLineStart);
  const firstDelta = changed[0].length - lines[0].length;
  const selStart = Math.max(firstLineStart, start + firstDelta);
  const selEnd = Math.max(selStart, end + total);
  return { from: firstLineStart, to: lastLineEnd, insert, selStart, selEnd };
}

/** Enter: nowy wiersz z wcięciem poprzedniego (plus jedno po „[” lub nagłówku oto). */
export function newlineEdit(text: string, start: number, end: number): Edit {
  const lineStart = text.lastIndexOf("\n", start - 1) + 1;
  const before = text.slice(lineStart, start);
  const lead = /^[ \t]*/.exec(text.slice(lineStart))![0];
  const indent = lead.slice(0, before.length);
  const extra = /\[\s*$/.test(before) || /^\s*(oto|to)\b/i.test(before) ? INDENT : "";
  const insert = "\n" + indent + extra;
  const caret = start + insert.length;
  return { from: start, to: end, insert, selStart: caret, selEnd: caret };
}

/** Przesunięcie w tekście dla (wiersz, kolumna) liczonych od 1; poza tekstem zwraca koniec wiersza lub tekstu. */
export function positionToOffset(text: string, line: number, column: number): number {
  let offset = 0;
  for (let l = 1; l < line; l++) {
    const nl = text.indexOf("\n", offset);
    if (nl === -1) return text.length;
    offset = nl + 1;
  }
  const nl = text.indexOf("\n", offset);
  const lineEnd = nl === -1 ? text.length : nl;
  return Math.min(offset + Math.max(0, column - 1), lineEnd);
}

export function offsetToPosition(text: string, offset: number): { line: number; column: number } {
  const before = text.slice(0, offset);
  const line = before.split("\n").length;
  return { line, column: offset - (before.lastIndexOf("\n") + 1) + 1 };
}
