import type { LogoErrorInfo } from "../lang";
import { highlight, type Span, type SpanKind } from "../lang/highlight";
import { matchShortcut, type Action } from "../app/shortcuts";
import { h } from "./dom";
import { applyEdit, indentEdit, newlineEdit, positionToOffset, type Edit } from "./editing";

export interface EditorOptions {
  label: string;
  onChange(text: string): void;
  onShortcut(action: Action): void;
}

const LINE_HEIGHT = 22;
const PAD_TOP = 10;

const ESCAPES: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;" };
const esc = (s: string) => s.replace(/[&<>]/g, (c) => ESCAPES[c]);

/** Zakres do podkreślenia dla błędu na (wiersz, kolumna): token w tym miejscu lub jeden znak. */
export function errorRange(text: string, spans: readonly Span[], line: number, column: number): [number, number] | null {
  const offset = positionToOffset(text, line, column);
  const hit = spans.find((s) => s.start <= offset && offset < s.end);
  if (hit) return [hit.start, hit.end];
  if (offset < text.length && text[offset] !== "\n") return [offset, offset + 1];
  const lineStart = text.lastIndexOf("\n", offset - 1) + 1;
  return offset > lineStart ? [offset - 1, offset] : null;
}

/** HTML warstwy podświetlenia z opcjonalnym zakresem błędu. */
export function highlightHtml(text: string, spans: readonly Span[], err: [number, number] | null): string {
  type Piece = { start: number; end: number; kind: SpanKind | null };
  const pieces: Piece[] = [];
  let pos = 0;
  for (const s of spans) {
    if (s.start > pos) pieces.push({ start: pos, end: s.start, kind: null });
    pieces.push({ start: s.start, end: s.end, kind: s.kind });
    pos = s.end;
  }
  if (pos < text.length) pieces.push({ start: pos, end: text.length, kind: null });
  let out = "";
  const emit = (a: number, b: number, kind: SpanKind | null, bad: boolean) => {
    if (b <= a) return;
    const cls = [kind ? `tok-${kind}` : "", bad ? "tok-error" : ""].filter(Boolean).join(" ");
    const t = esc(text.slice(a, b));
    out += cls ? `<span class="${cls}">${t}</span>` : t;
  };
  for (const p of pieces) {
    if (!err || err[1] <= p.start || err[0] >= p.end) {
      emit(p.start, p.end, p.kind, false);
      continue;
    }
    const a = Math.max(p.start, err[0]);
    const b = Math.min(p.end, err[1]);
    emit(p.start, a, p.kind, false);
    emit(a, b, p.kind, true);
    emit(b, p.end, p.kind, false);
  }
  return out;
}

/** Edytor kodu: textarea z przezroczystym tekstem nad warstwą podświetlenia, z numerami wierszy. */
export class CodeEditor {
  readonly el: HTMLElement;
  private readonly textarea: HTMLTextAreaElement;
  private readonly pre: HTMLPreElement;
  private readonly layer: HTMLElement;
  private readonly gutter: HTMLElement;
  private readonly execBand: HTMLElement;
  private readonly errorBand: HTMLElement;
  private lineCount = 0;
  private error: LogoErrorInfo | null = null;
  private execLine: number | null = null;
  private tabEscapes = false;
  private markedGutter: HTMLElement[] = [];

  constructor(private readonly options: EditorOptions) {
    this.pre = h("pre", { class: "editor-highlight", "aria-hidden": "true" });
    this.execBand = h("div", { class: "editor-band exec-band", hidden: true });
    this.errorBand = h("div", { class: "editor-band error-band", hidden: true });
    this.layer = h("div", { class: "editor-layer", "aria-hidden": "true" }, this.execBand, this.errorBand, this.pre);
    this.gutter = h("div", { class: "editor-gutter-inner" });
    this.textarea = h("textarea", {
      class: "editor-input",
      spellcheck: "false",
      autocomplete: "off",
      autocapitalize: "off",
      autocorrect: "off",
      wrap: "off",
      "aria-label": options.label,
      "aria-describedby": "editor-help",
      "aria-multiline": "true",
    });
    this.el = h(
      "div",
      { class: "editor" },
      h("div", { class: "editor-gutter", "aria-hidden": "true" }, this.gutter),
      h("div", { class: "editor-scroll" }, this.layer, this.textarea),
      h(
        "p",
        { id: "editor-help", class: "sr-only" },
        "Edytor programu w Logo. Skróty: Ctrl+Enter uruchamia, F10 wykonuje krok, F9 pauzuje, F8 zeruje. Tab wstawia wcięcie; aby opuścić edytor klawiaturą, naciśnij Escape, a potem Tab.",
      ),
    );
    this.textarea.addEventListener("input", () => {
      this.render();
      this.options.onChange(this.textarea.value);
    });
    this.textarea.addEventListener("scroll", () => this.syncScroll());
    this.textarea.addEventListener("keydown", (e) => this.onKeyDown(e));
    this.textarea.addEventListener("blur", () => (this.tabEscapes = false));
    this.render();
  }

  getValue(): string {
    return this.textarea.value;
  }

  /** Ustawia treść (np. po wczytaniu przykładu); nie wywołuje onChange. */
  setValue(text: string): void {
    if (this.textarea.value === text) return;
    this.textarea.value = text;
    this.render();
  }

  setError(error: LogoErrorInfo | null): void {
    this.error = error;
    this.render();
  }

  /** Podświetla wiersz właśnie wykonanego polecenia (null = brak). */
  setExecLine(line: number | null): void {
    this.execLine = line;
    this.renderBands();
    if (line !== null) this.scrollToLine(line);
  }

  focus(): void {
    this.textarea.focus();
  }

  /** Ustawia kursor na (wiersz, kolumna) i przenosi na niego fokus. */
  focusAt(line: number, column: number): void {
