const ESCAPES: Record<string, string> = { "&": "&amp;", "<": "&lt;", ">": "&gt;" };
const esc = (s: string) => s.replace(/[&<>]/g, (c) => ESCAPES[c]);

/** Zakres do podkreślenia dla błędu na (wiersz, kolumna): token w tym miejscu lub jeden znak. */
export function errorRange(text: string, spans: readonly Span[], line: number, column: number): [number, number] | null {
  const offset = positionToOffset(text, line, column);
  const hit = spans.find((s) => s.start <= offset && offset < s.end);
  if (hit) return [hit.start, hit.end];
  if (offset < text.length && text[offset] !== "\n") return [offset, offset + 1];
  const lineStart = text.lastIndexOf("\n", offset - 1) + 1;
  return offset > lineStart ? [offset - 1, offset] : null;
}

/** HTML warstwy podświetlenia z opcjonalnym zakresem błędu. */
export function highlightHtml(text: string, spans: readonly Span[], err: [number, number] | null): string {
  type Piece = { start: number; end: number; kind: SpanKind | null };
  const pieces: Piece[] = [];
  let pos = 0;
  for (const s of spans) {
    if (s.start > pos) pieces.push({ start: pos, end: s.start, kind: null });
    pieces.push({ start: s.start, end: s.end, kind: s.kind });
    pos = s.end;
  }
  if (pos < text.length) pieces.push({ start: pos, end: text.length, kind: null });
  let out = "";
  const emit = (a: number, b: number, kind: SpanKind | null, bad: boolean) => {
    if (b <= a) return;
    const cls = [kind ? `tok-${kind}` : "", bad ? "tok-error" : ""].filter(Boolean).join(" ");
    const t = esc(text.slice(a, b));
    out += cls ? `<span class="${cls}">${t}</span>` : t;
  };
  for (const p of pieces) {
    if (!err || err[1] <= p.start || err[0] >= p.end) {
      emit(p.start, p.end, p.kind, false);
      continue;
    }
    const a = Math.max(p.start, err[0]);
    const b = Math.min(p.end, err[1]);
    emit(p.start, a, p.kind, false);
    emit(a, b, p.kind, true);
    emit(b, p.end, p.kind, false);
  }
  return out;
