import { safeGet, safeSet, type KeyValueStore } from "../app/storage";
import type { CanvasBackground } from "../view/palette";

export type ThemePref = "system" | "light" | "dark";

const KEY_THEME = "logomocja:v1:theme";
const KEY_BG = "logomocja:v1:canvas-bg";

/** Motyw interfejsu: automatyczny (system), jasny albo ciemny; z zapamiętaniem wyboru. */
export class ThemeManager {
  private pref: ThemePref;
  private background: CanvasBackground;
  private listeners = new Set<() => void>();
  private media: MediaQueryList | null;

  constructor(private readonly store: KeyValueStore) {
    const t = safeGet(store, KEY_THEME);
    this.pref = t === "light" || t === "dark" ? t : "system";
    const b = safeGet(store, KEY_BG);
    this.background = b === "light" || b === "dark" ? b : "auto";
    this.media = typeof matchMedia === "function" ? matchMedia("(prefers-color-scheme: dark)") : null;
    this.media?.addEventListener?.("change", () => this.emit());
    this.apply();
  }

  get preference(): ThemePref {
    return this.pref;
  }

  get effective(): "light" | "dark" {
    if (this.pref !== "system") return this.pref;
    return this.media?.matches ? "dark" : "light";
  }

  get canvasBackground(): CanvasBackground {
    return this.background;
  }

  setPreference(pref: ThemePref): void {
    this.pref = pref;
    safeSet(this.store, KEY_THEME, pref);
    this.apply();
    this.emit();
  }

  /** Kolejno: automatyczny → jasny → ciemny. */
  cycle(): ThemePref {
    const next: ThemePref = this.pref === "system" ? "light" : this.pref === "light" ? "dark" : "system";
    this.setPreference(next);
    return next;
  }

  setCanvasBackground(value: CanvasBackground): void {
    this.background = value;
    safeSet(this.store, KEY_BG, value);
    this.emit();
  }

  onChange(listener: () => void): void {
    this.listeners.add(listener);
  }

  private apply(): void {
    const root = document.documentElement;
    if (this.pref === "system") root.removeAttribute("data-theme");
    else root.setAttribute("data-theme", this.pref);
  }

  private emit(): void {
    for (const l of [...this.listeners]) l();
  }
}

export const THEME_LABELS: Record<ThemePref, string> = {
  system: "automatyczny (jak w systemie)",
  light: "jasny",
  dark: "ciemny",
};
