import { h, icon } from "./dom";

export interface MenuItem {
  label: string;
  hint?: string;
  disabled?: boolean;
  run(): void;
}

/** Przycisk z rozwijanym menu (role=menu): strzałki, Home/End, Esc i kliknięcie poza menu. */
export function createMenu(label: string, getItems: () => MenuItem[], iconName = "menu"): HTMLElement {
  const list = h("div", { class: "menu-list", role: "menu", hidden: true });
  const button = h(
    "button",
    { type: "button", class: "btn", "aria-haspopup": "menu", "aria-expanded": "false" },
    icon(iconName, 18),
    h("span", { class: "btn-label" }, label),
  );
  const wrap = h("div", { class: "menu" }, button, list);

  const items = () => [...list.querySelectorAll<HTMLButtonElement>("button[role=menuitem]:not(:disabled)")];
  const close = (restoreFocus: boolean) => {
    list.hidden = true;
    button.setAttribute("aria-expanded", "false");
    document.removeEventListener("pointerdown", onOutside, true);
    if (restoreFocus) button.focus();
  };
  const onOutside = (e: Event) => {
    if (!wrap.contains(e.target as Node)) close(false);
  };
  const open = () => {
    list.replaceChildren(
      ...getItems().map((item) =>
        h(
          "button",
          {
            type: "button",
            role: "menuitem",
            class: "menu-item",
            disabled: item.disabled,
            tabindex: "-1",
            onClick: () => {
              close(true);
              item.run();
            },
          },
          h("span", null, item.label),
          item.hint ? h("small", null, item.hint) : null,
        ),
      ),
    );
    list.hidden = false;
    button.setAttribute("aria-expanded", "true");
    document.addEventListener("pointerdown", onOutside, true);
    items()[0]?.focus();
  };

  button.addEventListener("click", () => (list.hidden ? open() : close(true)));
  button.addEventListener("keydown", (e) => {
    if (e.key === "ArrowDown" && list.hidden) {
      e.preventDefault();
      open();
    }
  });
  list.addEventListener("keydown", (e) => {
    const all = items();
    const i = all.indexOf(document.activeElement as HTMLButtonElement);
    if (e.key === "ArrowDown") all[(i + 1) % all.length]?.focus();
    else if (e.key === "ArrowUp") all[(i - 1 + all.length) % all.length]?.focus();
    else if (e.key === "Home") all[0]?.focus();
    else if (e.key === "End") all[all.length - 1]?.focus();
    else if (e.key === "Escape") close(true);
    else if (e.key === "Tab") close(false);
    else return;
    if (e.key !== "Tab") e.preventDefault();
  });
  return wrap;
}
