  /** Kolejno: automatyczny → jasny → ciemny. */
  cycle(): ThemePref {
    const next: ThemePref = this.pref === "system" ? "light" : this.pref === "light" ? "dark" : "system";
    this.setPreference(next);
    return next;
  }

  setCanvasBackground(value: CanvasBackground): void {
    this.background = value;
    safeSet(this.store, KEY_BG, value);
    this.emit();
  }

  onChange(listener: () => void): void {
    this.listeners.add(listener);
  }

  private apply(): void {
    const root = document.documentElement;
    if (this.pref === "system") root.removeAttribute("data-theme");
    else root.setAttribute("data-theme", this.pref);
  }

  private emit(): void {
    for (const l of [...this.listeners]) l();
  }
}

export const THEME_LABELS: Record<ThemePref, string> = {
  system: "automatyczny (jak w systemie)",
  light: "jasny",
  dark: "ciemny",
};
