import { h } from "./dom";

export interface DialogAction {
  label: string;
  value: string;
  primary?: boolean;
}

let counter = 0;

/**
 * Okno modalne oparte na <dialog>: przeglądarka zapewnia pułapkę fokusu, Esc i zasłonięcie tła.
 * Obietnica spełnia się wartością klikniętego przycisku albo null (Esc / zamknięcie).
 */
export function showDialog(options: {
  title: string;
  body: Node | string;
  actions: DialogAction[];
  wide?: boolean;
}): Promise<string | null> {
  return new Promise((resolve) => {
    const titleId = `dialog-title-${++counter}`;
    let result: string | null = null;
    const dialog = h("dialog", { class: `dialog${options.wide ? " wide" : ""}`, "aria-labelledby": titleId });
    const buttons = options.actions.map((a) =>
      h(
        "button",
        {
          type: "button",
          class: `btn${a.primary ? " primary" : ""}`,
          onClick: () => {
            result = a.value;
            dialog.close ? dialog.close() : dialog.removeAttribute("open");
            finish();
          },
        },
        a.label,
      ),
    );
    const body = typeof options.body === "string" ? h("p", null, options.body) : options.body;
    dialog.append(
      h("h2", { id: titleId, class: "dialog-title" }, options.title),
      h("div", { class: "dialog-body" }, body),
      h("div", { class: "dialog-actions" }, ...buttons),
    );
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      dialog.remove();
      resolve(result);
    };
    dialog.addEventListener("close", finish);
    dialog.addEventListener("cancel", () => {
      result = null;
    });
    document.body.appendChild(dialog);
    if (typeof dialog.showModal === "function") dialog.showModal();
    else dialog.setAttribute("open", "");
    (buttons.find((_, i) => options.actions[i].primary) ?? buttons[0])?.focus();
  });
}
