import { h } from "./dom";

export interface Toaster {
  show(message: string, action?: { label: string; run(): void }): void;
}

/** Krótkie komunikaty w regionie aria-live; mogą mieć jeden przycisk akcji (np. „Przywróć”). */
export function createToaster(container: HTMLElement): Toaster {
  return {
    show(message, action) {
      const toast = h("div", { class: "toast" }, h("span", null, message));
      let timer = 0;
      const remove = () => {
        window.clearTimeout(timer);
        toast.remove();
      };
      if (action) {
        toast.appendChild(
          h(
            "button",
            {
              type: "button",
              class: "btn small",
              onClick: () => {
                action.run();
                remove();
              },
            },
            action.label,
          ),
        );
      }
      container.appendChild(toast);
      timer = window.setTimeout(remove, action ? 12000 : 6000);
    },
  };
}
