import type { Mode, Segment } from "../lang";
import { boundsOf } from "./bounds";
import { fitCamera2D, toScreen } from "./camera2d";
import { defaultCamera3D, fitCamera3D, projectSegment } from "./camera3d";
import { DARK_PALETTE, LIGHT_PALETTE } from "./palette";

/** Miniatura rysunku (bez siatki i osi) do galerii, wyzwań i dokumentacji. */
export function drawThumbnail(
  canvas: HTMLCanvasElement,
  segments: readonly Segment[],
  mode: Mode,
  theme: "light" | "dark",
): void {
  const ctx = typeof canvas.getContext === "function" ? canvas.getContext("2d") : null;
  if (!ctx) return;
  const cssW = Number(canvas.dataset.w ?? canvas.getAttribute("width") ?? 160);
  const cssH = Number(canvas.dataset.h ?? canvas.getAttribute("height") ?? 110);
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  canvas.style.width = `${cssW}px`;
  canvas.style.height = `${cssH}px`;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const pal = theme === "dark" ? DARK_PALETTE : LIGHT_PALETTE;
  ctx.fillStyle = pal.bg;
  ctx.fillRect(0, 0, cssW, cssH);
  const bounds = boundsOf(segments, false);
  if (!bounds) return;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  let project: (s: Segment) => [number, number, number, number] | null;
  if (mode === "2d") {
    const cam = fitCamera2D(bounds, cssW, cssH, 0.12);
    project = (s) => {
      const [ax, ay] = toScreen(cam, cssW, cssH, s.from[0], s.from[1]);
      const [bx, by] = toScreen(cam, cssW, cssH, s.to[0], s.to[1]);
      return [ax, ay, bx, by];
    };
  } else {
    const cam = fitCamera3D(bounds, cssW, cssH, defaultCamera3D());
    project = (s) => {
      const seg = projectSegment(cam, cssW, cssH, s.from, s.to);
      return seg ? [seg[0].x, seg[0].y, seg[1].x, seg[1].y] : null;
    };
  }
  let style = "";
  let open = false;
  for (const s of segments) {
    const p = project(s);
    if (!p) continue;
    const lw = Math.max(1, Math.min(2.5, s.width * 0.55));
    const key = `${s.color}|${lw}`;
    if (key !== style) {
      if (open) ctx.stroke();
      ctx.beginPath();
      ctx.strokeStyle = s.color;
      ctx.lineWidth = lw;
      style = key;
      open = true;
    }
    ctx.moveTo(p[0], p[1]);
    ctx.lineTo(p[2], p[3]);
  }
  if (open) ctx.stroke();
}
