cat > workspace-page.ts <<'EOF'
import { startSession, type LogoErrorInfo, type Mode } from "../lang";
import {
  challengeTarget,
  checkChallenge,
  loadChallengeDraft,
  saveChallengeDraft,
  type Challenge,
} from "../app/challenges";
import type { ControllerState } from "../app/controller";
import { CHALLENGES } from "../app/challenges";
import { SHORTCUTS, type Action } from "../app/shortcuts";
import { formatRoute } from "../app/router";
import { safeGet, safeSet } from "../app/storage";
import { drawThumbnail } from "../view/thumb";
import { Viewport } from "../view/viewport";
import type { Scene } from "../view/scene";
import type { AppContext } from "./context";
import { showDialog } from "./dialog";
import { download, h, icon } from "./dom";
import { CodeEditor } from "./editor";
import { createMenu } from "./menu";

/** Polecenia na sekundę dla kolejnych położeń suwaka; ostatnie to „natychmiast”. */
const SPEED_LEVELS = [3, 8, 20, 50, 120, 300, 800, 2500, Infinity];
const DEFAULT_SPEED_LEVEL = 4;
const MAX_ANIMATION_SECONDS = 12;
const KEY_SPEED = "logomocja:v1:speed";

const speedText = (level: number) =>
  SPEED_LEVELS[level] === Infinity ? "natychmiast" : `${SPEED_LEVELS[level]} poleceń na sekundę`;

/** Ile operacji wykona program (do dobrania tempa animacji); 0 przy błędzie składni. */
function estimateOps(source: string, mode: Mode): number {
  const started = startSession(source, mode);
  if (!started.ok) return 0;
  while (started.session.step());
  return started.session.ops;
}

export class WorkspacePage {
  readonly el: HTMLElement;
  private readonly editor: CodeEditor;
  private readonly viewport: Viewport;
  private readonly status = h("div", { class: "statusbar", role: "status", "aria-live": "polite" });
  private readonly challengePanel = h("section", { class: "challenge-panel", hidden: true, "aria-label": "Zadanie" });
  private readonly runBtn: HTMLButtonElement;
  private readonly stepBtn: HTMLButtonElement;
  private readonly pauseBtn: HTMLButtonElement;
  private readonly resetBtn: HTMLButtonElement;
  private readonly speed: HTMLInputElement;
  private readonly speedOut: HTMLOutputElement;
  private readonly modeInputs: Record<Mode, HTMLInputElement>;
  private readonly modeGroup: HTMLElement;
  private readonly paneButtons: Record<"code" | "view", HTMLButtonElement>;
  private readonly fileInput: HTMLInputElement;
  private challenge: Challenge | null = null;
  private showGhost = true;
  private lintError: LogoErrorInfo | null = null;
  private lintTimer = 0;
  private raf = 0;
  private lastFrame = 0;
  private lastState: ControllerState | null = null;

  constructor(private readonly ctx: AppContext) {
    const { studio, theme } = ctx;
    this.editor = new CodeEditor({
      label: "Kod programu w Logo",
      onChange: (text) => this.onEdit(text),
      onShortcut: (action) => this.dispatch(action),
    });
    this.viewport = new Viewport({
      getTheme: () => theme.effective,
      getBackground: () => theme.canvasBackground,
      setBackground: (v) => theme.setCanvasBackground(v),
    });
    theme.onChange(() => this.viewport.requestRender());

    const shortcutHint = (action: Action) => SHORTCUTS.find((s) => s.action === action)!.keys.join(" lub ");
    this.runBtn = h("button", { type: "button", class: "btn primary", title: `Uruchom program (${shortcutHint("run")})`, onClick: () => this.dispatch("run") }, icon("play"), h("span", { class: "btn-label" }, "Uruchom"));
    this.stepBtn = h("button", { type: "button", class: "btn", title: `Wykonaj jeden krok (${shortcutHint("step")})`, onClick: () => this.dispatch("step") }, icon("step"), h("span", { class: "btn-label" }, "Krok"));
    this.pauseBtn = h("button", { type: "button", class: "btn", title: `Pauza / wznów (${shortcutHint("pause-resume")})`, onClick: () => this.dispatch("pause-resume") }, icon("pause"), h("span", { class: "btn-label" }, "Pauza"));
    this.resetBtn = h("button", { type: "button", class: "btn", title: `Zeruj: przerwij i wyczyść rysunek (${shortcutHint("reset")})`, onClick: () => this.dispatch("reset") }, icon("reset"), h("span", { class: "btn-label" }, "Reset"));

    const storedLevel = Number(safeGet(ctx.store, KEY_SPEED));
    const level = Number.isInteger(storedLevel) && storedLevel >= 0 && storedLevel < SPEED_LEVELS.length ? storedLevel : DEFAULT_SPEED_LEVEL;
    this.speed = h("input", {
      type: "range",
      id: "speed-input",
      min: "0",
      max: String(SPEED_LEVELS.length - 1),
      step: "1",
      value: String(level),
      "aria-valuetext": speedText(level),
    });
    this.speedOut = h("output", { for: "speed-input", class: "speed-out" }, speedText(level));
    this.speed.addEventListener("input", () => {
      const l = Number(this.speed.value);
      this.speed.setAttribute("aria-valuetext", speedText(l));
      this.speedOut.textContent = speedText(l);
      safeSet(ctx.store, KEY_SPEED, String(l));
      this.applySpeed();
    });

    const radio = (mode: Mode) =>
      h("input", { type: "radio", name: "mode", value: mode, id: `mode-${mode}`, onChange: () => this.switchMode(mode) });
    this.modeInputs = { "2d": radio("2d"), "3d": radio("3d") };
    this.modeGroup = h(
      "fieldset",
      { class: "mode-switch" },
      h("legend", { class: "sr-only" }, "Tryb rysowania"),
      this.modeInputs["2d"],
      h("label", { for: "mode-2d", title: "Płaszczyzna: oś X w prawo, Y w górę" }, "2D"),
      this.modeInputs["3d"],
      h("label", { for: "mode-3d", title: "Przestrzeń: dodatkowo oś Z i obroty gora, dol, pp, pl" }, "3D"),
    );

    this.fileInput = h("input", {
      type: "file",
      accept: ".logo,.txt,text/plain",
      class: "sr-only",
      tabindex: "-1",
      "aria-label": "Wybierz plik .logo do otwarcia",
      onChange: () => void this.onFileChosen(),
    });
    const fileMenu = createMenu(
      "Plik",
      () => [
        { label: "Udostępnij link…", hint: "kodowany w adresie", run: () => void this.share() },
        { label: "Pobierz program (.logo)", run: () => this.downloadProgram() },
        { label: "Otwórz plik .logo…", run: () => this.fileInput.click() },
        { label: "Eksportuj rysunek (PNG)", run: () => void this.exportPng() },
        { label: "Przywróć poprzedni szkic", hint: "kopia sprzed ostatniej podmiany", disabled: !this.currentBackupAvailable(), run: () => this.restoreBackup() },
        { label: "Skróty klawiaturowe…", run: () => void this.showShortcuts() },
      ],
      "menu",
    );

    const toolbar = h(
      "div",
      { class: "toolbar", role: "toolbar", "aria-label": "Sterowanie programem" },
      this.runBtn,
      this.stepBtn,
      this.pauseBtn,
      this.resetBtn,
      h("div", { class: "speed" }, h("label", { for: "speed-input" }, "Szybkość"), this.speed, this.speedOut),
      this.modeGroup,
      fileMenu,
    );

    const paneSwitch = h(
      "div",
      { class: "pane-switch", role: "group", "aria-label": "Który panel pokazać" },
      (this.paneButtons = {
        code: h("button", { type: "button", class: "btn", "aria-pressed": "true", onClick: () => this.showPane("code") }, "Kod"),
        view: h("button", { type: "button", class: "btn", "aria-pressed": "false", onClick: () => this.showPane("view") }, "Rysunek"),
      }).code,
      this.paneButtons.view,
    );

    this.el = h(
      "section",
      { class: "studio", "data-pane": "code", "aria-label": "Pracownia" },
      this.challengePanel,
      toolbar,
      paneSwitch,
      h(
        "div",
        { class: "panes" },
        h("div", { class: "pane pane-code" }, this.editor.el, this.status),
        h("div", { class: "pane pane-view" }, this.viewport.el),
      ),
      this.fileInput,
    );

    studio.controller.subscribe((state) => this.onState(state));
    this.syncFromWorkspace();
    this.applySpeed();
    studio.controller.runToEnd(); // pierwszy ekran nie jest pusty
    this.viewport.fit();
  }

  // ---- API dla aplikacji ----

  /** Wybiera kontekst: swobodna pracownia (null) albo wyzwanie. */
  setChallenge(challenge: Challenge | null): void {
    if (this.challenge?.id === challenge?.id && this.challengePanel.hidden === !challenge) return;
    this.challenge = challenge;
    this.renderChallengePanel();
    this.syncFromWorkspace();
    this.ctx.studio.controller.runToEnd();
    this.viewport.fit();
  }

  /** Odtwarza edytor, tryb i kontroler ze stanu pracowni (po wczytaniu przykładu, pliku, linku). */
  syncFromWorkspace(): void {
    const ws = this.ctx.studio.workspace;
    const mode: Mode = this.challenge ? this.challenge.mode : ws.mode;
    const source = this.challenge ? loadChallengeDraft(this.ctx.store, this.challenge.id) : ws.source;
    this.modeInputs[mode].checked = true;
    this.modeGroup.hidden = !!this.challenge;
    this.viewport.setMode(mode);
    this.editor.setValue(source);
    this.lintError = null;
    this.ctx.studio.controller.reset();
    this.ctx.studio.controller.setProgram(source, mode);
    this.scheduleLint();
    this.applySpeed();
  }

  /** Pokazuje gotowy rysunek: dopasowanie widoku i narysowanie klatki. */
  async present(): Promise<void> {
    this.viewport.fit();
    await this.viewport.present();
  }

  runInstantly(): void {
    this.ctx.studio.controller.runToEnd();
    this.viewport.fit();
  }

  runAnimated(): void {
    this.dispatch("run");
  }

  focusEditor(): void {
    this.editor.focus();
  }

  // ---- sterowanie ----

  private get controller() {
    return this.ctx.studio.controller;
  }

  private currentMode(): Mode {
    return this.challenge ? this.challenge.mode : this.ctx.studio.workspace.mode;
  }

  dispatch(action: Action): void {
    const c = this.controller;
    switch (action) {
      case "run":
        this.applySpeed();
        c.run();
        if (c.state.status === "failed") {
          this.showPane("code");
          this.editor.focusAt(c.state.error!.line, c.state.error!.column);
        } else if (this.isNarrow()) this.showPane("view");
        break;
      case "step":
        c.step();
        break;
      case "pause-resume":
        if (c.state.status === "running") c.pause();
        else if (c.state.status === "paused") c.resume();
        break;
      case "reset":
        c.reset();
        break;
    }
  }

  private applySpeed(): void {
    const base = SPEED_LEVELS[Number(this.speed.value)];
    if (base === Infinity) {
      this.controller.setSpeed(Infinity);
      return;
    }
    // Duże programy przyspieszają same, by animacja nie trwała dłużej niż kilkanaście sekund.
    const total = estimateOps(this.editor.getValue(), this.currentMode());
    this.controller.setSpeed(Math.max(base, total / MAX_ANIMATION_SECONDS));
  }

  private onEdit(text: string): void {
    if (this.challenge) saveChallengeDraft(this.ctx.store, this.challenge.id, text);
    else this.ctx.studio.workspace.setSource(text);
    this.lintError = null;
    this.controller.setProgram(text, this.currentMode());
    this.scheduleLint();
  }

  private scheduleLint(): void {
    window.clearTimeout(this.lintTimer);
    this.lintTimer = window.setTimeout(() => {
      const started = startSession(this.editor.getValue(), this.currentMode());
      this.lintError = started.ok ? null : started.error;
      this.refreshError();
      if (this.lastState) this.renderStatus(this.lastState);
    }, 220);
  }

  private refreshError(): void {
    this.editor.setError(this.controller.state.error ?? this.lintError);
  }

  private switchMode(mode: Mode): void {
    if (this.challenge) return;
    this.ctx.studio.workspace.setMode(mode);
    this.syncFromWorkspace();
    this.controller.runToEnd();
    this.viewport.fit();
  }

  private showPane(pane: "code" | "view"): void {
    this.el.dataset.pane = pane;
    this.paneButtons.code.setAttribute("aria-pressed", String(pane === "code"));
    this.paneButtons.view.setAttribute("aria-pressed", String(pane === "view"));
    if (pane === "view") this.viewport.requestRender();
  }

  private isNarrow(): boolean {
    return typeof matchMedia === "function" && matchMedia("(max-width: 860px)").matches;
  }

  // ---- stan kontrolera -> interfejs ----

  private onState(state: ControllerState): void {
    this.lastState = state;
    const running = state.status === "running";
    const paused = state.status === "paused";
    const finished = state.status === "finished" || state.status === "failed";
    this.stepBtn.disabled = finished;
    this.pauseBtn.disabled = !(running || paused);
    const pauseLabel = this.pauseBtn.querySelector(".btn-label")!;
    pauseLabel.textContent = paused ? "Wznów" : "Pauza";
    this.resetBtn.disabled = state.status === "idle" && state.segments.length === 0 && !state.error;
    this.editor.setExecLine(running || paused ? state.line : null);
    this.refreshError();
    const scene: Scene = {
      segments: state.segments,
      turtle: state.turtle,
      ghost: this.challenge && this.showGhost ? challengeTarget(this.challenge) : undefined,
      showTurtle: true,
    };
    this.viewport.setScene(scene);
    this.renderStatus(state);
    if (running) this.startLoop();
  }

  private renderStatus(state: ControllerState): void {
    const err = state.error ?? this.lintError;
    const bar = this.status;
    bar.classList.toggle("is-error", !!err);
    bar.replaceChildren();
    if (err) {
      const where = `wiersz ${err.line}, kolumna ${err.column}`;
      bar.append(
        icon("warn", 18),
        h("span", { class: "status-text" }, h("strong", null, `Błąd (${where}): `), err.message),
        h("button", { type: "button", class: "btn small", onClick: () => this.editor.focusAt(err.line, err.column) }, "Pokaż w kodzie"),
      );
      if (state.error) {
        const kept = state.segments.length;
        bar.append(h("span", { class: "status-extra" }, kept ? `Narysowano ${kept} odc. przed błędem.` : "Nic nie narysowano."));
      }
      return;
    }
    let text: string;
    switch (state.status) {
      case "running": text = `Wykonywanie… wiersz ${state.line ?? "–"}`; break;
      case "paused": text = state.line ? `Wstrzymano po poleceniu w wierszu ${state.line}. Krok: F10, wznów: F9.` : "Wstrzymano."; break;
      case "finished": text = `Gotowe: ${state.segments.length} odcinków, ${state.ops} operacji.`; break;
      default: text = state.stale ? "Program zmieniony: uruchom go ponownie (Ctrl+Enter)." : "Gotowy. Ctrl+Enter uruchamia program.";
    }
    bar.append(icon(state.status === "finished" ? "check" : "play", 16), h("span", { class: "status-text" }, text));
  }

  private startLoop(): void {
    if (this.raf) return;
    this.lastFrame = performance.now();
    const frame = (now: number) => {
      const dt = Math.min(100, now - this.lastFrame);
      this.lastFrame = now;
      this.controller.tick(dt);
      if (this.controller.state.status === "running") this.raf = requestAnimationFrame(frame);
      else {
        this.raf = 0;
        this.viewport.requestRender();
      }
    };
    this.raf = requestAnimationFrame(frame);
  }

  // ---- plik, udostępnianie, eksport ----

  private currentBackupAvailable(): boolean {
    return !this.challenge && this.ctx.studio.workspace.hasBackup(this.ctx.studio.workspace.mode);
  }

  private restoreBackup(): void {
    const ws = this.ctx.studio.workspace;
    if (ws.restoreBackup(ws.mode)) {
      this.syncFromWorkspace();
      this.controller.runToEnd();
      this.viewport.fit();
      this.ctx.toaster.show("Przywrócono poprzedni szkic. Zamiana jest odwracalna: zrób to jeszcze raz, by wrócić.");
    }
  }

  private downloadProgram(): void {
    const text = this.editor.getValue();
    const mode = this.currentMode();
    download(this.challenge ? `${this.challenge.id}.logo` : `logomocja-${mode}.logo`, new Blob([text], { type: "text/plain;charset=utf-8" }));
    this.ctx.toaster.show("Pobrano plik .logo.");
  }

  private async onFileChosen(): Promise<void> {
    const file = this.fileInput.files?.[0];
    this.fileInput.value = "";
    if (!file) return;
    let text: string;
    try {
      text = await file.text();
    } catch {
      this.ctx.toaster.show("Nie udało się odczytać pliku.");
      return;
    }
    if (this.challenge) {
      saveChallengeDraft(this.ctx.store, this.challenge.id, text.replace(/^﻿/, "").replace(/\r\n?/g, "\n"));
      this.syncFromWorkspace();
      this.controller.runToEnd();
      return;
    }
    const r = this.ctx.studio.workspace.importFile(file.name, text);
    if (!r.ok) {
      this.ctx.toaster.show(r.reason);
      return;
    }
    this.syncFromWorkspace();
    this.controller.runToEnd();
    this.viewport.fit();
    this.ctx.toaster.show(
      r.switched ? `Wczytano ${file.name}. Program używa poleceń 3D, więc przełączono na tryb 3D.` : `Wczytano ${file.name}.`,
      this.ctx.studio.workspace.hasBackup(r.mode) ? { label: "Przywróć poprzedni szkic", run: () => this.restoreBackup() } : undefined,
    );
  }

  private async share(): Promise<void> {
    const mode = this.currentMode();
    const ws = this.ctx.studio.workspace;
    const text = this.editor.getValue();
    // Link koduje dokładnie to, co jest w edytorze (także w wyzwaniu).
    const saved = ws.mode === mode ? ws.source : null;
    if (this.challenge) ws.setMode(mode);
    const prior = ws.source;
    ws.setSource(text);
    const link = ws.shareLink(location.href);
    ws.setSource(prior);
    if (saved !== null) ws.setMode(mode);
    const input = h("input", { type: "text", readonly: true, class: "share-input", value: link, "aria-label": "Link do programu" });
    const feedback = h("p", { class: "muted", role: "status", "aria-live": "polite" });
    const copy = async () => {
      try {
        await navigator.clipboard.writeText(link);
        feedback.textContent = "Skopiowano link do schowka.";
      } catch {
        input.select();
        feedback.textContent = "Zaznaczono link: skopiuj go skrótem Ctrl+C.";
      }
    };
    const body = h(
      "div",
      null,
      h("p", null, "Ten link zawiera Twój program i tryb. Po otwarciu program wczyta się i uruchomi. Wszystko jest zapisane w adresie, bez serwera."),
      h("div", { class: "share-row" }, input, h("button", { type: "button", class: "btn primary", onClick: () => void copy() }, "Kopiuj")),
      feedback,
    );
    void copy();
    await showDialog({ title: "Udostępnij program", body, actions: [{ label: "Zamknij", value: "close", primary: true }] });
  }

  private async exportPng(): Promise<void> {
    const blob = await this.viewport.exportPng();
    if (!blob) {
      this.ctx.toaster.show("Nie udało się wyeksportować obrazu.");
      return;
    }
    download(`logomocja-${this.currentMode()}.png`, blob);
    this.ctx.toaster.show("Zapisano rysunek jako PNG.");
  }

  private async showShortcuts(): Promise<void> {
    await showShortcutsDialog();
  }

  // ---- panel wyzwania ----

  private renderChallengePanel(): void {
    const c = this.challenge;
    this.challengePanel.hidden = !c;
    this.challengePanel.replaceChildren();
    this.el.classList.toggle("has-challenge", !!c);
    if (!c) return;
    const result = h("div", { class: "challenge-result", role: "status", "aria-live": "polite" });
    const thumb = h("canvas", { width: "150", height: "104", "data-w": "150", "data-h": "104", "aria-hidden": "true", class: "thumb" });
    const solved = this.ctx.studio.progress.isSolved(c.id);
    const index = CHALLENGES.findIndex((x) => x.id === c.id);
    const next = CHALLENGES[index + 1];
    const ghost = h("input", {
      type: "checkbox",
      id: "ghost-toggle",
      checked: this.showGhost,
      onChange: () => {
        this.showGhost = ghost.checked;
        if (this.lastState) this.onState(this.lastState);
        this.viewport.fit();
      },
    });
    const check = h(
      "button",
      { type: "button", class: "btn primary", onClick: () => this.checkSolution(result) },
      icon("check"),
      h("span", { class: "btn-label" }, "Sprawdź rozwiązanie"),
    );
    this.challengePanel.append(
      h(
        "div",
        { class: "challenge-head" },
        h("div", null,
          h("p", { class: "eyebrow" }, `Wyzwanie ${index + 1} z ${CHALLENGES.length} · ${c.mode.toUpperCase()} · poziom ${"●".repeat(c.level)}${"○".repeat(3 - c.level)}`),
          h("h2", null, c.title, solved ? h("span", { class: "badge ok" }, "zaliczone") : null),
        ),
        h("a", { class: "btn small", href: formatRoute({ page: "challenges" }) }, "Wszystkie wyzwania"),
      ),
      h("div", { class: "challenge-body" },
        h("div", { class: "challenge-text" },
          h("p", null, c.task),
          h("details", null, h("summary", null, "Podpowiedź"), h("p", null, c.hint)),
          h("label", { class: "check", for: "ghost-toggle" }, ghost, " Pokaż wzór na rysunku (linia przerywana)"),
          h("div", { class: "challenge-actions" }, check, next ? h("a", { class: "btn", href: formatRoute({ page: "challenges", id: next.id }) }, "Następne wyzwanie →") : null),
          result,
        ),
        h("figure", { class: "challenge-figure" }, thumb, h("figcaption", null, "Wzór")),
      ),
    );
    drawThumbnail(thumb, challengeTarget(c), c.mode, this.ctx.theme.effective);
  }

  private checkSolution(result: HTMLElement): void {
    const c = this.challenge;
    if (!c) return;
    const source = this.editor.getValue();
    const outcome = checkChallenge(c, source);
