import { EXAMPLES, type Example } from "../app/examples";
import { run, type Mode } from "../lang";
import { drawThumbnail } from "../view/thumb";
import type { AppContext } from "./context";
import { h } from "./dom";

/** Galeria trzynastu standardowych programów. */
export function renderExamplesPage(ctx: AppContext): HTMLElement {
  const thumbs: Array<{ canvas: HTMLCanvasElement; example: Example; segments: ReturnType<typeof run>["segments"] }> = [];
  const draw = () => {
    for (const t of thumbs) drawThumbnail(t.canvas, t.segments, t.example.mode, ctx.theme.effective);
  };
  const card = (ex: Example) => {
    const segments = run(ex.source, ex.mode).segments;
    const canvas = h("canvas", { width: "220", height: "150", "data-w": "220", "data-h": "150", class: "thumb", "aria-hidden": "true" });
    thumbs.push({ canvas, example: ex, segments });
    return h(
      "article",
      { class: "card example-card", "data-mode": ex.mode, "aria-labelledby": `ex-${ex.id}` },
      h("div", { class: "card-media" }, canvas),
      h("div", { class: "card-body" },
        h("h3", { id: `ex-${ex.id}` }, ex.name, " ", h("span", { class: `badge mode-${ex.mode}` }, ex.mode.toUpperCase())),
        h("p", null, ex.description),
      ),
      h("div", { class: "card-actions" },
        h("button", { type: "button", class: "btn primary", "aria-label": `Uruchom przykład ${ex.name}`, onClick: () => void ctx.loadProgram({ source: ex.source, mode: ex.mode, label: ex.name, run: "animate" }) }, "Uruchom"),
        h("button", { type: "button", class: "btn", "aria-label": `Wczytaj przykład ${ex.name} do edytora`, onClick: () => void ctx.loadProgram({ source: ex.source, mode: ex.mode, label: ex.name, run: "instant" }) }, "Wczytaj do edytora"),
      ),
    );
  };

  const grid = h("div", { class: "card-grid" }, ...EXAMPLES.map(card));
  const filter = (mode: Mode | "all") => {
    for (const c of grid.children) (c as HTMLElement).hidden = mode !== "all" && (c as HTMLElement).dataset.mode !== mode;
  };
  const radio = (value: Mode | "all", label: string, checked = false) => {
    const id = `ex-filter-${value}`;
    return [h("input", { type: "radio", name: "ex-filter", id, checked, onChange: () => filter(value) }), h("label", { for: id }, label)];
  };

  const page = h(
    "section",
    { class: "page" },
    h("header", { class: "page-head" },
      h("h1", { tabindex: "-1" }, "Przykłady"),
      h("p", null, "Trzynaście gotowych programów: od kwadratu po rekurencyjne drzewo w przestrzeni. Wczytaj któryś do edytora, zmień liczby i zobacz, co się stanie. Twój własny szkic nie zginie: przed zastąpieniem zapytamy o zgodę, a poprzednią wersję da się przywrócić."),
    ),
    h("fieldset", { class: "mode-switch filter" }, h("legend", { class: "sr-only" }, "Pokaż przykłady"), ...radio("all", "Wszystkie", true), ...radio("2d", "2D"), ...radio("3d", "3D")),
    grid,
  );
  draw();
  ctx.theme.onChange(draw);
  return page;
}
