cat > docs-page.ts <<'EOF'
import { DOC_COMMANDS, DOC_SECTIONS, type DocBlock, type DocCommand, type DocExample } from "../app/docs-content";
import { formatRoute } from "../app/router";
import { run } from "../lang";
import { highlight } from "../lang/highlight";
import { drawThumbnail } from "../view/thumb";
import type { AppContext } from "./context";
import { h } from "./dom";
import { highlightHtml } from "./editor";

/** Strona dokumentacji języka: sekcje, polecenia z przykładami i przycisk „Wypróbuj”. */
export function renderDocsPage(ctx: AppContext, focusSection?: string): HTMLElement {
  const thumbs: Array<{ canvas: HTMLCanvasElement; example: DocExample; segments: ReturnType<typeof run>["segments"] }> = [];
  const redraw = () => {
    for (const t of thumbs) drawThumbnail(t.canvas, t.segments, t.example.mode, ctx.theme.effective);
  };

  const codeBlock = (code: string): HTMLElement => {
    const pre = h("pre", { class: "code", tabindex: "0" });
    const codeEl = h("code");
    codeEl.innerHTML = highlightHtml(code, highlight(code), null);
    pre.appendChild(codeEl);
    return pre;
  };

  const exampleView = (ex: DocExample): HTMLElement => {
    const result = run(ex.code, ex.mode);
    const canvas = h("canvas", { width: "140", height: "96", "data-w": "140", "data-h": "96", class: "thumb", "aria-hidden": "true" });
    if (!ex.error) thumbs.push({ canvas, example: ex, segments: result.segments });
    return h(
      "figure",
      { class: "doc-example" },
      h("figcaption", null, ex.title, " ", h("span", { class: `badge mode-${ex.mode}` }, ex.mode.toUpperCase())),
      h("div", { class: "doc-example-body" },
        codeBlock(ex.code),
        ex.error
          ? h("p", { class: "doc-error", role: "note" }, h("strong", null, "Wynik: błąd"), result.error ? ` (wiersz ${result.error.line}, kolumna ${result.error.column}): ${result.error.message}` : "")
          : canvas,
      ),
      h("button", { type: "button", class: "btn small", "aria-label": `Wypróbuj w pracowni: ${ex.title}`, onClick: () => void ctx.loadProgram({ source: ex.code, mode: ex.mode, label: ex.title, run: "animate" }) }, "Wypróbuj w pracowni"),
    );
  };

  const commandView = (c: DocCommand): HTMLElement =>
    h(
      "article",
      { class: "doc-command", id: `cmd-${c.id}`, "aria-labelledby": `cmd-title-${c.id}` },
      h("h3", { id: `cmd-title-${c.id}` },
        ...c.polish.flatMap((w, i) => [i ? " · " : "", h("code", null, w)]),
        c.spatial ? h("span", { class: "badge mode-3d" }, "3D") : null,
      ),
      h("p", { class: "aliases" }, "Angielski odpowiednik: ", ...c.english.flatMap((w, i) => [i ? ", " : "", h("code", null, w)])),
      h("p", { class: "syntax" }, "Składnia: ", h("code", null, c.syntax)),
      h("p", null, c.summary),
      c.details ? h("p", { class: "muted" }, c.details) : null,
      exampleView({ title: `Przykład: ${c.polish[0]}`, code: c.example, mode: c.mode }),
    );

  const blockView = (b: DocBlock): HTMLElement | HTMLElement[] => {
    switch (b.type) {
      case "p": return h("p", null, b.text);
      case "note": return h("p", { class: "note" }, h("strong", null, "Uwaga: "), b.text);
      case "list": return h("ul", null, ...b.items.map((t) => h("li", null, t)));
      case "table":
        return h("div", { class: "table-wrap" }, h("table", null,
          h("thead", null, h("tr", null, ...b.head.map((c) => h("th", { scope: "col" }, c)))),
          h("tbody", null, ...b.rows.map((r) => h("tr", null, ...r.map((cell, i) => (i === 0 ? h("th", { scope: "row" }, cell) : h("td", null, cell)))))),
        ));
      case "code": return exampleView(b.example);
      case "commands": return b.ids.map((id) => commandView(DOC_COMMANDS.find((c) => c.id === id)!));
    }
  };

  const sections = DOC_SECTIONS.map((s) =>
    h("section", { class: "doc-section", id: `doc-${s.id}`, "data-section": s.id, "aria-labelledby": `doc-title-${s.id}` },
      h("h2", { id: `doc-title-${s.id}` }, s.title),
      ...s.blocks.flatMap((b) => blockView(b)),
    ),
  );

  const toc = h(
    "nav",
    { class: "doc-toc", "aria-label": "Spis treści dokumentacji" },
    h("h2", null, "Spis treści"),
    h("ol", null, ...DOC_SECTIONS.map((s) => h("li", null, h("a", { href: formatRoute({ page: "docs", id: s.id }), "data-doc": s.id }, s.title)))),
  );

  const page = h(
    "section",
    { class: "page docs" },
    h("header", { class: "page-head" },
      h("h1", { tabindex: "-1" }, "Dokumentacja języka"),
      h("p", null, "Wszystko, co potrafi Logo w Logomocji: polecenia, wyrażenia, zmienne, warunki, procedury, tryb 3D, błędy i limity. Każde polecenie ma przykład, który możesz od razu wypróbować."),
    ),
    h("div", { class: "docs-layout" }, toc, h("div", { class: "docs-content" }, ...sections)),
  );
  redraw();
  ctx.theme.onChange(redraw);
  if (focusSection) {
    queueMicrotask(() => page.querySelector(`[data-section="${focusSection}"]`)?.scrollIntoView({ block: "start" }));
  }
  return page;
}
