import { CHALLENGES, challengeTarget } from "../app/challenges";
import { formatRoute } from "../app/router";
import { drawThumbnail } from "../view/thumb";
import type { AppContext } from "./context";
import { showDialog } from "./dialog";
import { h } from "./dom";

/** Lista wyzwań z postępem zapisanym lokalnie. */
export function renderChallengesPage(ctx: AppContext): HTMLElement {
  const progress = ctx.studio.progress;
  const total = CHALLENGES.length;
  const thumbs: Array<{ canvas: HTMLCanvasElement; index: number }> = [];
  const draw = () => {
    for (const t of thumbs) {
      const c = CHALLENGES[t.index];
      drawThumbnail(t.canvas, challengeTarget(c), c.mode, ctx.theme.effective);
    }
  };

  const summary = h("div", { class: "progress-summary" });
  const renderSummary = () => {
    const solved = progress.solvedCount();
    summary.replaceChildren(
      h("label", { for: "progress-bar" }, `Zaliczone: ${solved} z ${total}`),
      h("progress", { id: "progress-bar", max: String(total), value: String(solved) }, `${solved} z ${total}`),
    );
  };
  renderSummary();

  const cards = CHALLENGES.map((c, index) => {
    const solved = progress.isSolved(c.id);
    const canvas = h("canvas", { width: "200", height: "136", "data-w": "200", "data-h": "136", class: "thumb", "aria-hidden": "true" });
    thumbs.push({ canvas, index });
    return h(
      "article",
      { class: `card challenge-card${solved ? " solved" : ""}`, "aria-labelledby": `ch-${c.id}` },
      h("div", { class: "card-media" }, canvas),
      h("div", { class: "card-body" },
        h("p", { class: "eyebrow" }, `${c.mode.toUpperCase()} · poziom ${"●".repeat(c.level)}${"○".repeat(3 - c.level)}`),
        h("h3", { id: `ch-${c.id}` }, c.title, solved ? h("span", { class: "badge ok" }, "zaliczone") : null),
        h("p", null, c.task),
        progress.attempts(c.id) ? h("p", { class: "muted" }, `Próby: ${progress.attempts(c.id)}`) : null,
      ),
      h("div", { class: "card-actions" },
        h("a", { class: "btn primary", href: formatRoute({ page: "challenges", id: c.id }), "aria-label": `${solved ? "Rozwiąż ponownie" : "Rozwiąż"}: ${c.title}` }, solved ? "Rozwiąż ponownie" : "Rozwiąż"),
      ),
    );
  });

  const resetBtn = h("button", {
    type: "button",
    class: "btn small",
    onClick: async () => {
      const choice = await showDialog({
        title: "Wyczyścić postępy?",
        body: "Znikną informacje o zaliczonych wyzwaniach i liczbie prób. Twoje programy-rozwiązania zostaną.",
        actions: [{ label: "Anuluj", value: "no" }, { label: "Wyczyść postępy", value: "yes", primary: true }],
      });
      if (choice === "yes") {
        progress.reset();
        ctx.navigate({ page: "challenges" });
        ctx.toaster.show("Postępy wyczyszczone.");
      }
    },
  }, "Wyczyść postępy");

  const page = h(
    "section",
    { class: "page" },
    h("header", { class: "page-head" },
      h("h1", { tabindex: "-1" }, "Wyzwania"),
      h("p", null, "Każde wyzwanie opisuje rysunek, który masz uzyskać. Piszesz program, a Logomocja porównuje to, co narysował żółw, ze wzorem: nie ma znaczenia kolejność poleceń ani sposób, tylko gotowy rysunek (w granicach niewielkiej tolerancji). Postępy zapisują się w tej przeglądarce."),
    ),
    h("div", { class: "progress-row" }, summary, resetBtn),
