import { challengeById, CHALLENGES } from "../app/challenges";
import type { ControllerState } from "../app/controller";
import { formatRoute, parseRoute, type Route } from "../app/router";
import type { KeyValueStore } from "../app/storage";
import type { Studio } from "../app/studio";
import type { Mode } from "../lang";
import type { AppContext } from "./context";
import { renderChallengesPage } from "./challenges-page";
import { showDialog } from "./dialog";
import { download, h, icon } from "./dom";
import { renderDocsPage } from "./docs-page";
import { renderExamplesPage } from "./examples-page";
import { THEME_LABELS, ThemeManager } from "./theme";
import { createToaster } from "./toast";
import { showShortcutsDialog, WorkspacePage } from "./workspace-page";

const NAV: Array<{ page: Route["page"]; label: string }> = [
  { page: "workspace", label: "Pracownia" },
  { page: "examples", label: "Przykłady" },
  { page: "challenges", label: "Wyzwania" },
  { page: "docs", label: "Dokumentacja" },
];

const TITLES: Record<Route["page"], string> = {
  workspace: "Pracownia",
  examples: "Przykłady",
  challenges: "Wyzwania",
  docs: "Dokumentacja",
};

const TURTLE_LOGO =
  '<svg viewBox="0 0 64 64" width="30" height="30" aria-hidden="true" focusable="false"><rect width="64" height="64" rx="14" fill="currentColor"/><g fill="var(--logo-fg, #fff)"><ellipse cx="32" cy="35" rx="16" ry="13"/><circle cx="32" cy="16" r="6"/><circle cx="17" cy="47" r="4.5"/><circle cx="47" cy="47" r="4.5"/><circle cx="14" cy="28" r="4"/><circle cx="50" cy="28" r="4"/></g><path d="M32 24v22M22 30l10 6 10-6" stroke="currentColor" stroke-width="2.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';

export class App {
  readonly ctx: AppContext;
  private readonly workspaceHost = h("div", { class: "workspace-host" });
  private readonly pageHost = h("div", { class: "page-host", hidden: true });
  private readonly main = h("main", { id: "main", tabindex: "-1" }, this.workspaceHost, this.pageHost);
  private readonly navLinks = new Map<Route["page"], HTMLAnchorElement>();
  private readonly themeBtn: HTMLButtonElement;
  private workspacePage!: WorkspacePage;
  private route: Route = { page: "workspace" };
  private firstRender = true;

  constructor(
    private readonly root: HTMLElement,
    private readonly studio: Studio,
    store: KeyValueStore,
  ) {
    const theme = new ThemeManager(store);
    const toastRegion = h("div", { class: "toasts", role: "region", "aria-label": "Komunikaty" });
    const toaster = createToaster(toastRegion);
    this.ctx = {
      studio,
      store,
      theme,
      toaster,
      navigate: (route) => this.navigate(route),
      loadProgram: (options) => this.loadProgram(options),
    };

    this.themeBtn = h("button", { type: "button", class: "btn ghost", onClick: () => this.cycleTheme() });
    const header = h(
      "header",
      { class: "topbar" },
      h("a", { class: "brand", href: formatRoute({ page: "workspace" }), "aria-label": "Logomocja: pracownia" },
        h("span", { class: "brand-mark", innerHTML: TURTLE_LOGO }),
        h("span", { class: "brand-name" }, "Logomocja"),
      ),
      h("nav", { class: "nav", "aria-label": "Główna nawigacja" },
        ...NAV.map((n) => {
          const a = h("a", { href: formatRoute({ page: n.page } as Route), class: "nav-link" }, n.label);
          this.navLinks.set(n.page, a);
          return a;
        }),
      ),
      h("div", { class: "topbar-actions" },
        h("button", { type: "button", class: "btn ghost", title: "Skróty klawiaturowe", "aria-label": "Skróty klawiaturowe", onClick: () => void showShortcutsDialog() }, icon("help"), h("span", { class: "btn-label" }, "Skróty")),
        this.themeBtn,
      ),
    );
    this.updateThemeButton();
    theme.onChange(() => this.updateThemeButton());

    root.replaceChildren(
      h("a", { class: "skip-link", href: "#main", onClick: (e: Event) => { e.preventDefault(); this.main.focus(); } }, "Przejdź do treści"),
      header,
      this.main,
      toastRegion,
    );

    this.workspacePage = new WorkspacePage(this.ctx);
    this.workspaceHost.appendChild(this.workspacePage.el);

    window.addEventListener("hashchange", () => this.onHashChange());
    window.addEventListener("popstate", () => this.onHashChange());
    this.onHashChange(true);
  }

  // ---- trasy ----

  navigate(route: Route): void {
    const hash = formatRoute(route);
    if (location.hash !== hash) history.pushState(null, "", hash);
    this.renderRoute(route);
  }

  private onHashChange(initial = false): void {
    const hash = location.hash;
    if (hash.startsWith("#/pracownia?") && this.openSharedLink(hash)) return;
    this.renderRoute(parseRoute(hash));
    void initial;
  }

  /** Link udostępniony: wczytuje program, uruchamia go i czyści adres, by odświeżenie nie nadpisało szkicu. */
  private openSharedLink(hash: string): boolean {
    const ws = this.studio.workspace;
    if (!ws.openShared(hash)) {
      history.replaceState(null, "", formatRoute({ page: "workspace" }));
      this.ctx.toaster.show("Ten link do programu jest uszkodzony, więc go nie otwieram.");
      this.renderRoute({ page: "workspace" });
      return true;
    }
    const mode = ws.mode;
    history.replaceState(null, "", formatRoute({ page: "workspace" }));
    this.renderRoute({ page: "workspace" });
    this.workspacePage.syncFromWorkspace();
    this.workspacePage.runInstantly();
    this.ctx.toaster.show(
      `Otwarto udostępniony program (tryb ${mode.toUpperCase()}).`,
      ws.hasBackup(mode) ? { label: "Przywróć mój szkic", run: () => { ws.restoreBackup(mode); this.workspacePage.syncFromWorkspace(); this.workspacePage.runInstantly(); } } : undefined,
    );
    return true;
  }

  private renderRoute(route: Route): void {
    this.route = route;
    for (const [page, a] of this.navLinks) {
      const active = page === route.page || (page === "workspace" && route.page === "workspace");
      if (active) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    }
    let challengeTitle = "";
    if (route.page === "workspace" || (route.page === "challenges" && route.id)) {
      const challenge = route.page === "challenges" && route.id ? challengeById(route.id) : undefined;
      if (route.page === "challenges" && route.id && !challenge) {
        // Nieznane wyzwanie: wracamy do listy.
        this.navigate({ page: "challenges" });
        return;
      }
      this.workspacePage.setChallenge(challenge ?? null);
      challengeTitle = challenge ? `: ${challenge.title}` : "";
      this.workspaceHost.hidden = false;
      this.pageHost.hidden = true;
      this.pageHost.replaceChildren();
      this.navLinks.get(route.page === "challenges" ? "challenges" : "workspace")?.setAttribute("aria-current", "page");
      if (route.page === "challenges") this.navLinks.get("workspace")?.removeAttribute("aria-current");
    } else {
      this.workspaceHost.hidden = true;
      this.pageHost.hidden = false;
      this.pageHost.replaceChildren(this.buildPage(route));
    }
    document.title = `${TITLES[route.page]}${challengeTitle} – Logomocja`;
    if (!this.firstRender) {
      if (route.page === "docs" && route.id) return;
      const heading = this.pageHost.querySelector<HTMLElement>("h1");
      (heading ?? this.main).focus({ preventScroll: true });
      window.scrollTo({ top: 0 });
    }
    this.firstRender = false;
  }

  private buildPage(route: Route): HTMLElement {
    switch (route.page) {
      case "examples": return renderExamplesPage(this.ctx);
      case "challenges": return renderChallengesPage(this.ctx);
      case "docs": return renderDocsPage(this.ctx, route.id);
      default: return h("div");
    }
  }

  // ---- motyw ----

  private cycleTheme(): void {
    const next = this.ctx.theme.cycle();
    this.ctx.toaster.show(`Motyw: ${THEME_LABELS[next]}.`);
  }

  private updateThemeButton(): void {
    const pref = this.ctx.theme.preference;
    const iconName = pref === "dark" ? "moon" : pref === "light" ? "sun" : "contrast";
    this.themeBtn.replaceChildren(icon(iconName), h("span", { class: "btn-label" }, "Motyw"));
    this.themeBtn.title = `Motyw: ${THEME_LABELS[pref]}. Kliknij, aby zmienić.`;
    this.themeBtn.setAttribute("aria-label", `Motyw: ${THEME_LABELS[pref]}. Kliknij, aby zmienić na kolejny.`);
  }

  // ---- wczytywanie programów ----

  private async loadProgram(options: { source: string; mode: Mode; label: string; run: "instant" | "animate" | "none" }): Promise<boolean> {
    const ws = this.studio.workspace;
    const outcome = ws.loadProgram(options.source, options.mode);
    if (outcome.status === "needs-confirmation") {
      const choice = await showDialog({
        title: "Zastąpić Twój szkic?",
        body: h("div", null,
          h("p", null, `W edytorze (tryb ${options.mode.toUpperCase()}) jest Twój szkic, który nie jest wbudowanym przykładem. Wczytanie „${options.label}” go zastąpi.`),
          h("p", { class: "muted" }, "Zachowamy kopię zapasową, którą przywrócisz z menu Plik → Przywróć poprzedni szkic."),
        ),
        actions: [
          { label: "Anuluj", value: "cancel" },
          { label: "Pobierz szkic i wczytaj", value: "download" },
          { label: "Wczytaj i zachowaj kopię", value: "replace", primary: true },
        ],
      });
      if (choice !== "replace" && choice !== "download") return false;
      if (choice === "download") {
        const file = ws.exportFileFor(options.mode);
        download(file.filename, new Blob([file.content], { type: file.mime }));
      }
      outcome.confirm();
    }
    this.navigate({ page: "workspace" });
    this.workspacePage.syncFromWorkspace();
    if (options.run === "instant") this.workspacePage.runInstantly();
    else if (options.run === "animate") this.workspacePage.runAnimated();
    this.ctx.toaster.show(
      `Wczytano „${options.label}”.`,
      ws.hasBackup(options.mode)
        ? { label: "Przywróć poprzedni szkic", run: () => { ws.restoreBackup(options.mode); this.workspacePage.syncFromWorkspace(); this.workspacePage.runInstantly(); } }
        : undefined,
    );
    return true;
  }

  // ---- dla window.logomocja.open ----

  /** Pokazuje pracownię z programem, który właśnie wczytał studio.open, i czeka na narysowanie. */
  async presentWorkspace(_state: ControllerState): Promise<void> {
    this.navigate({ page: "workspace" });
    this.workspacePage.adoptWorkspaceState();
    await this.workspacePage.present();
  }
}

export { CHALLENGES };
EOF
