  --fg: #1d2b2a;
  --muted: #566763;
  --border: #d6cdb8;
  --accent: #12795f;
  --accent-fg: #ffffff;
  --accent-text: #0d6b53;
  --accent-soft: #dcefe7;
  --amber: #c1763d;
  --danger: #b3261e;
  --danger-soft: #fbe3df;
  --danger-fg: #7d1912;
  --ok: #0d6b53;
  --ok-soft: #d6efe4;
  --focus: #0b57d0;
  --editor-bg: #fffdf8;
  --gutter-bg: #f1ebdd;
  --exec-band: rgb(18 121 95 / 0.16);
  --selection: rgb(11 87 208 / 0.25);
  --tok-command: #0a58a6;
  --tok-number: #9a4a00;
  --tok-name: #1d2b2a;
  --tok-procedure: #7a3ea1;
  --tok-string: #0b7a4e;
  --tok-comment: #62736f;
  --tok-bracket: #8a5a00;
  --tok-operator: #8f3a3a;
  --canvas-frame: #e9e2d0;
  --shadow: 0 6px 24px rgb(40 30 10 / 0.16);
  --font-ui: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, "SF Mono", "Cascadia Code", "Fira Code", Menlo, Consolas, "Liberation Mono", monospace;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #0b1415;
  --dot: #14262a;
  --surface: #12201f;
  --surface-2: #1a2d2d;
  --fg: #e6efe9;
  --muted: #9db3ad;
  --border: #2b4246;
  --accent: #3fbf9c;
  --accent-fg: #06231b;
  --accent-text: #6fd7b9;
  --accent-soft: #15332d;
  --amber: #e29a5f;
  --danger: #ff8a80;
  --danger-soft: #3a1c1a;
  --danger-fg: #ffb4ab;
  --ok: #6fd7b9;
  --ok-soft: #12362e;
  --focus: #8ab4ff;
  --editor-bg: #0e1a1b;
  --gutter-bg: #0b1415;
  --exec-band: rgb(63 191 156 / 0.2);
  --selection: rgb(138 180 255 / 0.3);
  --tok-command: #7fb6ff;
  --tok-number: #f0a860;
  --tok-name: #e6efe9;
  --tok-procedure: #c9a0ec;
  --tok-string: #7fd8a8;
  --tok-comment: #8a9d98;
  --tok-bracket: #e0c068;
  --tok-operator: #e69a9a;
  --canvas-frame: #0b1415;
  --shadow: 0 6px 24px rgb(0 0 0 / 0.5);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #0b1415;
    --dot: #14262a;
    --surface: #12201f;
    --surface-2: #1a2d2d;
    --fg: #e6efe9;
    --muted: #9db3ad;
    --border: #2b4246;
    --accent: #3fbf9c;
    --accent-fg: #06231b;
    --accent-text: #6fd7b9;
    --accent-soft: #15332d;
    --amber: #e29a5f;
    --danger: #ff8a80;
    --danger-soft: #3a1c1a;
    --danger-fg: #ffb4ab;
    --ok: #6fd7b9;
    --ok-soft: #12362e;
    --focus: #8ab4ff;
    --editor-bg: #0e1a1b;
    --gutter-bg: #0b1415;
    --exec-band: rgb(63 191 156 / 0.2);
    --selection: rgb(138 180 255 / 0.3);
    --tok-command: #7fb6ff;
    --tok-number: #f0a860;
    --tok-name: #e6efe9;
    --tok-procedure: #c9a0ec;
    --tok-string: #7fd8a8;
    --tok-comment: #8a9d98;
    --tok-bracket: #e0c068;
    --tok-operator: #e69a9a;
    --canvas-frame: #0b1415;
    --shadow: 0 6px 24px rgb(0 0 0 / 0.5);
  }
}

/* ===== Podstawy ===== */
*,
*::before,
*::after {
  box-sizing: border-box;
}
[hidden] {
  display: none !important;
}
html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.5 var(--font-ui);
}
#app {
  height: 100dvh;
  display: flex;
  flex-direction: column;
}
h1, h2, h3, h4 {
  line-height: 1.2;
  margin: 0 0 0.5rem;
}
a {
  color: var(--accent-text);
}
code {
  font-family: var(--font-mono);
  font-size: 0.92em;
  background: var(--surface-2);
  padding: 0.05rem 0.35rem;
  border-radius: 6px;
}
kbd {
  font: 0.85em var(--font-mono);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-radius: 6px;
  padding: 0.05rem 0.4rem;
  white-space: nowrap;
}
.muted {
  color: var(--muted);
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
::selection {
  background: var(--selection);
}
.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -4rem;
  z-index: 100;
  background: var(--accent);
  color: var(--accent-fg);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  text-decoration: none;
  font-weight: 700;
}
.skip-link:focus {
  top: 0.5rem;
}
.icon {
  display: inline-flex;
  flex: none;
}
.icon svg {
  display: block;
}

/* ===== Przyciski ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 40px;
  padding: 0.4rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--fg);
  font: inherit;
  font-weight: 650;
  line-height: 1.2;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}
.btn:hover:not(:disabled) {
  background: var(--accent-soft);
  border-color: var(--accent);
}
.btn:active:not(:disabled) {
  transform: translateY(1px);
}
.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.btn.primary {
  background: var(--accent);
  border-color: transparent;
  color: var(--accent-fg);
}
.btn.primary:hover:not(:disabled) {
  background: var(--accent);
  filter: brightness(1.1);
}
.btn.ghost {
  background: transparent;
}
.btn.small {
  min-height: 34px;
  padding: 0.2rem 0.65rem;
  font-size: 0.9rem;
}

/* ===== Pasek górny ===== */
.topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  padding: 0.45rem 0.9rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  color: var(--accent);
  text-decoration: none;
  --logo-fg: var(--surface);
}
.brand-mark {
  display: inline-flex;
}
.brand-name {
  font-size: 1.3rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--fg);
}
.nav {
  display: flex;
  gap: 0.25rem;
  flex: 1;
  flex-wrap: wrap;
}
.nav-link {
  padding: 0.4rem 0.8rem;
  border-radius: 10px;
  color: var(--fg);
  text-decoration: none;
  font-weight: 650;
}
.nav-link:hover {
  background: var(--surface-2);
}
.nav-link[aria-current="page"] {
  background: var(--accent-soft);
  color: var(--accent-text);
  box-shadow: inset 0 -3px 0 var(--accent);
}
.topbar-actions {
  display: flex;
  gap: 0.25rem;
  margin-left: auto;
}

main {
  flex: 1;
  min-height: 0;
  overflow: auto;
}
main:focus {
  outline: none;
}
.workspace-host {
  height: 100%;
}
.page-host {
  min-height: 100%;
  background-image: radial-gradient(var(--dot) 1px, transparent 1px);
  background-size: 22px 22px;
}

/* ===== Pracownia ===== */
.studio {
  height: 100%;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.6rem;
  padding: 0.5rem 0.75rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.toolbar .menu {
  margin-left: auto;
}
.speed {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
}
.speed input[type="range"] {
  width: 110px;
  accent-color: var(--accent);
  min-height: 32px;
}
.speed-out {
  min-width: 9.5ch;
  color: var(--muted);
  font-size: 0.82rem;
}
.mode-switch {
  position: relative;
  display: inline-flex;
  margin: 0;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--surface);
}
.mode-switch input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}
.mode-switch label {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 0.3rem 0.95rem;
  font-weight: 800;
  cursor: pointer;
}
.mode-switch input:checked + label {
  background: var(--accent);
  color: var(--accent-fg);
}
.mode-switch input:focus-visible + label {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.mode-switch.filter {
  margin-bottom: 1rem;
}

.pane-switch {
  display: none;
  gap: 0.4rem;
  padding: 0.4rem 0.75rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.pane-switch .btn {
  flex: 1;
}
.pane-switch .btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-fg);
  border-color: transparent;
}
.panes {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(320px, 42%) 1fr;
}
.pane {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.pane-code {
  border-right: 1px solid var(--border);
}
.pane-view {
  background: var(--canvas-frame);
}

/* ===== Edytor ===== */
.editor {
  position: relative;
  display: flex;
  flex: 1;
  min-height: 0;
  background: var(--editor-bg);
  font: 14px/22px var(--font-mono);
  font-variant-ligatures: none;
}
.editor:focus-within {
  box-shadow: inset 0 0 0 3px var(--focus);
}
.editor-gutter {
  flex: none;
  width: 3.4em;
  overflow: hidden;
  background: var(--gutter-bg);
  border-right: 1px solid var(--border);
  color: var(--muted);
  text-align: right;
  user-select: none;
}
.editor-gutter-inner {
  padding: 10px 0.6em 10px 0;
  will-change: transform;
}
.ln {
  display: block;
  height: 22px;
  line-height: 22px;
}
.ln-exec {
  color: var(--accent-text);
  font-weight: 800;
  background: var(--exec-band);
}
.ln-error {
  color: var(--danger);
  font-weight: 800;
}
.ln-error::before {
  content: "●";
  margin-right: 0.35em;
  font-size: 0.7em;
  vertical-align: 0.1em;
}
.editor-scroll {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.editor-layer,
.editor-input {
  position: absolute;
  top: 0;
  left: 0;
  margin: 0;
  font: inherit;
  font-variant-ligatures: none;
  letter-spacing: 0;
  tab-size: 2;
  white-space: pre;
  word-break: normal;
  overflow-wrap: normal;
}
.editor-layer {
  min-width: 100%;
  min-height: 100%;
  width: max-content;
  pointer-events: none;
  will-change: transform;
}
.editor-highlight {
  margin: 0;
  padding: 10px 12px;
  font: inherit;
  font-variant-ligatures: none;
  tab-size: 2;
  color: var(--tok-name);
}
.editor-input {
  width: 100%;
  height: 100%;
  padding: 10px 12px;
  border: 0;
  outline: 0;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: var(--fg);
}
.editor-input::selection {
  background: var(--selection);
  -webkit-text-fill-color: transparent;
}
.editor-band {
  position: absolute;
  left: 0;
  right: 0;
  height: 22px;
}
.exec-band {
  background: var(--exec-band);
  box-shadow: inset 3px 0 0 var(--accent);
}
.error-band {
  background: var(--danger-soft);
  box-shadow: inset 3px 0 0 var(--danger);
}
.tok-command { color: var(--tok-command); font-weight: 650; }
.tok-number { color: var(--tok-number); }
.tok-name { color: var(--tok-name); }
.tok-procedure { color: var(--tok-procedure); font-weight: 650; }
.tok-string { color: var(--tok-string); }
.tok-comment { color: var(--tok-comment); font-style: italic; }
.tok-bracket { color: var(--tok-bracket); font-weight: 700; }
.tok-operator { color: var(--tok-operator); }
.tok-invalid { color: var(--danger); }
.tok-error {
  text-decoration: underline wavy var(--danger);
  text-decoration-thickness: 2px;
  text-underline-offset: 4px;
  background: var(--danger-soft);
}

.statusbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.35rem 0.6rem;
  min-height: 2.9rem;
  padding: 0.45rem 0.8rem;
  background: var(--surface-2);
  border-top: 1px solid var(--border);
  font-size: 0.92rem;
}
.statusbar.is-error {
  background: var(--danger-soft);
  color: var(--danger-fg);
}
.status-text {
  flex: 1 1 14rem;
  min-width: 0;
}
.status-extra {
  flex-basis: 100%;
  font-size: 0.85rem;
  opacity: 0.85;
}

/* ===== Widok rysunku ===== */
.viewport {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  touch-action: none;
}
.viewport-canvas {
  position: absolute;
  inset: 0;
  display: block;
  cursor: grab;
  touch-action: none;
}
.viewport.dragging .viewport-canvas {
  cursor: grabbing;
}
.viewport-canvas:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.viewport-controls {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  max-width: calc(100% - 1rem);
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.3rem;
}
.viewport-controls .btn {
  background: var(--surface);
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.15);
}

/* ===== Panel wyzwania ===== */
.challenge-panel {
  max-height: 46%;
  overflow: auto;
  padding: 0.75rem 1rem;
  background: var(--accent-soft);
  border-bottom: 1px solid var(--border);
}
.challenge-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  flex-wrap: wrap;
}
.challenge-head h2 {
  margin: 0;
  font-size: 1.25rem;
}
.eyebrow {
  margin: 0 0 0.15rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent-text);
}
.challenge-body {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  align-items: flex-start;
}
.challenge-text {
  flex: 1 1 320px;
  min-width: 0;
}
.challenge-text p {
  margin: 0.4rem 0;
}
.challenge-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin: 0.5rem 0;
}
.challenge-figure {
  margin: 0;
  text-align: center;
  font-size: 0.8rem;
  color: var(--muted);
}
.challenge-figure .thumb {
  border: 1px solid var(--border);
  border-radius: 8px;
}
.check {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
}
.check input {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: var(--accent);
}
.challenge-result {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
  margin-top: 0.4rem;
  font-weight: 650;
}
.challenge-result.pass {
  color: var(--ok);
}
.challenge-result.fail {
  color: var(--danger-fg);
}
.badge {
  display: inline-block;
  margin-left: 0.4rem;
  padding: 0.05rem 0.5rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--fg);
  font-size: 0.72rem;
  font-weight: 750;
  vertical-align: middle;
  letter-spacing: 0.02em;
}
.badge.ok {
  background: var(--ok-soft);
  color: var(--ok);
  border-color: var(--ok);
}
.badge.mode-3d {
  background: #e8def5;
  color: #4b2a73;
}
:root[data-theme="dark"] .badge.mode-3d {
  background: #2b1f3d;
  color: #d6b9f5;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .badge.mode-3d {
    background: #2b1f3d;
    color: #d6b9f5;
  }
}

/* ===== Strony ===== */
.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 1.25rem 1rem 3.5rem;
}
.page-head h1 {
  font-size: clamp(1.7rem, 3.5vw, 2.4rem);
  letter-spacing: -0.02em;
}
.page-head h1:focus {
  outline: none;
}
.page-head p {
  max-width: 70ch;
  color: var(--muted);
}
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
}
.card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
}
.card.solved {
  border-color: var(--ok);
}
.card-media {
  display: flex;
  justify-content: center;
  background: var(--editor-bg);
  border-bottom: 1px solid var(--border);
}
.card-body {
  flex: 1;
  padding: 0.75rem 1rem 0.5rem;
}
.card-body h3 {
  margin: 0 0 0.25rem;
  font-size: 1.1rem;
}
.card-body p {
  margin: 0.25rem 0;
  font-size: 0.93rem;
}
.card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.5rem 1rem 1rem;
}
.progress-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.5rem 0 1rem;
}
.progress-summary {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  font-weight: 650;
}
progress {
  width: 200px;
  height: 14px;
  accent-color: var(--accent);
}

/* ===== Dokumentacja ===== */
.docs-layout {
  display: grid;
  grid-template-columns: 230px minmax(0, 1fr);
  gap: 2rem;
  margin-top: 1rem;
}
.doc-toc {
  position: sticky;
  top: 0.75rem;
  align-self: start;
  max-height: calc(100dvh - 8rem);
  overflow: auto;
  padding: 0.75rem 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
}
.doc-toc h2 {
  font-size: 1rem;
}
.doc-toc ol {
  margin: 0;
  padding-left: 1.2rem;
}
.doc-toc li {
  margin: 0.25rem 0;
}
.doc-section {
  margin-bottom: 2.5rem;
  scroll-margin-top: 0.75rem;
}
.doc-section > h2 {
  padding-bottom: 0.3rem;
  border-bottom: 2px solid var(--accent);
  font-size: 1.5rem;
}
.doc-command {
  margin: 1.25rem 0;
  padding: 0.9rem 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 5px solid var(--accent);
  border-radius: 12px;
}
.doc-command h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2rem;
  font-size: 1.15rem;
}
.doc-command p {
  margin: 0.3rem 0;
}
.doc-example {
  margin: 0.9rem 0;
  padding: 0.7rem 0.8rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
}
.doc-command .doc-example {
  background: var(--editor-bg);
}
.doc-example figcaption {
  margin-bottom: 0.4rem;
  font-weight: 700;
  font-size: 0.92rem;
}
.doc-example-body {
  display: flex;
  flex-wrap: wrap;
