}

/* ===== Menu, okna, komunikaty ===== */
.menu {
  position: relative;
}
.menu-list {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  z-index: 30;
  display: flex;
  flex-direction: column;
  min-width: 270px;
  max-width: calc(100vw - 1rem);
  padding: 0.35rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--shadow);
}
.menu-item {
  display: flex;
