  align-items: flex-start;
  padding: 0.55rem 0.7rem;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--fg);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.menu-item:hover:not(:disabled),
.menu-item:focus-visible {
  background: var(--accent-soft);
}
.menu-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.menu-item small {
  color: var(--muted);
}
.dialog {
  max-width: min(560px, 92vw);
  padding: 0;
  background: var(--surface);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: var(--shadow);
}
.dialog.wide {
  max-width: min(760px, 94vw);
}
.dialog::backdrop {
  background: rgb(0 0 0 / 0.5);
}
.dialog-title {
  margin: 0;
  padding: 1rem 1.25rem 0.25rem;
  font-size: 1.2rem;
}
.dialog-body {
  padding: 0.25rem 1.25rem;
}
.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem 1rem;
}
.share-row {
  display: flex;
  gap: 0.5rem;
}
.share-input {
  flex: 1;
  min-width: 0;
  padding: 0.5rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--editor-bg);
  color: var(--fg);
  font: 0.85rem var(--font-mono);
}
.toasts {
  position: fixed;
  left: 50%;
  bottom: 1rem;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(92vw, 540px);
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.6rem 0.9rem;
  background: var(--fg);
  color: var(--bg);
  border-radius: 12px;
  box-shadow: var(--shadow);
  pointer-events: auto;
}
.toast .btn {
  flex: none;
  color: var(--fg);
}

/* ===== Węższe ekrany ===== */
@media (max-width: 860px) {
  .topbar {
    padding: 0.35rem 0.6rem;
  }
  .nav {
    order: 3;
    flex-basis: 100%;
    flex-wrap: nowrap;
    overflow-x: auto;
  }
  .nav-link {
    white-space: nowrap;
  }
  .topbar-actions .btn-label {
