    padding: 0.4rem 0.5rem;
  }
  .toolbar .btn-label {
    font-size: 0.9rem;
  }
  .speed-out {
    display: none;
  }
  .pane-switch {
    display: flex;
  }
  .panes {
    grid-template-columns: 1fr;
  }
  .studio[data-pane="code"] .pane-view,
  .studio[data-pane="view"] .pane-code {
    display: none;
  }
  .pane-code {
    border-right: 0;
  }
  .challenge-panel {
    max-height: 50%;
  }
  .docs-layout {
    grid-template-columns: 1fr;
  }
  .doc-toc {
    position: static;
    max-height: none;
  }
  .viewport-controls .btn-label {
    display: none;
  }
}

@media (pointer: coarse) {
  .editor {
    font-size: 16px;
    line-height: 24px;
  }
  .ln {
    height: 24px;
    line-height: 24px;
  }
  .editor-band {
    height: 24px;
  }
  .editor-input {
    font-size: 16px;
  }
}

@media (max-width: 480px) {
  .toolbar .btn {
    padding: 0.4rem 0.6rem;
  }
  .speed input[type="range"] {
    width: 80px;
  }
  .viewport-controls .btn {
    min-width: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}
