}

/* ===== Pracownia ===== */
.studio {
  height: 100%;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.6rem;
  padding: 0.5rem 0.75rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.toolbar .menu {
  margin-left: auto;
}
.speed {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
}
.speed input[type="range"] {
  width: 110px;
  accent-color: var(--accent);
  min-height: 32px;
}
.speed-out {
  min-width: 9.5ch;
  color: var(--muted);
  font-size: 0.82rem;
}
.mode-switch {
  position: relative;
