  margin: 0;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--surface);
}
.mode-switch input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}
.mode-switch label {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 0.3rem 0.95rem;
  font-weight: 800;
  cursor: pointer;
}
.mode-switch input:checked + label {
