  border-right: 1px solid var(--border);
  color: var(--muted);
  text-align: right;
  user-select: none;
}
.editor-gutter-inner {
  padding: 10px 0.6em 10px 0;
  will-change: transform;
}
.ln {
  display: block;
  height: 22px;
  line-height: 22px;
}
.ln-exec {
  color: var(--accent-text);
  font-weight: 800;
  background: var(--exec-band);
}
.ln-error {
  color: var(--danger);
  font-weight: 800;
}
.ln-error::before {
  content: "●";
  margin-right: 0.35em;
  font-size: 0.7em;
  vertical-align: 0.1em;
}
.editor-scroll {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}
.editor-layer,
.editor-input {
  position: absolute;
  top: 0;
  left: 0;
  margin: 0;
  font: inherit;
  font-variant-ligatures: none;
  letter-spacing: 0;
  tab-size: 2;
  white-space: pre;
  word-break: normal;
  overflow-wrap: normal;
}
.editor-layer {
  min-width: 100%;
  min-height: 100%;
  width: max-content;
  pointer-events: none;
  will-change: transform;
}
.editor-highlight {
