.editor-input::selection {
  background: var(--selection);
  -webkit-text-fill-color: transparent;
}
.editor-band {
  position: absolute;
  left: 0;
  right: 0;
  height: 22px;
}
.exec-band {
  background: var(--exec-band);
  box-shadow: inset 3px 0 0 var(--accent);
}
.error-band {
  background: var(--danger-soft);
  box-shadow: inset 3px 0 0 var(--danger);
}
.tok-command { color: var(--tok-command); font-weight: 650; }
.tok-number { color: var(--tok-number); }
.tok-name { color: var(--tok-name); }
.tok-procedure { color: var(--tok-procedure); font-weight: 650; }
.tok-string { color: var(--tok-string); }
.tok-comment { color: var(--tok-comment); font-style: italic; }
.tok-bracket { color: var(--tok-bracket); font-weight: 700; }
.tok-operator { color: var(--tok-operator); }
.tok-invalid { color: var(--danger); }
.tok-error {
  text-decoration: underline wavy var(--danger);
  text-decoration-thickness: 2px;
  text-underline-offset: 4px;
  background: var(--danger-soft);
}

.statusbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.35rem 0.6rem;
  min-height: 2.9rem;
  padding: 0.45rem 0.8rem;
  background: var(--surface-2);
  border-top: 1px solid var(--border);
  font-size: 0.92rem;
}
.statusbar.is-error {
  background: var(--danger-soft);
  color: var(--danger-fg);
}
.status-text {
  flex: 1 1 14rem;
  min-width: 0;
}
.status-extra {
  flex-basis: 100%;
  font-size: 0.85rem;
  opacity: 0.85;
}

/* ===== Widok rysunku ===== */
.viewport {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  touch-action: none;
}
.viewport-canvas {
  position: absolute;
  inset: 0;
  display: block;
  cursor: grab;
  touch-action: none;
}
.viewport.dragging .viewport-canvas {
  cursor: grabbing;
}
.viewport-canvas:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.viewport-controls {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  max-width: calc(100% - 1rem);
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.3rem;
}
.viewport-controls .btn {
  background: var(--surface);
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.15);
}

/* ===== Panel wyzwania ===== */
.challenge-panel {
  max-height: 46%;
  overflow: auto;
  padding: 0.75rem 1rem;
  background: var(--accent-soft);
  border-bottom: 1px solid var(--border);
}
.challenge-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  flex-wrap: wrap;
}
.challenge-head h2 {
  margin: 0;
  font-size: 1.25rem;
}
.eyebrow {
  margin: 0 0 0.15rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent-text);
}
.challenge-body {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  align-items: flex-start;
}
.challenge-text {
  flex: 1 1 320px;
  min-width: 0;
}
.challenge-text p {
  margin: 0.4rem 0;
}
.challenge-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin: 0.5rem 0;
}
.challenge-figure {
  margin: 0;
  text-align: center;
  font-size: 0.8rem;
  color: var(--muted);
}
.challenge-figure .thumb {
  border: 1px solid var(--border);
  border-radius: 8px;
}
.check {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  cursor: pointer;
}
.check input {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: var(--accent);
}
.challenge-result {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
  margin-top: 0.4rem;
  font-weight: 650;
}
.challenge-result.pass {
  color: var(--ok);
}
.challenge-result.fail {
  color: var(--danger-fg);
}
.badge {
  display: inline-block;
  margin-left: 0.4rem;
  padding: 0.05rem 0.5rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--fg);
  font-size: 0.72rem;
  font-weight: 750;
  vertical-align: middle;
  letter-spacing: 0.02em;
}
.badge.ok {
  background: var(--ok-soft);
  color: var(--ok);
  border-color: var(--ok);
}
.badge.mode-3d {
  background: #e8def5;
  color: #4b2a73;
}
:root[data-theme="dark"] .badge.mode-3d {
  background: #2b1f3d;
  color: #d6b9f5;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .badge.mode-3d {
    background: #2b1f3d;
    color: #d6b9f5;
  }
}

/* ===== Strony ===== */
.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 1.25rem 1rem 3.5rem;
}
.page-head h1 {
  font-size: clamp(1.7rem, 3.5vw, 2.4rem);
  letter-spacing: -0.02em;
}
.page-head h1:focus {
  outline: none;
}
.page-head p {
  max-width: 70ch;
  color: var(--muted);
}
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
}
.card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
}
.card.solved {
  border-color: var(--ok);
}
.card-media {
  display: flex;
  justify-content: center;
  background: var(--editor-bg);
  border-bottom: 1px solid var(--border);
}
.card-body {
  flex: 1;
  padding: 0.75rem 1rem 0.5rem;
}
.card-body h3 {
  margin: 0 0 0.25rem;
  font-size: 1.1rem;
}
.card-body p {
  margin: 0.25rem 0;
  font-size: 0.93rem;
}
.card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.5rem 1rem 1rem;
}
.progress-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.5rem 0 1rem;
}
.progress-summary {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  font-weight: 650;
}
progress {
  width: 200px;
  height: 14px;
  accent-color: var(--accent);
}

/* ===== Dokumentacja ===== */
.docs-layout {
  display: grid;
  grid-template-columns: 230px minmax(0, 1fr);
  gap: 2rem;
  margin-top: 1rem;
}
.doc-toc {
  position: sticky;
  top: 0.75rem;
  align-self: start;
  max-height: calc(100dvh - 8rem);
  overflow: auto;
  padding: 0.75rem 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
}
.doc-toc h2 {
  font-size: 1rem;
}
.doc-toc ol {
  margin: 0;
  padding-left: 1.2rem;
}
.doc-toc li {
  margin: 0.25rem 0;
}
.doc-section {
  margin-bottom: 2.5rem;
  scroll-margin-top: 0.75rem;
}
.doc-section > h2 {
  padding-bottom: 0.3rem;
  border-bottom: 2px solid var(--accent);
  font-size: 1.5rem;
}
.doc-command {
  margin: 1.25rem 0;
  padding: 0.9rem 1rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 5px solid var(--accent);
  border-radius: 12px;
}
.doc-command h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2rem;
  font-size: 1.15rem;
}
.doc-command p {
  margin: 0.3rem 0;
}
.doc-example {
  margin: 0.9rem 0;
  padding: 0.7rem 0.8rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
}
.doc-command .doc-example {
  background: var(--editor-bg);
}
.doc-example figcaption {
  margin-bottom: 0.4rem;
  font-weight: 700;
  font-size: 0.92rem;
}
.doc-example-body {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  align-items: flex-start;
  margin-bottom: 0.6rem;
}
pre.code {
  flex: 1 1 280px;
  min-width: 0;
  margin: 0;
  padding: 0.6rem 0.8rem;
  overflow: auto;
  background: var(--editor-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  font: 13px/1.55 var(--font-mono);
  tab-size: 2;
}
pre.code code {
  padding: 0;
  background: none;
  font: inherit;
}
.doc-example .thumb {
  border: 1px solid var(--border);
  border-radius: 8px;
  flex: none;
}
.doc-error {
  flex: 1 1 240px;
  margin: 0;
  padding: 0.5rem 0.7rem;
  background: var(--danger-soft);
  color: var(--danger-fg);
  border-radius: 8px;
}
.note {
  padding: 0.6rem 0.9rem;
  background: var(--accent-soft);
  border-left: 4px solid var(--accent);
  border-radius: 8px;
}
.table-wrap {
  overflow: auto;
  margin: 0.8rem 0;
}
table {
  border-collapse: collapse;
  width: 100%;
  background: var(--surface);
}
th,
td {
  padding: 0.45rem 0.7rem;
  border: 1px solid var(--border);
  text-align: left;
  vertical-align: top;
}
thead th {
  background: var(--surface-2);
}
.kbd-table th {
  font-weight: 600;
}

/* ===== Menu, okna, komunikaty ===== */
.menu {
  position: relative;
}
.menu-list {
  position: absolute;
  right: 0;
  top: calc(100% + 4px);
  z-index: 30;
  display: flex;
  flex-direction: column;
  min-width: 270px;
  max-width: calc(100vw - 1rem);
  padding: 0.35rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--shadow);
}
.menu-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 0.55rem 0.7rem;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--fg);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.menu-item:hover:not(:disabled),
.menu-item:focus-visible {
  background: var(--accent-soft);
}
.menu-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.menu-item small {
  color: var(--muted);
}
.dialog {
  max-width: min(560px, 92vw);
  padding: 0;
  background: var(--surface);
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: var(--shadow);
}
.dialog.wide {
  max-width: min(760px, 94vw);
}
.dialog::backdrop {
  background: rgb(0 0 0 / 0.5);
}
.dialog-title {
  margin: 0;
  padding: 1rem 1.25rem 0.25rem;
  font-size: 1.2rem;
}
.dialog-body {
  padding: 0.25rem 1.25rem;
}
.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem 1rem;
}
.share-row {
  display: flex;
  gap: 0.5rem;
}
.share-input {
  flex: 1;
  min-width: 0;
  padding: 0.5rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--editor-bg);
  color: var(--fg);
  font: 0.85rem var(--font-mono);
}
.toasts {
  position: fixed;
  left: 50%;
  bottom: 1rem;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: min(92vw, 540px);
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.6rem 0.9rem;
  background: var(--fg);
  color: var(--bg);
  border-radius: 12px;
  box-shadow: var(--shadow);
  pointer-events: auto;
}
.toast .btn {
  flex: none;
  color: var(--fg);
}

/* ===== Węższe ekrany ===== */
@media (max-width: 860px) {
  .topbar {
    padding: 0.35rem 0.6rem;
  }
  .nav {
    order: 3;
    flex-basis: 100%;
    flex-wrap: nowrap;
    overflow-x: auto;
  }
  .nav-link {
    white-space: nowrap;
  }
  .topbar-actions .btn-label {
    display: none;
  }
  .toolbar {
    gap: 0.4rem;
    padding: 0.4rem 0.5rem;
  }
  .toolbar .btn-label {
    font-size: 0.9rem;
  }
  .speed-out {
    display: none;
  }
  .pane-switch {
    display: flex;
  }
  .panes {
    grid-template-columns: 1fr;
  }
  .studio[data-pane="code"] .pane-view,
  .studio[data-pane="view"] .pane-code {
    display: none;
  }
  .pane-code {
    border-right: 0;
  }
  .challenge-panel {
    max-height: 50%;
  }
  .docs-layout {
    grid-template-columns: 1fr;
  }
  .doc-toc {
    position: static;
    max-height: none;
  }
  .viewport-controls .btn-label {
    display: none;
  }
}

@media (pointer: coarse) {
  .editor {
    font-size: 16px;
    line-height: 24px;
  }
  .ln {
    height: 24px;
    line-height: 24px;
  }
  .editor-band {
    height: 24px;
  }
  .editor-input {
    font-size: 16px;
  }
}

@media (max-width: 480px) {
  .toolbar .btn {
    padding: 0.4rem 0.6rem;
  }
  .speed input[type="range"] {
    width: 80px;
  }
  .viewport-controls .btn {
    min-width: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}
EOF
