mkdir -p /tmp/shots && cat > /tmp/dom-smoke/scripts/render.ts <<'EOF'
import { createCanvas } from "/tmp/dom-smoke/node_modules/@napi-rs/canvas/index.js";
import { writeFileSync } from "node:fs";
import { EXAMPLES } from "/work/src/app/examples";
import { run, startSession } from "/work/src/lang";
import { boundsOf } from "/work/src/view/bounds";
import { fitCamera2D } from "/work/src/view/camera2d";
import { defaultCamera3D, fitCamera3D, topView } from "/work/src/view/camera3d";
import { DARK_PALETTE, LIGHT_PALETTE } from "/work/src/view/palette";
import { drawScene2D } from "/work/src/view/render2d";
import { drawScene3D } from "/work/src/view/render3d";

const W = 900, H = 600;
const only = process.argv[2];
for (const theme of ["light", "dark"] as const) {
  const pal = theme === "dark" ? DARK_PALETTE : LIGHT_PALETTE;
  for (const ex of EXAMPLES) {
    if (only && ex.id !== only) continue;
    const s = startSession(ex.source, ex.mode);
    if (!s.ok) throw new Error(ex.id);
    while (s.session.step());
    const segments = s.session.segments;
    const turtle = s.session.turtle;
    const canvas = createCanvas(W, H);
    const ctx = canvas.getContext("2d") as unknown as CanvasRenderingContext2D;
    const b = boundsOf(segments);
    if (b) for (let k = 0; k < 3; k++) { b.min[k] = Math.min(b.min[k], turtle.position[k]); b.max[k] = Math.max(b.max[k], turtle.position[k]); }
    const scene = { segments, turtle, showTurtle: true };
    if (ex.mode === "2d") drawScene2D(ctx, fitCamera2D(b, W, H), W, H, scene, pal);
    else {
      const extent = Math.max(100, ...b!.min.map(Math.abs), ...b!.max.map(Math.abs));
      drawScene3D(ctx, fitCamera3D(b, W, H, defaultCamera3D()), W, H, scene, pal, extent);
    }
    writeFileSync(`/tmp/shots/${ex.id}-${theme}.png`, canvas.toBuffer("image/png"));
  }
}
console.log("ok");
EOF
