import { watch } from "node:fs";
import { file } from "bun";
import { build, normalizeBase } from "./build";

/** Serwer deweloperski: buduje do dist/ i serwuje go, przebudowując po zmianach w src/. */
const base = normalizeBase(process.env.BASE_PATH);
const port = Number(process.env.PORT ?? 3000);

let building: Promise<void> = build(base).catch((e) => console.error(e));
let timer: ReturnType<typeof setTimeout> | undefined;
for (const dir of ["src", "public"]) {
  watch(dir, { recursive: true }, () => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      building = build(base).catch((e) => console.error(e));
    }, 150);
  });
}
watch("index.html", () => {
  building = build(base).catch((e) => console.error(e));
});

Bun.serve({
  port,
  async fetch(req) {
    await building;
    const { pathname } = new URL(req.url);
    if (!pathname.startsWith(base)) return Response.redirect(base, 302);
    const rel = pathname.slice(base.length) || "index.html";
    const f = file(`dist/${rel}`);
    return (await f.exists()) ? new Response(f) : new Response("404", { status: 404 });
  },
});
console.log(`Logomocja: http://localhost:${port}${base}`);
EOF
