/** Forma liczby mnogiej po polsku: [1, 2–4, reszta] (z wyjątkiem 12–14). */
export function pluralize(n: number, forms: readonly [string, string, string]): string {
  if (n === 1) return forms[0];
  const last = n % 10;
  const last2 = n % 100;
  return last >= 2 && last <= 4 && !(last2 >= 12 && last2 <= 14) ? forms[1] : forms[2];
}

export const segmentsLabel = (n: number) => `${n} ${pluralize(n, ["odcinek", "odcinki", "odcinków"])}`;
export const operationsLabel = (n: number) => `${n} ${pluralize(n, ["operacja", "operacje", "operacji"])}`;
EOF
