import { describe, expect, test } from "bun:test";
import { highlight } from "../src/lang/highlight";
import { errorRange, highlightHtml } from "../src/ui/editor";

const render = (text: string, err: [number, number] | null = null, inline?: { offset: number; message: string }) =>
  highlightHtml(text, highlight(text), err, inline);

describe("HTML warstwy podświetlenia edytora", () => {
  test("zwykłe podświetlenie: polecenia i liczby w osobnych spanach, tekst jest ucieczkowany", () => {
    expect(render("np 5 ; a<b")).toBe('<span class="tok-command">np</span> <span class="tok-number">5</span> <span class="tok-comment">; a&lt;b</span>');
  });
  test("zakres błędu dostaje klasę tok-error i dzieli token, jeśli obejmuje jego część", () => {
    const html = render("np 5", [3, 4]);
    expect(html).toBe('<span class="tok-command">np</span> <span class="tok-number tok-error">5</span>');
    const gap = render("ab cd", [1, 4]); // fragment tekstu bez tokenów leksykalnych nie istnieje, ale zakres obejmuje kilka tokenów
    expect(gap).toContain("tok-error");
  });
  test("komunikat błędu pojawia się w tym samym wierszu, na jego końcu, przed znakiem nowego wiersza", () => {
    const text = "np 10\nfoo 5\nnp 1";
    const offset = text.indexOf("\n", 6); // koniec wiersza 2
    const html = render(text, [6, 9], { offset, message: "Nieznane polecenie" });
    const lines = html.split("\n");
    expect(lines).toHaveLength(3);
    expect(lines[1]).toMatch(/<span class="inline-error"[^>]*>.*Nieznane polecenie<\/span>$/);
    expect(lines[0]).not.toContain("inline-error");
    expect(lines[2]).not.toContain("inline-error");
  });
  test("komunikat jest ucieczkowany i działa także w ostatnim wierszu bez znaku nowego wiersza oraz w pustym wierszu", () => {
    const last = render("np 1\nfoo <b>", null, { offset: 12, message: "a < b & c" });
    expect(last.endsWith("a &lt; b &amp; c</span>")).toBe(true);
    const empty = render("np 1\n\nnp 2", null, { offset: 5, message: "pusty" });
    expect(empty.split("\n")[1]).toContain("inline-error");
    expect(empty.split("\n")[0]).not.toContain("inline-error");
  });
});

describe("zakres błędu w edytorze", () => {
  test("błąd na tokenie podkreśla cały token, a na końcu wiersza ostatni znak", () => {
    const text = "np 10\n  foo 5";
    expect(errorRange(text, highlight(text), 2, 3)).toEqual([8, 11]);
    expect(errorRange("np", highlight("np"), 1, 3)).toEqual([1, 2]);
    expect(errorRange("", highlight(""), 1, 1)).toBeNull();
  });
});
EOF
