export function highlightHtml(
  text: string,
  spans: readonly Span[],
  err: [number, number] | null,
  inline?: { offset: number; message: string },
): string {
  type Piece = { start: number; end: number; kind: SpanKind | null };
  const pieces: Piece[] = [];
  let pos = 0;
  for (const s of spans) {
    if (s.start > pos) pieces.push({ start: pos, end: s.start, kind: null });
    pieces.push({ start: s.start, end: s.end, kind: s.kind });
    pos = s.end;
  }
  if (pos < text.length) pieces.push({ start: pos, end: text.length, kind: null });

  // Cięcie kawałków w punktach, w których zmienia się wygląd: początek i koniec błędu oraz koniec wiersza z komunikatem.
  const cuts = [err?.[0], err?.[1], inline?.offset].filter((c): c is number => c !== undefined);
  const cut: Piece[] = [];
