    const bad = !!err && p.start >= err[0] && p.end <= err[1];
    const cls = [p.kind ? `tok-${p.kind}` : "", bad ? "tok-error" : ""].filter(Boolean).join(" ");
    const t = esc(text.slice(p.start, p.end));
    out += cls ? `<span class="${cls}">${t}</span>` : t;
