import { installDom } from "./env";
const { win, log } = installDom();
document.body.innerHTML = '<div id="app"></div>';
const errors: unknown[] = [];
win.addEventListener("error", (e: any) => errors.push(e.error ?? e.message));
process.on("unhandledRejection", (e) => errors.push(e));
const sleep = (ms = 20) => new Promise((r) => setTimeout(r, ms));
const $$ = (sel: string) => [...document.querySelectorAll<HTMLElement>(sel)];
const check = (name: string, ok: boolean, extra = "") => console.log(`${ok ? "OK  " : "FAIL"} ${name} ${extra}`);
await import("/work/src/main.ts");
await sleep(50);
const ta = document.querySelector<HTMLTextAreaElement>(".editor-input")!;
const menuBtn = $$("button").find((b) => b.textContent!.trim().startsWith("Przykłady"))!;
menuBtn.click();
const items = $$("[role=menuitem]");
check("menu Przykłady: 13 pozycji", items.length === 13, String(items.length));
check("pozycje mają nazwy i tryb", items.map((i) => i.querySelector("span")!.textContent).join("|") === "Kwadrat (2D)|Gwiazda (2D)|Rozeta (2D)|Spirala (2D)|Wielokąty (2D)|Drzewo (2D)|Śnieżynka (2D)|Schody (3D)|Sześcian (3D)|Pierścień (3D)|Kula (3D)|Helisa (3D)|Drzewo 3D (3D)", items.map((i) => i.querySelector("span")!.textContent).join("|"));
items.find((i) => i.textContent!.startsWith("Kula"))!.click();
await sleep(60);
check("Kula wczytana w trybie 3D", ta.value.includes("Dwanaście okręgów") && (document.getElementById("mode-3d") as HTMLInputElement).checked);
check("status po wczytaniu", document.querySelector(".statusbar")!.textContent!.includes("432 odcinki"), document.querySelector(".statusbar")!.textContent ?? "");
// własny szkic 3D, potem inny przykład -> dialog
ta.value = "gora 10 np 1 ; moje";
ta.dispatchEvent(new win.Event("input", { bubbles: true }));
await sleep(20);
menuBtn.click();
$$("[role=menuitem]").find((i) => i.textContent!.startsWith("Helisa"))!.click();
await sleep(40);
check("własny szkic 3D chroniony dialogiem", !!document.querySelector("dialog[open]"));
$$("dialog button").find((b) => b.textContent === "Anuluj")!.click();
await sleep(30);
check("szkic bez zmian po Anuluj", ta.value === "gora 10 np 1 ; moje");
// błąd inline
ta.value = "np 10\nfoo 5";
ta.dispatchEvent(new win.Event("input", { bubbles: true }));
await sleep(300);
check("komunikat inline w warstwie podświetlenia", document.querySelector(".inline-error")?.textContent?.includes("Nieznane polecenie") === true, document.querySelector(".inline-error")?.textContent ?? "");
console.log("errors:", errors, "bad:", log.bad.length);
EOF
cd /tmp/dom-smoke && bun run scripts/smoke4.ts 2>&1 | head -20

