export type TokenKind = "num" | "word" | "ma" | "colon" | "comma" | "str" | "bad" | "lbr" | "rbr" | "op" | "cmp" | "lpar" | "rpar";

export interface Token {
  kind: TokenKind;
  /** Tekst źródłowy tokenu. */
  text: string;
  /** Wartość liczbowa dla liczb. */
  num: number;
  /** Nazwa bez rozróżniania wielkości liter (małe litery, NFC) dla słów i :nazw. */
  name: string;
  line: number;
  col: number;
  /** Przesunięcie początku tokenu w tekście źródłowym. */
  start: number;
  /** Czy to pierwszy / ostatni token w swoim wierszu. */
  first: boolean;
  last: boolean;
  /** Czy bezpośrednio przed / po tokenie stoi biały znak (lub początek / koniec tekstu). */
  wsBefore: boolean;
  wsAfter: boolean;
}

export function scan(source: string): Token[] {
  const tokens: Token[] = [];
  let line = 1;
  let lineStart = 0;
  let i = 0;
  const add = (kind: TokenKind, start: number, end: number, num = NaN) => {
    const isSpace = (k: number) => k < 0 || k >= source.length || /\s|;/.test(source[k]);
    tokens.push({
      kind,
      text: source.slice(start, end),
      num,
      name: "",
      line,
      col: start - lineStart + 1,
      start,
      first: false,
      last: false,
      wsBefore: isSpace(start - 1),
      wsAfter: isSpace(end),
    });
  };
  while (i < source.length) {
    const ch = source[i];
    if (ch === "\n") {
      line++;
      i++;
      lineStart = i;
    } else if (ch === ";") {
      while (i < source.length && source[i] !== "\n") i++;
    } else if (/\s/.test(ch)) {
      i++;
    } else if (ch === "[" || ch === "]") {
      add(ch === "[" ? "lbr" : "rbr", i, i + 1);
      i++;
    } else if (ch === ",") {
      add("comma", i, i + 1);
      i++;
    } else if (ch === "(" || ch === ")") {
      add(ch === "(" ? "lpar" : "rpar", i, i + 1);
      i++;
    } else if (ch === "+" || ch === "-" || ch === "*" || ch === "/") {
      add("op", i, i + 1);
      i++;
    } else if (ch === "<" || ch === ">" || ch === "=") {
      const two = source.slice(i, i + 2);
      const len = two === "<=" || two === ">=" || two === "<>" ? 2 : 1;
      add("cmp", i, i + len);
      i += len;
    } else if (ch === ":") {
      const start = i;
      i++;
      while (i < source.length && /[\p{L}\p{M}\p{N}_]/u.test(source[i])) i++;
      add("colon", start, i);
      tokens[tokens.length - 1].name = source.slice(start + 1, i).normalize("NFC").toLowerCase();
    } else if (ch === '"') {
      const start = i;
      i++;
      while (i < source.length && source[i] !== '"' && source[i] !== "\n") i++;
      if (source[i] === '"') i++;
      add("str", start, i);
    } else if (/[0-9.]/.test(ch)) {
      const start = i;
      while (i < source.length && /[\p{L}\p{N}_.]/u.test(source[i])) i++;
      const text = source.slice(start, i);
      if (/^(\d+(\.\d+)?|\.\d+)$/.test(text)) add("num", start, i, Number(text));
      else add("bad", start, i);
    } else {
      const start = i;
      while (i < source.length && /[\p{L}\p{M}\p{N}_]/u.test(source[i])) i++;
      if (i === start) {
        i++;
        add("bad", start, i);
        continue;
      }
      const name = source.slice(start, i).normalize("NFC").toLowerCase();
      if (name === "ma" && source[i] === ":") {
        i++;
        add("ma", start, i);
      } else {
        add("word", start, i);
      }
      tokens[tokens.length - 1].name = name;
    }
  }
  for (let k = 0; k < tokens.length; k++) {
    tokens[k].first = k === 0 || tokens[k - 1].line !== tokens[k].line;
    tokens[k].last = k === tokens.length - 1 || tokens[k + 1].line !== tokens[k].line;
  }
  return tokens;
}

