import { describe, expect, test } from "bun:test";
import { run, startSession, type Mode } from "../src/lang";

// ---------- generator programów poprawnych z konstrukcji ----------
function rng(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Odpowiedniki słów (z ogonkami i bez, polskie i angielskie), niezależne od słownika interpretera. */
const ALIASES: Record<string, string[]> = {
  fd: ["np", "naprzod", "naprzód", "fd", "forward"],
  bk: ["ws", "wstecz", "bk", "back"],
  rt: ["pw", "prawo", "rt", "right"],
  lt: ["lw", "lewo", "lt", "left"],
  pu: ["pod", "podnies", "podnieś", "pu", "penup"],
  pd: ["opu", "opusc", "opuść", "pd", "pendown"],
  color: ["kolor", "color"],
  width: ["grubosc", "grubość", "width"],
  repeat: ["powtorz", "powtórz", "repeat"],
  let: ["niech", "let"],
  if: ["jeśli", "jesli", "if"],
  ifelse: ["jeżeli", "jezeli", "ifelse"],
  stop: ["stop"],
  home: ["dom", "home"],
  cs: ["czyść", "czysc", "cs", "clearscreen"],
  rep: ["nrpowt", "repcount"],
  to: ["oto", "to"],
  end: ["już", "juz", "end"],
  pitchup: ["gora", "góra", "pitchup"],
  pitchdown: ["dol", "dół", "pitchdown"],
  rollr: ["pp", "przechylprawo", "rr", "rollright"],
  rolll: ["pl", "przechyllewo", "rl", "rolllleft"],
};
ALIASES.rolll = ["pl", "przechyllewo", "rl", "rollleft"];

type Part = string | { w: keyof typeof ALIASES } | { v: string }; // słowo kluczowe, nazwa
type Gen = { parts: Part[] };

function generate(rand: () => number, spatial: boolean): Gen {
  const parts: Part[] = [];
  const pick = <T,>(xs: T[]) => xs[Math.floor(rand() * xs.length)];
  const int = (a: number, b: number) => a + Math.floor(rand() * (b - a + 1));
  const w = (k: keyof typeof ALIASES) => parts.push({ w: k });
  const t = (s: string) => parts.push(s);
  const nl = () => parts.push("\n");
  const procs: { name: string; arity: number }[] = [];

  const expr = (vars: string[], inRepeat: boolean, depth = 0): void => {
    const leaf = () => {
      const r = rand();
      if (r < 0.5 || (vars.length === 0 && !inRepeat)) t(String(pick([0, 1, 2, 5, 10, 25, 40, 7.5, 0.5, 90])));
      else if (r < 0.8 && vars.length) parts.push({ v: pick(vars) });
      else if (inRepeat) w("rep");
      else t("3");
    };
    if (depth > 1 || rand() < 0.45) return leaf();
    const kind = rand();
    if (kind < 0.25) {
      t("(");
      expr(vars, inRepeat, depth + 1);
      t(" + ");
      expr(vars, inRepeat, depth + 1);
      t(")");
    } else if (kind < 0.4) {
      t("-");
      leaf();
    } else {
      leaf();
      t(pick([" + ", " - ", " * "]));
      expr(vars, inRepeat, depth + 1);
    }
    if (rand() < 0.15) {
      t(" / ");
      t(String(int(1, 9)));
    }
  };
  // Nie dzielimy wyniku przez zero: dzielnik to zawsze literał 1–9. Wartości są niewielkie, więc limity nie wystąpią.

  const cond = (vars: string[], inRepeat: boolean) => {
    expr(vars, inRepeat, 1);
    t(pick([" < ", " > ", " = ", " <= ", " >= ", " <> ", "<", ">=", "<>"]));
    expr(vars, inRepeat, 1);
  };

  const block = (vars: string[], inRepeat: boolean, inProc: boolean, depth: number, size: number): void => {
    const local = [...vars];
    for (let k = 0; k < size; k++) statement(local, inRepeat, inProc, depth);
  };

  const statement = (vars: string[], inRepeat: boolean, inProc: boolean, depth: number): void => {
    const r = rand();
    const sep = () => (rand() < 0.2 ? nl() : t(" "));
    if (r < 0.22) {
      w("fd"); t(" "); expr(vars, inRepeat); sep();
    } else if (r < 0.28) {
      w("bk"); t(" "); expr(vars, inRepeat); sep();
    } else if (r < 0.42) {
      w(pick(["rt", "lt"] as const)); t(" "); expr(vars, inRepeat); sep();
    } else if (r < 0.47) {
      w(pick(["pu", "pd"] as const)); sep();
    } else if (r < 0.52) {
      w("color"); t(` "#${pick(["16866a", "C1763D", "2b6fb3", "a478C0"])}" `); sep();
    } else if (r < 0.56) {
      w("width"); t(` ${int(1, 12)} `); sep();
    } else if (r < 0.64 && depth < 3) {
      w("repeat"); t(` ${int(0, 4)} [`); nl();
      block(vars, true, inProc, depth + 1, int(1, 3));
      t("] "); sep();
    } else if (r < 0.72 && depth < 3) {
      const ifelse = rand() < 0.5;
      w(ifelse ? "ifelse" : "if"); t(" "); cond(vars, inRepeat); t(" [");
      block(vars, inRepeat, inProc, depth + 1, int(1, 2));
      t("]");
      if (ifelse) {
        t(" [");
        block(vars, inRepeat, inProc, depth + 1, int(1, 2));
        t("]");
      }
      sep();
    } else if (r < 0.8) {
      const name = pick(["x", "y", "Zmiana", "dł", "bok2"]);
      w("let"); t(" "); parts.push({ v: name }); t(" "); expr(vars, inRepeat); sep();
      if (depth === 0 && !vars.includes(name.toLowerCase())) vars.push(name.toLowerCase());
    } else if (r < 0.86 && procs.length) {
      const p = pick(procs);
      parts.push({ v: p.name });
      for (let k = 0; k < p.arity; k++) {
        t(" ");
        expr(vars, inRepeat);
      }
      sep();
    } else if (r < 0.9) {
      w("home"); sep();
    } else if (r < 0.92) {
      w("cs"); sep();
    } else if (r < 0.95 && inProc) {
      w("if"); t(" "); cond(vars, inRepeat); t(" ["); w("stop"); t("] "); sep();
    } else if (spatial && r < 0.975) {
      w(pick(["pitchup", "pitchdown", "rollr", "rolll"] as const)); t(" "); expr(vars, inRepeat); sep();
    } else {
      w("fd"); t(" 5 ");
