import { afterEach, describe, expect, test } from "bun:test";
import { createBrowserStore, createMemoryStore, safeGet, safeSet } from "../src/app/storage";

const g = globalThis as { localStorage?: unknown };
const original = Object.getOwnPropertyDescriptor(globalThis, "localStorage");

afterEach(() => {
  if (original) Object.defineProperty(globalThis, "localStorage", original);
  else delete g.localStorage;
});

describe("magazyn lokalny", () => {
  test("pamięciowy magazyn zachowuje się jak localStorage (null dla brakującego klucza)", () => {
    const s = createMemoryStore({ a: "1" });
    expect(s.getItem("a")).toBe("1");
    expect(s.getItem("b")).toBeNull();
    s.setItem("b", "2");
    s.removeItem("a");
    expect([s.getItem("a"), s.getItem("b")]).toEqual([null, "2"]);
  });
  test("gdy localStorage jest zablokowany (wyjątek przy dostępie), aplikacja dostaje działający magazyn w pamięci", () => {
    Object.defineProperty(globalThis, "localStorage", {
      configurable: true,
      get() {
        throw new Error("SecurityError: dostęp zablokowany");
      },
    });
    const store = createBrowserStore();
    store.setItem("k", "v");
    expect(store.getItem("k")).toBe("v");
  });
  test("gdy zapis do localStorage się nie udaje (np. brak miejsca), magazyn przechodzi na pamięć", () => {
    const failing = {
      getItem: () => null,
      setItem: () => {
        throw new Error("QuotaExceededError");
      },
      removeItem: () => {},
    };
    Object.defineProperty(globalThis, "localStorage", { configurable: true, value: failing });
    const store = createBrowserStore();
    store.setItem("k", "v");
