import re, glob
css = open('src/styles.css').read()
css_classes = set(re.findall(r'\.([a-zA-Z][\w-]*)', css))
used = {}
for f in glob.glob('src/**/*.ts', recursive=True):
    s = open(f).read()
    for m in re.finditer(r'class:\s*"([^"]+)"', s):
        for c in m.group(1).split():
            used.setdefault(c, set()).add(f.split('/')[-1])
    for m in re.finditer(r'class:\s*`([^`]+)`', s):
        for c in re.sub(r'\$\{[^}]*\}', ' ', m.group(1)).split():
            used.setdefault(c, set()).add(f.split('/')[-1])
    for m in re.finditer(r'classList\.(?:add|toggle)\("([^"]+)"', s):
        used.setdefault(m.group(1), set()).add(f.split('/')[-1])
missing = sorted(c for c in used if c not in css_classes)
print("klasy używane w TS bez reguły w CSS:", missing)
unused = sorted(c for c in css_classes if c not in used and not c.startswith(('tok-','ln-','mode-','is-')))
